import { useState, useRef, useCallback } from 'react';
import {
  X,
  Upload,
  FileText,
  Type,
  FileUp,
  Loader2,
  CheckCircle2,
  AlertCircle,
  Trash2,
  RefreshCw,
} from 'lucide-react';
import { useArticleStore } from '@/stores/articleStore';
import { useSettingsStore } from '@/stores/settingsStore';
import type { Category } from '@/types';
import { parseFile, isSupportedFile, SUPPORTED_EXTENSIONS } from '@/utils/fileParser';
import type { Article, Language } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import { cn } from '@/lib/utils';

interface ImportModalProps {
  isOpen: boolean;
  onClose: () => void;
}

type UploadStatus = 'idle' | 'parsing' | 'success' | 'error';

interface PendingFile {
  name: string;
  size: number;
  content: string;
  fileType: string;
}

export default function ImportModal({ isOpen, onClose }: ImportModalProps) {
  const { addArticle, categories, addCategory } = useArticleStore();
  const { settings } = useSettingsStore();

  // Form state
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [targetLanguage, setTargetLanguage] = useState<Language>(settings.defaultTargetLanguage);
  const [categoryId, setCategoryId] = useState('default');
  const [customCategoryName, setCustomCategoryName] = useState('');
  const [showCustomInput, setShowCustomInput] = useState(false);
  const [importMethod, setImportMethod] = useState<'paste' | 'new' | 'file'>('paste');

  // Upload state
  const [isDragOver, setIsDragOver] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<UploadStatus>('idle');
  const [uploadError, setUploadError] = useState('');
  const [pendingFiles, setPendingFiles] = useState<PendingFile[]>([]);
  // 解析进度
  const [parseProgress, setParseProgress] = useState(0);
  const [parseProgressText, setParseProgressText] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const dropZoneRef = useRef<HTMLDivElement>(null);

  // ─── File handling ──────────────────────────────────────────────
  const handleFiles = useCallback(async (files: FileList | File[]) => {
    const fileArray = Array.from(files);
    const validFiles = fileArray.filter(isSupportedFile);

    if (validFiles.length === 0) {
      setUploadError(`不支持的文件格式，仅支持 ${SUPPORTED_EXTENSIONS.join('、')}`);
      setUploadStatus('error');
      return;
    }

    setUploadStatus('parsing');
    setUploadError('');
    setParseProgress(0);
    setParseProgressText('准备解析...');

    const parsed: PendingFile[] = [];
    const failedFiles: string[] = [];
    const total = validFiles.length;

    for (let i = 0; i < validFiles.length; i++) {
      const file = validFiles[i];
      const percent = Math.round(((i + 1) / total) * 100);
      setParseProgress(percent);
      setParseProgressText(`正在解析 ${i + 1}/${total}：${file.name}`);

      try {
        const result = await parseFile(file);
        parsed.push({
          name: result.title,
          size: file.size,
          content: result.content,
          fileType: result.fileType,
        });
      } catch {
        failedFiles.push(file.name);
      }
    }

    if (parsed.length === 0) {
      setUploadError(
        failedFiles.length > 0
          ? `解析失败：${failedFiles.join('、')}`
          : '文件解析失败，请检查文件是否损坏'
      );
      setUploadStatus('error');
      setParseProgress(0);
      return;
    }

    setPendingFiles(parsed);
    setParseProgress(100);
    setParseProgressText(`已完成 ${parsed.length}/${total}${failedFiles.length > 0 ? `（${failedFiles.length} 个失败）` : ''}`);

    // Auto-fill first file
    if (parsed.length > 0 && !title) {
      setTitle(parsed[0].name);
    }
    if (parsed.length === 1) {
      setContent(parsed[0].content);
    } else {
      setContent(parsed.map((f) => f.content).join('\n\n---\n\n'));
    }

    setUploadStatus('success');
  }, [title]);

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      handleFiles(e.target.files);
      e.target.value = '';
    }
  };

  // ─── Drag & Drop ─────────────────────────────────────────────────
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragOver(false);
    if (e.dataTransfer.files) {
      handleFiles(e.dataTransfer.files);
    }
  };

  // ─── Submit ──────────────────────────────────────────────────────
  const handleSubmit = () => {
    if (!content.trim() || !title.trim()) return;

    if (pendingFiles.length > 1) {
      // Batch import
      pendingFiles.forEach((file) => {
        const article: Article = {
          id: crypto.randomUUID(),
          title: file.name,
          content: file.content,
          sourceLanguage: 'zh',
          targetLanguage,
          categoryId,
          createdAt: Date.now(),
          updatedAt: Date.now(),
          tags: [],
        };
        addArticle(article);
      });
    } else {
      const article: Article = {
        id: crypto.randomUUID(),
        title: title.trim(),
        content: content.trim(),
        sourceLanguage: 'zh',
        targetLanguage,
        categoryId,
        createdAt: Date.now(),
        updatedAt: Date.now(),
        tags: [],
      };
      addArticle(article);
    }

    onClose();
    resetForm();
  };

  const resetForm = () => {
    setTitle('');
    setContent('');
    setPendingFiles([]);
    setUploadStatus('idle');
    setUploadError('');
    setParseProgress(0);
    setParseProgressText('');
    setImportMethod('paste');
    setCategoryId('default');
    setCustomCategoryName('');
    setShowCustomInput(false);
  };

  const handleCategoryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const value = e.target.value;
    if (value === '__custom__') {
      setShowCustomInput(true);
      setCategoryId('default');
    } else {
      setShowCustomInput(false);
      setCategoryId(value);
    }
  };

  const handleAddCustomCategory = () => {
    const name = customCategoryName.trim();
    if (!name) return;

    const newCategory: Category = {
      id: crypto.randomUUID(),
      name,
      icon: '📁',
      articleCount: 0,
    };
    addCategory(newCategory);
    setCategoryId(newCategory.id);
    setShowCustomInput(false);
    setCustomCategoryName('');
  };

  const handleClose = () => {
    onClose();
    resetForm();
  };

  // ─── Helpers ─────────────────────────────────────────────────────
  const formatSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const fileIcon = (type: string) => {
    switch (type) {
      case 'txt': return '📄';
      case 'docx': return '📝';
      case 'pdf': return '📕';
      default: return '📎';
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={handleClose}>
      <div
        className="modal-content max-w-2xl w-full"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-lg font-bold text-gray-800 dark:text-gray-100">
            导入文章
          </h2>
          <button
            onClick={handleClose}
            className="w-7 h-7 rounded-lg flex items-center justify-center hover:bg-gray-100 dark:hover:bg-slate-700 text-gray-400 hover:text-gray-600 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Method tabs */}
        <div className="flex gap-2 mb-5">
          {[
            { key: 'paste' as const, icon: Type, label: '粘贴文本' },
            { key: 'new' as const, icon: FileText, label: '新建空白' },
            { key: 'file' as const, icon: Upload, label: '上传文档' },
          ].map(({ key, icon: Icon, label }) => (
            <button
              key={key}
              onClick={() => {
                setImportMethod(key);
                if (key !== 'file') {
                  setUploadStatus('idle');
                  setPendingFiles([]);
                }
              }}
              className={cn(
                'flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-medium transition-all',
                importMethod === key
                  ? 'bg-primary-50 dark:bg-primary-950 text-primary-700 dark:text-primary-300 ring-1 ring-primary-200 dark:ring-primary-800'
                  : 'text-gray-500 hover:bg-gray-50 dark:hover:bg-slate-700'
              )}
            >
              <Icon className="w-4 h-4" />
              {label}
            </button>
          ))}
        </div>

        {/* ─── Upload Zone ─────────────────────────────────────────── */}
        {importMethod === 'file' && (
          <div className="mb-5">
            <div
              ref={dropZoneRef}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
              className={cn(
                'relative border-2 border-dashed rounded-2xl p-8 text-center cursor-pointer transition-all duration-200',
                isDragOver
                  ? 'border-primary-400 bg-primary-50 dark:bg-primary-950 scale-[1.01]'
                  : uploadStatus === 'error'
                  ? 'border-red-300 bg-red-50 dark:bg-red-950'
                  : uploadStatus === 'success'
                  ? 'border-green-300 bg-green-50 dark:bg-green-950'
                  : 'border-gray-200 dark:border-gray-600 hover:border-primary-300 hover:bg-primary-50/50 dark:hover:bg-primary-950/50'
              )}
            >
              <input
                ref={fileInputRef}
                type="file"
                accept=".txt,.docx,.pdf"
                multiple
                className="hidden"
                onChange={handleFileInput}
              />

              {uploadStatus === 'parsing' ? (
                <div className="flex flex-col items-center gap-3 w-full">
                  <Loader2 className="w-10 h-10 text-primary-500 animate-spin" />
                  <p className="text-sm font-medium text-gray-700 dark:text-gray-200">
                    {parseProgressText || '正在解析文件...'}
                  </p>
                  <div className="w-full max-w-xs h-2 rounded-full bg-white/60 dark:bg-slate-800/60 overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-primary-400 to-accent-400 transition-all duration-300 ease-out rounded-full"
                      style={{ width: `${parseProgress}%` }}
                    />
                  </div>
                  <p className="text-xs text-gray-400 tabular-nums">{parseProgress}%</p>
                </div>
              ) : uploadStatus === 'error' ? (
                <div className="flex flex-col items-center gap-3">
                  <AlertCircle className="w-10 h-10 text-red-400" />
                  <p className="text-sm font-medium text-red-600 dark:text-red-400">
                    {uploadError}
                  </p>
                  <button
                    onClick={() => fileInputRef.current?.click()}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 text-xs font-medium hover:bg-red-200 dark:hover:bg-red-900/60 transition-colors"
                  >
                    <RefreshCw className="w-3.5 h-3.5" />
                    重试
                  </button>
                  <p className="text-xs text-gray-400">点击重试或拖拽文件到此处</p>
                </div>
              ) : uploadStatus === 'success' ? (
                <div className="flex flex-col items-center gap-3">
                  <CheckCircle2 className="w-10 h-10 text-green-500" />
                  <p className="text-sm font-medium text-green-700 dark:text-green-400">
                    解析成功！{pendingFiles.length} 个文件已就绪
                  </p>
                  <p className="text-xs text-gray-400">
                    可继续拖拽添加更多文件，或点击下方区域修改内容
                  </p>
                </div>
              ) : (
                <div className="flex flex-col items-center gap-3">
                  <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-primary-100 to-accent-100 dark:from-primary-900 dark:to-accent-900 flex items-center justify-center">
                    <FileUp className="w-6 h-6 text-primary-600 dark:text-primary-400" />
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-700 dark:text-gray-200">
                      拖拽文件到此处，或{' '}
                      <span className="text-primary-600 dark:text-primary-400 underline underline-offset-2">
                        点击选择文件
                      </span>
                    </p>
                    <p className="text-xs text-gray-400 mt-1">
                      支持 {SUPPORTED_EXTENSIONS.join('、')} 格式，可多选
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* Pending files list */}
            {pendingFiles.length > 0 && (
              <div className="mt-3 space-y-1.5 max-h-32 overflow-y-auto scrollbar-thin">
                {pendingFiles.map((file, idx) => (
                  <div
                    key={idx}
                    className="flex items-center gap-2 px-3 py-2 rounded-xl bg-gray-50 dark:bg-slate-700/50 text-sm"
                  >
                    <span className="text-base">{fileIcon(file.fileType)}</span>
                    <span className="flex-1 truncate text-gray-700 dark:text-gray-200 text-xs">
                      {file.name}
                    </span>
                    <span className="text-[11px] text-gray-400 shrink-0">
                      {formatSize(file.size)}
                    </span>
                    <button
                      onClick={() => {
                        const updated = pendingFiles.filter((_, i) => i !== idx);
                        setPendingFiles(updated);
                        if (updated.length === 0) {
                          setUploadStatus('idle');
                          setContent('');
                          setTitle('');
                        } else if (updated.length === 1) {
                          setContent(updated[0].content);
                          setTitle(updated[0].name);
                        }
                      }}
                      className="text-gray-400 hover:text-red-500 transition-colors"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ─── Form fields ─────────────────────────────────────────── */}
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
              文章标题
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="输入文章标题..."
              className="input-field"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                目标语种
              </label>
              <select
                value={targetLanguage}
                onChange={(e) => setTargetLanguage(e.target.value as Language)}
                className="input-field"
              >
                {Object.entries(LANGUAGE_NAMES).map(([key, name]) => (
                  <option key={key} value={key}>
                    {name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                分类
              </label>
              <select
                value={showCustomInput ? '__custom__' : categoryId}
                onChange={handleCategoryChange}
                className="input-field"
              >
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>
                    {cat.icon} {cat.name}
                  </option>
                ))}
                <option value="__custom__">+ 新建分类</option>
              </select>

              {showCustomInput && (
                <div className="mt-2 flex gap-2">
                  <input
                    type="text"
                    value={customCategoryName}
                    onChange={(e) => setCustomCategoryName(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleAddCustomCategory();
                      }
                    }}
                    placeholder="输入新分类名称..."
                    className="input-field flex-1 text-sm"
                    autoFocus
                  />
                  <button
                    onClick={handleAddCustomCategory}
                    disabled={!customCategoryName.trim()}
                    className="btn-primary text-sm whitespace-nowrap disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    添加
                  </button>
                </div>
              )}
            </div>
          </div>

          {importMethod !== 'new' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">
                文章内容
                {content && (
                  <span className="ml-2 text-xs text-gray-400 font-normal">
                    {content.length} 字
                  </span>
                )}
              </label>
              <textarea
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder={
                  importMethod === 'file'
                    ? '上传文件后内容将自动填充，也可在此手动修改...'
                    : '在此粘贴或输入文章内容...'
                }
                rows={8}
                className="input-field resize-y min-h-[180px]"
              />
            </div>
          )}
        </div>

        {/* ─── Actions ─────────────────────────────────────────────── */}
        <div className="flex justify-between items-center mt-6 pt-4 border-t border-gray-100 dark:border-gray-700">
          <div className="text-xs text-gray-400">
            {pendingFiles.length > 1 && (
              <span>将批量导入 {pendingFiles.length} 篇文章</span>
            )}
          </div>
          <div className="flex gap-3">
            <button onClick={handleClose} className="btn-secondary">
              取消
            </button>
            <button
              onClick={handleSubmit}
              className="btn-primary"
              disabled={!title.trim() || !content.trim()}
            >
              {pendingFiles.length > 1 ? '批量导入学习' : '导入学习'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}