import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, FolderOpen, Trash2, Grid3X3, List } from 'lucide-react';
import { useArticleStore } from '@/stores/articleStore';
import { useUIStore } from '@/stores/uiStore';
import ArticleCard from '@/components/ArticleCard';
import ImportModal from '@/components/ImportModal';
import EmptyState from '@/components/EmptyState';
import BackButton from '@/components/BackButton';
import { ConfirmDialog, useConfirm } from '@/components/ConfirmDialog';
import { cn } from '@/lib/utils';

export default function ArticlesPage() {
  const navigate = useNavigate();
  const { articles, categories, deleteArticle, deleteCategory } = useArticleStore();
  const { setSelectedLanguage } = useUIStore();
  const { state: confirmState, confirm, handleConfirm, handleCancel } = useConfirm();
  const [showImport, setShowImport] = useState(false);
  const [activeCategory, setActiveCategory] = useState('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredArticles = activeCategory === 'all'
    ? articles
    : articles.filter((a) => a.categoryId === activeCategory);

  const activeCatName = activeCategory === 'all'
    ? '全部文章'
    : categories.find((c) => c.id === activeCategory)?.name ?? '未知分类';

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
      <BackButton />

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
        <div>
          <h1 className="text-xl font-bold text-gray-800 dark:text-gray-100">文章管理</h1>
          <p className="text-sm text-gray-500 mt-0.5">
            {activeCatName} · 共 {filteredArticles.length} 篇
          </p>
        </div>
        <button onClick={() => setShowImport(true)} className="btn-primary self-start sm:self-auto">
          <Plus className="w-4 h-4" />
          导入文章
        </button>
      </div>

      {/* Category tabs - mobile & desktop unified */}
      <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-1 scrollbar-thin">
        <button
          onClick={() => setActiveCategory('all')}
          className={cn(
            'px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-colors',
            activeCategory === 'all'
              ? 'bg-primary-100 text-primary-700 dark:bg-primary-900 dark:text-primary-300'
              : 'bg-gray-100 text-gray-600 dark:bg-slate-700 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
          )}
        >
          全部 ({articles.length})
        </button>
        {categories.map((cat) => (
          <div key={cat.id} className="group relative shrink-0">
            <button
              onClick={() => setActiveCategory(cat.id)}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-colors',
                activeCategory === cat.id
                  ? 'bg-primary-100 text-primary-700 dark:bg-primary-900 dark:text-primary-300'
                  : 'bg-gray-100 text-gray-600 dark:bg-slate-700 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
              )}
            >
              {cat.icon} {cat.name} ({cat.articleCount})
            </button>
            {cat.id !== 'default' && (
              <button
                onClick={() => deleteCategory(cat.id)}
                className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-red-400 text-white opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity"
              >
                <Trash2 className="w-2.5 h-2.5" />
              </button>
            )}
          </div>
        ))}
      </div>

      {/* View mode toggle */}
      {filteredArticles.length > 0 && (
        <div className="flex items-center justify-end mb-3">
          <div className="flex items-center bg-gray-100 dark:bg-slate-700 rounded-lg p-0.5">
            <button
              onClick={() => setViewMode('grid')}
              className={cn(
                'p-1.5 rounded-md transition-colors',
                viewMode === 'grid'
                  ? 'bg-white dark:bg-slate-600 shadow-sm text-primary-600'
                  : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'
              )}
            >
              <Grid3X3 className="w-4 h-4" />
            </button>
            <button
              onClick={() => setViewMode('list')}
              className={cn(
                'p-1.5 rounded-md transition-colors',
                viewMode === 'list'
                  ? 'bg-white dark:bg-slate-600 shadow-sm text-primary-600'
                  : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'
              )}
            >
              <List className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* Content */}
      {filteredArticles.length > 0 ? (
        viewMode === 'grid' ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
            {filteredArticles.map((article) => (
              <div key={article.id} className="relative group">
                <ArticleCard
                  article={article}
                  variant="grid"
                  onClick={() => {
                    setSelectedLanguage(article.targetLanguage);
                    navigate(`/read/${article.id}`);
                  }}
                />
                <button
                  onClick={async (e) => {
                    e.stopPropagation();
                    const ok = await confirm('删除文章', '确定删除这篇文章？删除后无法恢复。');
                    if (ok) deleteArticle(article.id);
                  }}
                  className="absolute top-2 right-2 w-7 h-7 rounded-lg bg-white/80 dark:bg-slate-700/80 opacity-0 group-hover:opacity-100 flex items-center justify-center text-gray-400 hover:text-red-500 transition-all shadow-sm"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ))}
          </div>
        ) : (
          <div className="space-y-2">
            {filteredArticles.map((article) => (
              <div key={article.id} className="relative group">
                <ArticleCard
                  article={article}
                  variant="list"
                  onClick={() => {
                    setSelectedLanguage(article.targetLanguage);
                    navigate(`/read/${article.id}`);
                  }}
                />
                <button
                  onClick={async (e) => {
                    e.stopPropagation();
                    const ok = await confirm('删除文章', '确定删除这篇文章？删除后无法恢复。');
                    if (ok) deleteArticle(article.id);
                  }}
                  className="absolute top-2 right-2 w-7 h-7 rounded-lg bg-white/80 dark:bg-slate-700/80 opacity-0 group-hover:opacity-100 flex items-center justify-center text-gray-400 hover:text-red-500 transition-all shadow-sm"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ))}
          </div>
        )
      ) : (
        <EmptyState
          icon={<FolderOpen className="w-12 h-12" />}
          title={activeCategory === 'all' ? '还没有文章' : '此分类暂无文章'}
          description="导入一篇文章开始你的学习之旅"
          action={
            <button onClick={() => setShowImport(true)} className="btn-primary">
              <Plus className="w-4 h-4" /> 导入文章
            </button>
          }
        />
      )}

      <ImportModal isOpen={showImport} onClose={() => setShowImport(false)} />
      <ConfirmDialog
        open={confirmState.open}
        title={confirmState.title}
        message={confirmState.message}
        onConfirm={handleConfirm}
        onCancel={handleCancel}
      />
    </div>
  );
}