import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { VocabularyWord, ReviewRating } from '@/types';
import { calculateNextReview, createInitialReviewState, isDue } from '@/lib/ebbinghaus';

interface VocabularyState {
  words: VocabularyWord[];
  addWord: (word: VocabularyWord) => void;
  removeWord: (id: string) => void;
  updateWord: (id: string, data: Partial<VocabularyWord>) => void;
  incrementReview: (id: string) => void;
  /** 记录一次复习（艾宾浩斯算法） */
  recordReview: (id: string, rating: ReviewRating) => void;
  /** 获取所有到期需要复习的单词 */
  getWordsToReview: () => VocabularyWord[];
  /** 统计到期单词数量 */
  getDueCount: () => number;
  getWordsByLanguage: (language: string) => VocabularyWord[];
  getWordsByArticle: (articleId: string) => VocabularyWord[];
}

/** 为旧数据补齐复习字段（向前兼容） */
function migrateWord(word: VocabularyWord): VocabularyWord {
  if (typeof word.easeFactor === 'number' && word.nextReviewAt) {
    return word;
  }
  const init = createInitialReviewState(word.createdAt);
  return {
    ...word,
    ...init,
  };
}

export const useVocabularyStore = create<VocabularyState>()(
  persist(
    (set, get) => ({
      words: [],
      addWord: (word) =>
        set((state) => {
          // 按 word + language + sourceArticleId 去重：允许同词不同文章分别收藏
          const exists = state.words.find(
            (w) =>
              w.word === word.word &&
              w.language === word.language &&
              w.sourceArticleId === word.sourceArticleId
          );
          if (exists) return state;
          // 为新单词初始化艾宾浩斯字段
          const init = createInitialReviewState();
          return { words: [{ ...word, ...init }, ...state.words] };
        }),
      removeWord: (id) =>
        set((state) => ({ words: state.words.filter((w) => w.id !== id) })),
      updateWord: (id, data) =>
        set((state) => ({
          words: state.words.map((w) => (w.id === id ? { ...w, ...data } : w)),
        })),
      incrementReview: (id) =>
        set((state) => ({
          words: state.words.map((w) =>
            w.id === id
              ? { ...w, reviewCount: w.reviewCount + 1, lastReviewAt: Date.now() }
              : w
          ),
        })),
      recordReview: (id, rating) => {
        const word = get().words.find((w) => w.id === id);
        if (!word) return;
        const migrated = migrateWord(word);
        const result = calculateNextReview(
          {
            easeFactor: migrated.easeFactor,
            interval: migrated.interval,
            repetitions: migrated.repetitions,
          },
          rating
        );
        set((state) => ({
          words: state.words.map((w) =>
            w.id === id
              ? {
                  ...w,
                  easeFactor: result.easeFactor,
                  interval: result.interval,
                  repetitions: result.repetitions,
                  nextReviewAt: result.nextReviewAt,
                  reviewCount: w.reviewCount + 1,
                  lastReviewAt: Date.now(),
                  lastRating: rating,
                }
              : w
          ),
        }));
      },
      getWordsToReview: () => {
        const now = Date.now();
        return get()
          .words.map(migrateWord)
          .filter((w) => isDue(w, now))
          .sort((a, b) => a.nextReviewAt - b.nextReviewAt);
      },
      getDueCount: () => {
        const now = Date.now();
        return get().words.filter((w) => isDue(migrateWord(w), now)).length;
      },
      getWordsByLanguage: (language) =>
        get().words.filter((w) => w.language === language),
      getWordsByArticle: (articleId) =>
        get().words.filter((w) => w.sourceArticleId === articleId),
    }),
    {
      name: 'bilingual-reader-vocabulary',
      // 加载时迁移旧数据
      onRehydrateStorage: () => (state) => {
        if (state?.words) {
          state.words = state.words.map(migrateWord);
        }
      },
    }
  )
);