import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import ErrorBoundary from "@/components/ErrorBoundary";
import Layout from "@/components/Layout";
import Home from "@/pages/Home";
import ReadPage from "@/pages/ReadPage";
import ArticlesPage from "@/pages/ArticlesPage";
import VocabularyPage from "@/pages/VocabularyPage";
import SettingsPage from "@/pages/SettingsPage";
import StatsPage from "@/pages/StatsPage";
import BasicsPage from "@/pages/BasicsPage";
import BasicsLessonPage from "@/pages/BasicsLessonPage";
import PublicLibraryPage from "@/pages/PublicLibraryPage";
import PublicReadPage from "@/pages/PublicReadPage";
import MySubmissionsPage from "@/pages/MySubmissionsPage";
import AuthPage from "@/pages/AuthPage";

export default function App() {
  return (
    <ErrorBoundary>
      <Router>
        <Routes>
          <Route path="/auth" element={<AuthPage />} />
          <Route element={<Layout />}>
            <Route path="/" element={<Home />} />
            <Route path="/read/:articleId" element={<ReadPage />} />
            <Route path="/articles" element={<ArticlesPage />} />
            <Route path="/library" element={<PublicLibraryPage />} />
            <Route path="/library/:articleId" element={<PublicReadPage />} />
            <Route path="/submissions" element={<MySubmissionsPage />} />
            <Route path="/vocabulary" element={<VocabularyPage />} />
            <Route path="/settings" element={<SettingsPage />} />
            <Route path="/stats" element={<StatsPage />} />
            <Route path="/basics" element={<BasicsPage />} />
            <Route path="/basics/:language/:lessonId" element={<BasicsLessonPage />} />
          </Route>
        </Routes>
      </Router>
    </ErrorBoundary>
  );
}