import { Sun, Moon, Type, Globe, Volume2, Database, RefreshCw, Flame } from 'lucide-react';
import { useSettingsStore } from '@/stores/settingsStore';
import { useCheckInStore } from '@/stores/checkInStore';
import BackButton from '@/components/BackButton';
import { LANGUAGE_NAMES, POS_NAMES, DIFFICULTY_NAMES, type Language, type PartOfSpeech, type Difficulty } from '@/types';
import { cn } from '@/lib/utils';

export default function SettingsPage() {
  const { settings, updateSettings, toggleTheme } = useSettingsStore();
  const resetCheckIn = useCheckInStore((s) => s.reset);
  const totalCheckIns = useCheckInStore((s) => Object.values(s.checkInDays).filter(Boolean).length);

  const SettingSection = ({ title, icon, children }: { title: string; icon: React.ReactNode; children: React.ReactNode }) => (
    <div className="card p-5">
      <div className="flex items-center gap-2 mb-4">
        <span className="text-primary-600 dark:text-primary-400">{icon}</span>
        <h2 className="text-sm font-semibold text-gray-800 dark:text-gray-100">{title}</h2>
      </div>
      {children}
    </div>
  );

  return (
    <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8"
      onMouseDown={(e) => {
        // 只阻止按钮获取焦点导致的页面滚动，不影响 input/select 原生交互
        const target = e.target as HTMLElement;
        if (target.tagName === 'BUTTON' || target.closest('button')) {
          e.preventDefault();
        }
      }}
    >
      <BackButton />

      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800 dark:text-gray-100">设置</h1>
        <p className="text-sm text-gray-500 mt-0.5">自定义你的学习体验</p>
      </div>

      <div className="space-y-4">
        {/* Appearance */}
        <SettingSection title="外观" icon={<Sun className="w-4 h-4" />}>
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-700 dark:text-gray-200">主题模式</p>
              <p className="text-xs text-gray-400 mt-0.5">切换浅色/深色主题</p>
            </div>
            <button
              onClick={toggleTheme}
              className={cn(
                'relative w-14 h-7 rounded-full transition-colors duration-300',
                settings.theme === 'dark' ? 'bg-primary-500' : 'bg-gray-200'
              )}
            >
              <div
                className={cn(
                  'absolute top-0.5 w-6 h-6 rounded-full bg-white shadow-sm flex items-center justify-center transition-transform duration-300',
                  settings.theme === 'dark' ? 'translate-x-7.5' : 'translate-x-0.5'
                )}
              >
                {settings.theme === 'dark' ? (
                  <Moon className="w-3 h-3 text-primary-600" />
                ) : (
                  <Sun className="w-3 h-3 text-yellow-500" />
                )}
              </div>
            </button>
          </div>
        </SettingSection>

        {/* Language */}
        <SettingSection title="语种" icon={<Globe className="w-4 h-4" />}>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1.5">默认目标语种</label>
            <select
              value={settings.defaultTargetLanguage}
              onChange={(e) => {
                updateSettings({ defaultTargetLanguage: e.target.value as Language });
                (e.target as HTMLElement).blur();
              }}
              className="input-field max-w-xs"
            >
              {Object.entries(LANGUAGE_NAMES).map(([key, name]) => (
                <option key={key} value={key}>{name}</option>
              ))}
            </select>
          </div>
        </SettingSection>

        {/* Reading */}
        <SettingSection title="阅读" icon={<Type className="w-4 h-4" />}>
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1.5">
                正文字号：{settings.fontSize}px
              </label>
              <input
                type="range"
                min="14"
                max="24"
                value={settings.fontSize}
                onChange={(e) => updateSettings({ fontSize: Number(e.target.value) })}
                className="w-full max-w-xs h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-primary-500"
              />
              <div className="flex justify-between max-w-xs text-[10px] text-gray-400 mt-0.5">
                <span>14</span>
                <span>18</span>
                <span>24</span>
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1.5">行间距</label>
              <select
                value={settings.lineHeight}
                onChange={(e) => {
                  updateSettings({ lineHeight: Number(e.target.value) });
                  (e.target as HTMLElement).blur();
                }}
                className="input-field max-w-xs"
              >
                <option value={1.4}>紧凑 (1.4)</option>
                <option value={1.6}>标准 (1.6)</option>
                <option value={1.8}>宽松 (1.8)</option>
                <option value={2.0}>极宽 (2.0)</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1.5">字体样式</label>
              <div className="flex gap-2">
                <button
                  onClick={() => updateSettings({ fontFamily: 'sans' })}
                  className={cn(
                    'px-4 py-2 rounded-xl text-sm font-medium transition-all',
                    settings.fontFamily === 'sans'
                      ? 'bg-primary-100 text-primary-700 ring-1 ring-primary-300'
                      : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                  )}
                >
                  无衬线
                </button>
                <button
                  onClick={() => updateSettings({ fontFamily: 'serif' })}
                  className={cn(
                    'px-4 py-2 rounded-xl text-sm font-medium transition-all font-serif',
                    settings.fontFamily === 'serif'
                      ? 'bg-primary-100 text-primary-700 ring-1 ring-primary-300'
                      : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                  )}
                >
                  衬线
                </button>
                <button
                  onClick={() => updateSettings({ fontFamily: 'mono' })}
                  className={cn(
                    'px-4 py-2 rounded-xl text-sm font-medium transition-all font-mono',
                    settings.fontFamily === 'mono'
                      ? 'bg-primary-100 text-primary-700 ring-1 ring-primary-300'
                      : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                  )}
                >
                  等宽
                </button>
              </div>
            </div>
          </div>
        </SettingSection>

        {/* Speech */}
        <SettingSection title="朗读" icon={<Volume2 className="w-4 h-4" />}>
          <div>
            <label className="block text-xs font-medium text-gray-500 mb-1.5">
              朗读语速：{settings.speechRate.toFixed(1)}x
            </label>
            <input
              type="range"
              min="0.5"
              max="2"
              step="0.1"
              value={settings.speechRate}
              onChange={(e) => updateSettings({ speechRate: Number(e.target.value) })}
              className="w-full max-w-xs h-2 bg-gray-200 rounded-full appearance-none cursor-pointer accent-primary-500"
            />
            <div className="flex justify-between max-w-xs text-[10px] text-gray-400 mt-0.5">
              <span>0.5x</span>
              <span>1.0x</span>
              <span>2.0x</span>
            </div>
          </div>
        </SettingSection>

        {/* Replace */}
        <SettingSection title="换词" icon={<RefreshCw className="w-4 h-4" />}>
          <div className="space-y-5">
            {/* Ratio */}
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-2">
                替换强度：{Math.round(settings.replaceRatio * 100)}%
              </label>
              <input
                type="range"
                min="0"
                max="1"
                step="0.05"
                value={settings.replaceRatio}
                onChange={(e) => updateSettings({ replaceRatio: Number(e.target.value) })}
                className="w-full max-w-xs h-2 bg-gray-200 dark:bg-slate-600 rounded-full appearance-none cursor-pointer accent-primary-500"
              />
              <div className="flex justify-between max-w-xs text-[10px] text-gray-400 mt-1">
                <span>0%</span>
                <span>25%</span>
                <span>50%</span>
                <span>75%</span>
                <span>100%</span>
              </div>
            </div>

            {/* Difficulty */}
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1.5">难度分级</label>
              <div className="flex gap-2">
                {(Object.entries(DIFFICULTY_NAMES) as [Difficulty, string][]).map(([key, name]) => (
                  <button
                    key={key}
                    onClick={() => updateSettings({ replaceDifficulty: key })}
                    className={cn(
                      'flex-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-all',
                      settings.replaceDifficulty === key
                        ? 'bg-accent-100 text-accent-700 ring-1 ring-accent-300 dark:bg-accent-900 dark:text-accent-300'
                        : 'bg-gray-50 text-gray-500 hover:bg-gray-100 dark:bg-slate-700 dark:text-gray-400'
                    )}
                  >
                    {name}
                  </button>
                ))}
              </div>
            </div>

            {/* POS Filter */}
            <div>
              <label className="block text-xs font-medium text-gray-500 mb-1.5">词性筛选</label>
              <div className="flex flex-wrap gap-1.5">
                {(Object.entries(POS_NAMES) as [PartOfSpeech, string][]).map(([key, name]) => {
                  const isActive = (settings.replacePosFilter || []).includes(key);
                  return (
                    <button
                      key={key}
                      type="button"
                      onClick={() => {
                        const current = settings.replacePosFilter || [];
                        const next = isActive
                          ? current.filter((p) => p !== key)
                          : [...current, key];
                        updateSettings({ replacePosFilter: next });
                      }}
                      className={cn(
                        'px-2.5 py-1 rounded-lg text-[11px] font-medium transition-all',
                        isActive
                          ? 'bg-primary-100 text-primary-700 ring-1 ring-primary-300 dark:bg-primary-900 dark:text-primary-300'
                          : 'bg-gray-50 text-gray-500 hover:bg-gray-100 dark:bg-slate-700 dark:text-gray-400'
                      )}
                    >
                      {name}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Avoid Duplicates */}
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={settings.replaceAvoidDuplicates}
                onChange={(e) => updateSettings({ replaceAvoidDuplicates: e.target.checked })}
                className="w-4 h-4 rounded border-gray-300 text-primary-500 focus:ring-primary-400"
              />
              <span className="text-xs text-gray-600 dark:text-gray-400">同一篇文章内避免重复替换同一个词</span>
            </label>
          </div>
        </SettingSection>

        {/* Data */}
        <SettingSection title="数据管理" icon={<Database className="w-4 h-4" />}>
          <div className="space-y-3">
            <p className="text-xs text-gray-500">
              所有数据存储在本地设备中，无需账号即可使用全部功能。
              {settings.autoSync && ' 云端同步已开启。'}
            </p>
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={settings.autoSync}
                onChange={(e) => updateSettings({ autoSync: e.target.checked })}
                className="w-4 h-4 rounded border-gray-300 text-primary-500 focus:ring-primary-400"
              />
              <span className="text-sm text-gray-600 dark:text-gray-400">开启云端备份（开发中）</span>
            </label>

            {/* 打卡数据管理 */}
            <div className="flex items-center justify-between p-3 mt-2 rounded-xl bg-orange-50 dark:bg-orange-900/20 border border-orange-100 dark:border-orange-900/50">
              <div className="flex items-center gap-2 min-w-0">
                <Flame className="w-4 h-4 text-orange-500 shrink-0" />
                <div className="min-w-0">
                  <p className="text-sm text-gray-700 dark:text-gray-200">学习打卡记录</p>
                  <p className="text-[11px] text-gray-400">已累计 {totalCheckIns} 天</p>
                </div>
              </div>
              <button
                onClick={() => {
                  if (window.confirm('确定要清除所有打卡记录吗？此操作不可撤销。')) {
                    resetCheckIn();
                  }
                }}
                disabled={totalCheckIns === 0}
                className="shrink-0 px-3 py-1.5 rounded-lg text-xs font-medium text-orange-700 dark:text-orange-300 hover:bg-orange-100 dark:hover:bg-orange-900/40 disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
              >
                清除记录
              </button>
            </div>
          </div>
        </SettingSection>
      </div>
    </div>
  );
}