import { Outlet, NavLink } from 'react-router-dom';
import {
  BookOpen,
  BookMarked,
  FolderOpen,
  Settings,
  ChevronLeft,
  ChevronRight,
  Sun,
  Moon,
  Menu,
  Flame,
  BarChart3,
  GraduationCap,
  Library,
  Send,
  LogIn,
  LogOut,
} from 'lucide-react';
import { useUIStore } from '@/stores/uiStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { useVocabularyStore } from '@/stores/vocabularyStore';
import { useCheckInStore } from '@/stores/checkInStore';
import { useAuthStore } from '@/stores/authStore';
import { useWalletStore } from '@/stores/walletStore';
import { cn } from '@/lib/utils';
import { useEffect, useState } from 'react';
import { isDue } from '@/lib/ebbinghaus';
import LoginPrompt from '@/components/LoginPrompt';
import { useNavigate } from 'react-router-dom';

const navItems = [
  { path: '/', label: '学习台', icon: BookOpen },
  { path: '/articles', label: '文章管理', icon: FolderOpen },
  { path: '/library', label: '公共文章库', icon: Library },
  { path: '/submissions', label: '我的投稿', icon: Send },
  { path: '/vocabulary', label: '生词本', icon: BookMarked },
  { path: '/basics', label: '基础学习', icon: GraduationCap },
  { path: '/stats', label: '学习数据', icon: BarChart3 },
  { path: '/settings', label: '设置', icon: Settings },
];

export default function Layout() {
  const { showSidebar, toggleSidebar } = useUIStore();
  const { settings, toggleTheme } = useSettingsStore();
  const words = useVocabularyStore((s) => s.words);
  const streak = useCheckInStore((s) => s.streak);
  const bootstrap = useAuthStore((s) => s.bootstrap);
  const isGuest = useAuthStore((s) => s.isGuest);
  const user = useAuthStore((s) => s.user);
  const logout = useAuthStore((s) => s.logout);
  const syncWallet = useWalletStore((s) => s.syncFromServer);
  const navigate = useNavigate();
  const isDark = settings.theme === 'dark';

  // 移动端抽屉状态（与桌面端 showSidebar 分离）
  const [isMobileDrawerOpen, setIsMobileDrawerOpen] = useState(false);

  // 计算待复习单词数
  const dueCount = words.filter((w) => isDue(w)).length;

  // 启动时初始化认证状态，已登录用户才同步钱包
  useEffect(() => {
    bootstrap().then(() => {
      if (!useAuthStore.getState().isGuest) {
        syncWallet();
      }
    });
  }, [bootstrap, syncWallet, isGuest]);

  // 同步主题到 <html> 元素（Tailwind dark mode class 策略）
  useEffect(() => {
    document.documentElement.classList.remove('light', 'dark');
    document.documentElement.classList.add(settings.theme);
  }, [settings.theme]);

  // 移动端点击遮罩关闭抽屉
  const handleBackdropClick = () => {
    setIsMobileDrawerOpen(false);
  };

  // 移动端导航点击后关闭抽屉
  const handleMobileNavClick = () => {
    setIsMobileDrawerOpen(false);
  };

  return (
    <div className="flex h-screen overflow-hidden bg-[var(--color-bg)]">
      {/* === 移动端抽屉侧边栏 === */}
      {/* 遮罩层 */}
      <div
        className={cn(
          'fixed inset-0 bg-black/40 backdrop-blur-sm z-40 transition-opacity duration-300 md:hidden',
          isMobileDrawerOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'
        )}
        onClick={handleBackdropClick}
      />

      {/* 移动端抽屉 */}
      <aside
        className={cn(
          'fixed top-0 left-0 h-full w-72 bg-white dark:bg-slate-800 z-50 transform transition-transform duration-300 ease-out md:hidden',
          isMobileDrawerOpen ? 'translate-x-0' : '-translate-x-full'
        )}
      >
        {/* Logo */}
        <div className="flex items-center gap-3 px-5 h-16 border-b border-gray-100 dark:border-gray-700">
          <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-macaron-green to-macaron-purple flex items-center justify-center text-white font-bold text-sm shadow-sm">
            阅
          </div>
          <span className="font-semibold text-gray-800 dark:text-gray-100 text-sm tracking-wide">
            双语阅学
          </span>
        </div>

        {/* Nav */}
        <nav className="flex-1 py-4 px-3 space-y-1">
          {navItems.map((item) => {
            const showBadge = item.path === '/vocabulary' && dueCount > 0;
            const showStreak = item.path === '/' && streak > 0;
            return (
              <NavLink
                key={item.path}
                to={item.path}
                end={item.path === '/'}
                onClick={handleMobileNavClick}
                className={({ isActive }) =>
                  cn(
                    'flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-all duration-200',
                    isActive
                      ? 'bg-primary-50 dark:bg-primary-950 text-primary-700 dark:text-primary-300 shadow-sm'
                      : 'text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-slate-700 hover:text-gray-800 dark:hover:text-gray-200'
                  )
                }
              >
                <item.icon className="w-4.5 h-4.5 shrink-0" />
                <span className="truncate flex-1">{item.label}</span>
                {showBadge && (
                  <span className="shrink-0 min-w-[20px] h-5 px-1.5 rounded-full bg-primary-500 text-white text-[10px] font-semibold flex items-center justify-center">
                    {dueCount > 99 ? '99+' : dueCount}
                  </span>
                )}
                {showStreak && (
                  <span className="shrink-0 inline-flex items-center gap-0.5 px-1.5 h-5 rounded-full bg-orange-100 dark:bg-orange-900/40 text-orange-700 dark:text-orange-300 text-[10px] font-semibold">
                    <Flame className="w-3 h-3 fill-current" />
                    {streak}
                  </span>
                )}
              </NavLink>
            );
          })}
        </nav>

        {/* Theme toggle */}
        <div className="px-3 pb-3 border-t border-gray-100 dark:border-gray-700 pt-3">
          <button
            onClick={toggleTheme}
            className="flex items-center gap-3 w-full px-3 py-2.5 rounded-xl text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-slate-700 transition-all duration-200"
          >
            {isDark ? <Sun className="w-4.5 h-4.5" /> : <Moon className="w-4.5 h-4.5" />}
            <span>{isDark ? '浅色模式' : '深色模式'}</span>
          </button>
        </div>

        {/* User status */}
        <div className="px-3 pb-4">
          {isGuest ? (
            <button
              onClick={() => navigate('/auth')}
              className="flex items-center gap-3 w-full px-3 py-2.5 rounded-xl text-sm font-medium text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-950 hover:bg-primary-100 dark:hover:bg-primary-900 transition-all duration-200"
            >
              <LogIn className="w-4.5 h-4.5 shrink-0" />
              <span>登录 / 注册</span>
            </button>
          ) : (
            <div className="flex items-center gap-2">
              <div className="flex items-center gap-2 flex-1 min-w-0 px-2 py-1.5 rounded-xl bg-gray-50 dark:bg-slate-700">
                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-macaron-green to-macaron-purple text-white text-xs flex items-center justify-center font-bold shrink-0">
                  {user?.username[0]?.toUpperCase()}
                </div>
                <span className="text-xs font-medium text-gray-700 dark:text-gray-200 truncate">
                  {user?.username}
                </span>
              </div>
              <button
                onClick={logout}
                className="p-2 rounded-xl text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-all"
                title="退出登录"
              >
                <LogOut className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      </aside>

      {/* === 平板/桌面端侧边栏 === */}
      <aside
        className={cn(
          'hidden md:flex flex-col border-r border-gray-200 dark:border-gray-700 bg-white dark:bg-slate-800 transition-all duration-300 ease-in-out shrink-0 relative',
          // 桌面端（lg以上）：展开 w-56，收起 w-0（完全隐藏）
          // 平板端（md-lg）：展开 w-48，收起 w-16（图标模式）
          showSidebar ? 'w-48 lg:w-56' : 'w-16 lg:w-0 overflow-hidden'
        )}
      >
        {/* 展开时显示在侧边栏右上角的收起按钮 */}
        {showSidebar && (
          <button
            onClick={toggleSidebar}
            className="hidden md:flex absolute top-2 right-2 z-10 w-7 h-7 rounded-lg bg-gray-50 dark:bg-slate-700 hover:bg-gray-100 dark:hover:bg-slate-600 items-center justify-center transition-all duration-200 text-gray-400 hover:text-gray-600"
            title="收起侧边栏"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>
        )}

        {/* Logo */}
        <div className="flex items-center gap-3 px-3 lg:px-5 h-14 border-b border-gray-100 dark:border-gray-700">
          <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-macaron-green to-macaron-purple flex items-center justify-center text-white font-bold text-sm shadow-sm shrink-0">
            阅
          </div>
          {/* 收起时隐藏文字 */}
          <span className={cn(
            'font-semibold text-gray-800 dark:text-gray-100 text-sm tracking-wide transition-opacity duration-200',
            showSidebar ? 'opacity-100' : 'opacity-0 overflow-hidden w-0'
          )}>
            双语阅学
          </span>
        </div>

        {/* Nav */}
        <nav className="flex-1 py-4 px-3 space-y-1">
          {navItems.map((item) => {
            const showBadge = item.path === '/vocabulary' && dueCount > 0;
            const showStreak = item.path === '/' && streak > 0;
            return (
              <NavLink
                key={item.path}
                to={item.path}
                end={item.path === '/'}
                className={({ isActive }) =>
                  cn(
                    'relative flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-all duration-200',
                    isActive
                      ? 'bg-primary-50 dark:bg-primary-950 text-primary-700 dark:text-primary-300 shadow-sm'
                      : 'text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-slate-700 hover:text-gray-800 dark:hover:text-gray-200'
                  )
                }
              >
                <item.icon className="w-4.5 h-4.5 shrink-0" />
                {/* 收起时隐藏文字 */}
                <span className={cn(
                  'truncate flex-1 transition-opacity duration-200',
                  showSidebar ? 'opacity-100' : 'opacity-0 overflow-hidden w-0'
                )}>
                  {item.label}
                </span>
                {showBadge && showSidebar && (
                  <span className="shrink-0 min-w-[20px] h-5 px-1.5 rounded-full bg-primary-500 text-white text-[10px] font-semibold flex items-center justify-center">
                    {dueCount > 99 ? '99+' : dueCount}
                  </span>
                )}
                {showBadge && !showSidebar && (
                  <span className="absolute right-1 top-1 w-2 h-2 rounded-full bg-primary-500" />
                )}
                {showStreak && showSidebar && (
                  <span className="shrink-0 inline-flex items-center gap-0.5 px-1.5 h-5 rounded-full bg-orange-100 dark:bg-orange-900/40 text-orange-700 dark:text-orange-300 text-[10px] font-semibold">
                    <Flame className="w-3 h-3 fill-current" />
                    {streak}
                  </span>
                )}
              </NavLink>
            );
          })}
        </nav>

        {/* Theme toggle */}
        <div className="px-3 pb-4 border-t border-gray-100 dark:border-gray-700 pt-3">
          <button
            onClick={toggleTheme}
            className="flex items-center justify-center md:justify-start gap-3 w-full px-3 py-2.5 rounded-xl text-sm font-medium text-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-slate-700 transition-all duration-200"
          >
            {isDark ? <Sun className="w-4.5 h-4.5 shrink-0" /> : <Moon className="w-4.5 h-4.5 shrink-0" />}
            {/* 收起时隐藏文字 */}
            <span className={cn(
              'transition-opacity duration-200',
              showSidebar ? 'opacity-100' : 'opacity-0 overflow-hidden w-0'
            )}>
              {isDark ? '浅色模式' : '深色模式'}
            </span>
          </button>
        </div>

        {/* User status (desktop) */}
        <div className="px-3 pb-3">
          {isGuest ? (
            <button
              onClick={() => navigate('/auth')}
              className="flex items-center justify-center md:justify-start gap-3 w-full px-3 py-2.5 rounded-xl text-sm font-medium text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-950 hover:bg-primary-100 dark:hover:bg-primary-900 transition-all duration-200"
            >
              <LogIn className="w-4.5 h-4.5 shrink-0" />
              <span className={cn(
                'transition-opacity duration-200',
                showSidebar ? 'opacity-100' : 'opacity-0 overflow-hidden w-0'
              )}>
                登录 / 注册
              </span>
            </button>
          ) : (
            <div className="flex items-center justify-center md:justify-start gap-2">
              <div className={cn(
                'flex items-center gap-2 flex-1 min-w-0 px-2 py-1.5 rounded-xl bg-gray-50 dark:bg-slate-700',
                !showSidebar && 'flex-none px-0'
              )}>
                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-macaron-green to-macaron-purple text-white text-xs flex items-center justify-center font-bold shrink-0">
                  {user?.username[0]?.toUpperCase()}
                </div>
                <span className={cn(
                  'text-xs font-medium text-gray-700 dark:text-gray-200 truncate transition-opacity duration-200',
                  showSidebar ? 'opacity-100' : 'opacity-0 overflow-hidden w-0'
                )}>
                  {user?.username}
                </span>
              </div>
              <button
                onClick={logout}
                className={cn(
                  'p-2 rounded-xl text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-all',
                  !showSidebar && 'hidden'
                )}
                title="退出登录"
              >
                <LogOut className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      </aside>

      {/* === 移动端：精致的浮动菜单按钮 === */}
      <button
        onClick={() => setIsMobileDrawerOpen(true)}
        className="md:hidden fixed top-3 right-3 z-30 w-9 h-9 rounded-full bg-white/70 dark:bg-slate-800/70 backdrop-blur-md border border-gray-200/60 dark:border-gray-700/60 flex items-center justify-center shadow-sm hover:shadow-md hover:bg-white dark:hover:bg-slate-800 transition-all duration-200 text-gray-500 dark:text-gray-400"
        aria-label="打开菜单"
      >
        <Menu className="w-[18px] h-[18px]" />
      </button>

      {/* 平板/桌面端：侧边栏收起时的唤起按钮 */}
      {!showSidebar && (
        <button
          onClick={toggleSidebar}
          className="hidden md:flex fixed top-3 left-3 z-20 w-8 h-8 rounded-lg bg-white dark:bg-slate-700 border border-gray-200 dark:border-gray-600 items-center justify-center shadow-md hover:shadow-lg transition-all duration-200 text-gray-400 hover:text-gray-600 sidebar-toggle-btn"
          title="展开侧边栏"
        >
          <ChevronRight className="w-4 h-4" />
        </button>
      )}

      {/* === 主内容区域 === */}
      <main className="flex-1 overflow-auto md:pt-0 pt-0">
        <div className="animate-fade-in">
          <Outlet />
        </div>
      </main>

      {/* 登录提示弹窗（游客尝试受限操作时显示） */}
      <LoginPrompt />
    </div>
  );
}