/**
 * 翻译服务模块
 * 支持行对行翻译，可接入多种翻译引擎
 * 
 * 技术路线：
 * 阶段一：腾讯翻译君 TMT（推荐，每月 500 万字符免费额度）
 * 阶段二：MyMemory（零配置兜底，免费但有每日限额）
 * 阶段三：百度翻译 API（需要有效密钥）
 * 阶段四：模拟翻译（演示模式，无网络时兜底）
 */

import type { Language } from '@/types';
import { baiduTranslate, baiduTranslateBatch, isBaiduConfigured } from './baiduTranslate';
import {
  tencentTranslate,
  tencentTranslateBatch,
  isTencentConfigured,
} from './tencentTranslate';
import {
  mymemoryTranslate,
  mymemoryTranslateBatch,
  isMyMemoryAvailable,
} from './mymemoryTranslate';

export interface TranslationPair {
  original: string;
  translated: string;
}

export interface TranslationResult {
  pairs: TranslationPair[];
  sourceLanguage: Language;
  targetLanguage: Language;
  /**
   * 是否因"源语种 = 目标语种"跳过了翻译。
   * true 时，pairs 中 translated 与 original 相同，调用方应展示"无需翻译"提示而非"翻译完成"。
   */
  noTranslationNeeded: boolean;
}

/**
 * 翻译进度回调
 * @param completed 已完成的句子数
 * @param total 总句子数
 * @param current 当前正在翻译的句子（用于显示"正在翻译第 X/Y 句"）
 */
export type TranslationProgressCallback = (
  completed: number,
  total: number,
  current: string
) => void;

/**
 * 翻译选项
 */
export interface TranslateOptions {
  /** 进度回调（按行更新） */
  onProgress?: TranslationProgressCallback;
  /** 中断信号（true 时停止后续翻译） */
  signal?: { aborted: boolean };
}

/**
 * 文本是否含有指定语言的特征字符
 * - zh/ja/ko: CJK / 平假名 / 片假名 / 韩文
 * - en: 拉丁字母
 * - fr/de/es: 拉丁字母（含变音符）
 * - ru: 西里尔字母
 * - ar: 阿拉伯字母
 */
const LANG_CHAR_PATTERNS: Record<Language, RegExp> = {
  zh: /[\u4E00-\u9FFF]/,
  ja: /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FFF]/,
  ko: /[\uAC00-\uD7AF\u1100-\u11FF]/,
  en: /[A-Za-z]/,
  fr: /[A-Za-zÀ-ÖØ-öø-ÿ]/,
  de: /[A-Za-zÀ-ÖØ-öø-ÿß]/,
  es: /[A-Za-zÀ-ÖØ-öø-ÿñÑ]/,
  ru: /[\u0400-\u04FF]/,
  ar: /[\u0600-\u06FF]/,
};

function hasSourceLanguageChars(text: string, lang: Language): boolean {
  const pattern = LANG_CHAR_PATTERNS[lang];
  return pattern ? pattern.test(text) : /[A-Za-z]/.test(text);
}

/**
 * 将文本按行对行分割（保持原文行结构）
 * 按换行符逐行分割，保留空行占位，不做句子级别拆分
 */
function splitBySentences(text: string): string[] {
  const lines = text.split('\n');
  const result: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    // 保留空行作为占位符
    if (!trimmed) {
      result.push('');
      continue;
    }
    result.push(trimmed);
  }

  return result;
}

/**
 * 模拟翻译（演示用，当未配置 API 时使用）
 */
async function mockTranslate(
  text: string,
  targetLang: Language
): Promise<string> {
  // 模拟翻译延迟
  await new Promise((resolve) => setTimeout(resolve, 300));
  
  // 根据目标语言返回不同的模拟翻译
  const translations: Record<Language, string> = {
    zh: text,
    en: `[English] ${text}`,
    ja: `[日本語] ${text}`,
    ru: `[Русский] ${text}`,
    es: `[Español] ${text}`,
    ko: `[한국어] ${text}`,
    fr: `[Français] ${text}`,
    de: `[Deutsch] ${text}`,
    ar: `[العربية] ${text}`,
  };
  
  return translations[targetLang] || text;
}

/**
 * 行对行翻译（自动选择翻译引擎，支持进度回调）
 * 优先级：MyMemory（无需 Key）> 百度 API > 模拟翻译
 */
export async function translateLineByLine(
  content: string,
  sourceLang: Language,
  targetLang: Language,
  options: TranslateOptions = {}
): Promise<TranslationResult> {
  const { onProgress, signal } = options;
  const sentences = splitBySentences(content);
  const total = sentences.length;

  // 短路：源语种 = 目标语种，无需翻译
  if (sourceLang === targetLang) {
    const pairs: TranslationPair[] = sentences.map((s) => ({
      original: s,
      translated: s,
    }));
    onProgress?.(total, total, '');
    return {
      pairs,
      sourceLanguage: sourceLang,
      targetLanguage: targetLang,
      noTranslationNeeded: true,
    };
  }

  const pairs: TranslationPair[] = [];
  let completed = 0;

  // 引擎选择：腾讯 > MyMemory > 百度 > 模拟
  const [tencentAvailable, myMemoryUp, baiduAvailable] = await Promise.all([
    isTencentConfigured(),
    isMyMemoryAvailable(),
    isBaiduConfigured(),
  ]);

  const engine: 'tencent' | 'mymemory' | 'baidu' | 'mock' = tencentAvailable
    ? 'tencent'
    : myMemoryUp
      ? 'mymemory'
      : baiduAvailable
        ? 'baidu'
        : 'mock';

  if (engine === 'mock') {
    // 模拟翻译：逐句处理（带进度）
    for (const sentence of sentences) {
      if (signal?.aborted) break;
      if (!sentence) {
        pairs.push({ original: '', translated: '' });
      } else {
        onProgress?.(completed, total, sentence);
        const translated = await mockTranslate(sentence, targetLang);
        pairs.push({ original: sentence, translated });
      }
      completed++;
      onProgress?.(completed, total, sentence);
    }
    return {
      pairs,
      sourceLanguage: sourceLang,
      targetLanguage: targetLang,
      noTranslationNeeded: false,
    };
  }

  // 真实翻译引擎：批量处理（带进度）
  const nonEmptySentences = sentences.filter(Boolean);
  let translatedResults: string[];
  let lastEngineError: Error | null = null;

  try {
    onProgress?.(0, total, '');
    translatedResults =
      engine === 'tencent'
        ? await tencentTranslateBatch(nonEmptySentences, sourceLang, targetLang)
        : engine === 'mymemory'
          ? await mymemoryTranslateBatch(nonEmptySentences, sourceLang, targetLang)
          : await baiduTranslateBatch(nonEmptySentences, sourceLang, targetLang);
    if (signal?.aborted) {
      return {
        pairs,
        sourceLanguage: sourceLang,
        targetLanguage: targetLang,
        noTranslationNeeded: false,
      };
    }
  } catch (err) {
    // 批量失败时降级为逐句翻译（带进度 + 错误恢复）
    console.error(`[翻译] ${engine} 批量翻译失败，降级为逐句翻译:`, err);
    lastEngineError = err instanceof Error ? err : new Error(String(err));
    translatedResults = [];
    for (const sentence of nonEmptySentences) {
      if (signal?.aborted) break;
      onProgress?.(completed, total, sentence);
      try {
        const result =
          engine === 'tencent'
            ? await tencentTranslate(sentence, sourceLang, targetLang)
            : engine === 'mymemory'
              ? await mymemoryTranslate(sentence, sourceLang, targetLang)
              : await baiduTranslate(sentence, sourceLang, targetLang);
        translatedResults.push(result);
      } catch (e) {
        // 单句失败：保留原文，避免整个流程崩溃
        translatedResults.push(sentence);
      }
      completed++;
      onProgress?.(completed, total, sentence);
    }
  }

  if (signal?.aborted) {
    return {
      pairs,
      sourceLanguage: sourceLang,
      targetLanguage: targetLang,
      noTranslationNeeded: false,
    };
  }

  // 将翻译结果映射回原始句子序列（空行保持空翻译）
  let translatedIndex = 0;
  // 只对"含有源语言特征字符"的行做翻译失败校验
  // 这样可以避免 SQL/代码/数字行被 MyMemory 原样返回时误判为翻译失败
  let translatableCount = 0;
  let sameAsOriginalInTranslatable = 0;
  for (const sentence of sentences) {
    if (!sentence) {
      pairs.push({ original: '', translated: '' });
    } else {
      const translated = translatedResults[translatedIndex] || sentence;
      pairs.push({ original: sentence, translated });
      if (hasSourceLanguageChars(sentence, sourceLang)) {
        translatableCount++;
        // 翻译后与原文比较（去除首尾空白和标点）
        const normalize = (s: string) =>
          s.trim().replace(/[\s，。！？、；：""''（）【】「」『』]/g, '');
        if (normalize(translated) === normalize(sentence)) {
          sameAsOriginalInTranslatable++;
        }
      }
      translatedIndex++;
    }
  }
  onProgress?.(total, total, '');

  // 校验：仅在"可翻译行"中统计；如果大部分应该被翻译的行都没变化，视为翻译失败
  // 阈值设为 0.8（避免误判：含 1-2 行未被翻译的代码行不应让整体失败）
  if (
    translatableCount > 0 &&
    sameAsOriginalInTranslatable / translatableCount >= 0.8
  ) {
    const reason = lastEngineError
      ? `（${lastEngineError.message}）`
      : '可能是源/目标语言设置错误，或翻译服务受限';
    const tip = sourceLang === 'en'
      ? '请检查源语言/目标语言是否正确。若是代码/技术文档，部分内容可能因含大量专有名词而无法被翻译引擎正确处理。'
      : '请检查源语言/目标语言是否正确，或稍后重试。';
    throw new Error(
      `翻译失败：${sameAsOriginalInTranslatable}/${translatableCount} 句译文与原文完全相同${reason}。${tip}`
    );
  }

  return {
    pairs,
    sourceLanguage: sourceLang,
    targetLanguage: targetLang,
    noTranslationNeeded: false,
  };
}

/**
 * 批量翻译（整段）
 */
export async function translateBatch(
  content: string,
  sourceLang: Language,
  targetLang: Language
): Promise<string> {
  const result = await translateLineByLine(content, sourceLang, targetLang);
  return result.pairs.map((p) => p.translated).join('\n');
}

/**
 * 检查当前使用的翻译引擎
 */
export async function getActiveEngine(): Promise<string> {
  const [tencentAvailable, myMemoryUp, baiduAvailable] = await Promise.all([
    isTencentConfigured(),
    isMyMemoryAvailable(),
    isBaiduConfigured(),
  ]);
  if (tencentAvailable) return '腾讯翻译君 TMT';
  if (myMemoryUp) return 'MyMemory（免费，无需配置）';
  if (baiduAvailable) return '百度翻译 API';
  return '模拟翻译（演示模式）';
}
