import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Upload, BookOpen, Sparkles, ArrowRight, GraduationCap } from 'lucide-react';
import { useArticleStore } from '@/stores/articleStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { useUIStore } from '@/stores/uiStore';
import ArticleCard from '@/components/ArticleCard';
import ImportModal from '@/components/ImportModal';
import EmptyState from '@/components/EmptyState';
import CheckInCard from '@/components/CheckInCard';
import StatsSummary from '@/components/StatsSummary';
import type { Language } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import { cn } from '@/lib/utils';

export default function Home() {
  const navigate = useNavigate();
  const { articles, categories } = useArticleStore();
  const { settings } = useSettingsStore();
  const { setSelectedLanguage } = useUIStore();
  const [showImport, setShowImport] = useState(false);
  const [activeCategory, setActiveCategory] = useState('all');
  const [activeLanguage, setActiveLanguage] = useState<Language | 'all'>('all');

  const filteredArticles = articles.filter((a) => {
    if (activeCategory !== 'all' && a.categoryId !== activeCategory) return false;
    if (activeLanguage !== 'all' && a.targetLanguage !== activeLanguage) return false;
    return true;
  });

  const recentArticles = filteredArticles.slice(0, 8);

  const languages = Object.entries(LANGUAGE_NAMES).slice(0, 5) as [Language, string][];

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
      {/* Hero Section */}
      <div className="card bg-gradient-to-br from-macaron-green/10 via-macaron-warm to-macaron-purple/10 dark:from-primary-950 dark:to-accent-950 p-6 pt-7 sm:p-8 mb-8 rounded-2xl border-0">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div className="md:pr-0 pr-10">
            <h1 className="text-2xl sm:text-3xl font-bold text-gray-800 dark:text-gray-100 mb-2">
              欢迎回来，开始学习 ✨
            </h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">
              当前学习语种：
              <span className="font-medium text-primary-600 dark:text-primary-400 ml-1">
                {LANGUAGE_NAMES[settings.defaultTargetLanguage]}
              </span>
              {articles.length > 0 && (
                <span className="ml-3">· 共 {articles.length} 篇文章</span>
              )}
            </p>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => setShowImport(true)}
              className="btn-primary"
            >
              <Plus className="w-4 h-4" />
              导入文章
            </button>
            <button
              onClick={() => navigate('/articles')}
              className="btn-secondary"
            >
              <BookOpen className="w-4 h-4" />
              文章库
            </button>
          </div>
        </div>

        {/* Quick actions */}
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 mt-6">
          <button
            onClick={() => setShowImport(true)}
            className="flex items-center gap-3 p-3 rounded-xl bg-white/60 dark:bg-slate-800/60 hover:bg-white dark:hover:bg-slate-800 transition-all text-left group"
          >
            <div className="w-9 h-9 rounded-lg bg-primary-100 dark:bg-primary-900 flex items-center justify-center text-primary-600 dark:text-primary-400 group-hover:scale-110 transition-transform">
              <Upload className="w-4 h-4" />
            </div>
            <div>
              <div className="text-sm font-medium text-gray-800 dark:text-gray-200">导入文章</div>
              <div className="text-[11px] text-gray-400">TXT / Word / PDF</div>
            </div>
          </button>
          <button
            onClick={() => {
              setShowImport(true);
            }}
            className="flex items-center gap-3 p-3 rounded-xl bg-white/60 dark:bg-slate-800/60 hover:bg-white dark:hover:bg-slate-800 transition-all text-left group"
          >
            <div className="w-9 h-9 rounded-lg bg-accent-100 dark:bg-accent-900 flex items-center justify-center text-accent-600 dark:text-accent-400 group-hover:scale-110 transition-transform">
              <Plus className="w-4 h-4" />
            </div>
            <div>
              <div className="text-sm font-medium text-gray-800 dark:text-gray-200">新建文章</div>
              <div className="text-[11px] text-gray-400">手动输入内容</div>
            </div>
          </button>
          <button
            onClick={() => navigate('/vocabulary')}
            className="flex items-center gap-3 p-3 rounded-xl bg-white/60 dark:bg-slate-800/60 hover:bg-white dark:hover:bg-slate-800 transition-all text-left group"
          >
            <div className="w-9 h-9 rounded-lg bg-macaron-yellow/40 dark:bg-yellow-900/40 flex items-center justify-center text-yellow-700 dark:text-yellow-400 group-hover:scale-110 transition-transform">
              <Sparkles className="w-4 h-4" />
            </div>
            <div>
              <div className="text-sm font-medium text-gray-800 dark:text-gray-200">生词本</div>
              <div className="text-[11px] text-gray-400">复习收藏的单词</div>
            </div>
          </button>
          <button
            onClick={() => navigate('/basics')}
            className="flex items-center gap-3 p-3 rounded-xl bg-white/60 dark:bg-slate-800/60 hover:bg-white dark:hover:bg-slate-800 transition-all text-left group"
          >
            <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-primary-100 to-accent-100 dark:from-primary-900 dark:to-accent-900 flex items-center justify-center text-primary-600 dark:text-primary-400 group-hover:scale-110 transition-transform">
              <GraduationCap className="w-4 h-4" />
            </div>
            <div>
              <div className="text-sm font-medium text-gray-800 dark:text-gray-200">基础学习</div>
              <div className="text-[11px] text-gray-400">字母/音标/五十音</div>
            </div>
          </button>
          <button
            onClick={() => navigate('/settings')}
            className="flex items-center gap-3 p-3 rounded-xl bg-white/60 dark:bg-slate-800/60 hover:bg-white dark:hover:bg-slate-800 transition-all text-left group"
          >
            <div className="w-9 h-9 rounded-lg bg-macaron-pink/30 dark:bg-pink-900/30 flex items-center justify-center text-pink-600 dark:text-pink-400 group-hover:scale-110 transition-transform">
              <BookOpen className="w-4 h-4" />
            </div>
            <div>
              <div className="text-sm font-medium text-gray-800 dark:text-gray-200">学习设置</div>
              <div className="text-[11px] text-gray-400">偏好与外观</div>
            </div>
          </button>
        </div>
      </div>

      {/* Check-in Card */}
      <div className="mb-6">
        <CheckInCard />
      </div>

      {/* Stats Summary (极简版) */}
      <div className="mb-6">
        <StatsSummary />
      </div>

      {/* Language Filter */}
      <div className="flex items-center gap-2 mb-5 overflow-x-auto pb-1 scrollbar-thin">
        <button
          onClick={() => setActiveLanguage('all')}
          className={cn(
            'px-3.5 py-1.5 rounded-xl text-xs font-medium whitespace-nowrap transition-all',
            activeLanguage === 'all'
              ? 'bg-primary-500 text-white shadow-sm'
              : 'bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
          )}
        >
          全部
        </button>
        {languages.map(([key, name]) => (
          <button
            key={key}
            onClick={() => setActiveLanguage(key)}
            className={cn(
              'px-3.5 py-1.5 rounded-xl text-xs font-medium whitespace-nowrap transition-all',
              activeLanguage === key
                ? 'bg-primary-500 text-white shadow-sm'
                : 'bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
            )}
          >
            {name}
          </button>
        ))}
      </div>

      {/* Category Filter */}
      <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-1 scrollbar-thin">
        <button
          onClick={() => setActiveCategory('all')}
          className={cn(
            'px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all',
            activeCategory === 'all'
              ? 'bg-accent-100 dark:bg-accent-900 text-accent-700 dark:text-accent-300'
              : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
          )}
        >
          全部
        </button>
        {categories.map((cat) => (
          <button
            key={cat.id}
            onClick={() => setActiveCategory(cat.id)}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all',
              activeCategory === cat.id
                ? 'bg-accent-100 dark:bg-accent-900 text-accent-700 dark:text-accent-300'
                : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
            )}
          >
            {cat.icon} {cat.name}
          </button>
        ))}
      </div>

      {/* Article List */}
      {recentArticles.length > 0 ? (
        <>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-sm font-semibold text-gray-700 dark:text-gray-300">最近学习</h2>
            {articles.length > 8 && (
              <button
                onClick={() => navigate('/articles')}
                className="text-xs text-primary-600 hover:text-primary-700 flex items-center gap-1"
              >
                查看全部 <ArrowRight className="w-3 h-3" />
              </button>
            )}
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {recentArticles.map((article) => (
              <ArticleCard
                key={article.id}
                article={article}
                onClick={() => {
                  setSelectedLanguage(article.targetLanguage);
                  navigate(`/read/${article.id}`);
                }}
              />
            ))}
          </div>
        </>
      ) : (
        <EmptyState
          icon={<BookOpen className="w-12 h-12" />}
          title="还没有文章"
          description="导入一篇你的文章，或者手动输入内容，开始你的沉浸式外语学习之旅"
          action={
            <button onClick={() => setShowImport(true)} className="btn-primary">
              <Plus className="w-4 h-4" /> 导入第一篇文章
            </button>
          }
        />
      )}

      {/* Import Modal */}
      <ImportModal isOpen={showImport} onClose={() => setShowImport(false)} />
    </div>
  );
}