export type Language = 'zh' | 'en' | 'ja' | 'ru' | 'es' | 'ko' | 'fr' | 'de' | 'ar';

export type PartOfSpeech = 'noun' | 'verb' | 'adjective' | 'adverb' | 'preposition' | 'conjunction' | 'pronoun' | 'determiner';

export type Difficulty = 'beginner' | 'intermediate' | 'advanced';

export type ViewMode = 'line-by-line' | 'side-by-side' | 'top-bottom' | 'single-original' | 'single-translation';

export type ReadMode = 'parallel' | 'replace';

export interface ReplaceConfig {
  ratio: number;
  posFilter: PartOfSpeech[];
  difficulty: Difficulty;
  language: Language;
  avoidDuplicates: boolean;
  fixedPhrases: string[];
  customWords: string[];
}

export interface Article {
  id: string;
  title: string;
  content: string;
  translation?: string;
  sourceLanguage: Language;
  targetLanguage: Language;
  categoryId: string;
  createdAt: number;
  updatedAt: number;
  tags: string[];
  replaceConfig?: ReplaceConfig;
  wordReplacements?: WordReplacement[];
}

export interface WordReplacement {
  originalWord: string;
  replacementWord: string;
  position: number;
  partOfSpeech?: PartOfSpeech;
  phonetic?: string;
  translation: string;
  /** 日语替换词假名注音（前向兼容） */
  reading?: string;
}

export interface VocabularyWord {
  id: string;
  word: string;
  translation: string;
  language: Language;
  phonetic?: string;
  partOfSpeech?: string;
  /** 日语假名注音 / 其他语种发音标注 */
  reading?: string;
  /** 音节划分（英语，如 dic·tion·ar·y） */
  syllables?: string;
  /** 标记已掌握，从复习队列中排除 */
  mastered?: boolean;
  sourceArticleId: string;
  sourceSentence: string;
  difficulty: Difficulty;
  reviewCount: number;
  lastReviewAt?: number;
  createdAt: number;
  // ─── 艾宾浩斯复习字段（SM-2 算法） ───
  /** 难度系数，默认 2.5 */
  easeFactor: number;
  /** 当前间隔（天） */
  interval: number;
  /** 连续正确次数 */
  repetitions: number;
  /** 下次复习时间戳（毫秒） */
  nextReviewAt: number;
  /** 最近一次评级 0-3 */
  lastRating?: ReviewRating;
}

/** 复习评级
 * 0 = Again（完全忘记，需重置）
 * 1 = Hard（吃力，间隔 × 1.2）
 * 2 = Good（认识了，间隔 × easeFactor）
 * 3 = Easy（简单，间隔 × easeFactor × 1.3）
 */
export type ReviewRating = 0 | 1 | 2 | 3;

export interface Category {
  id: string;
  name: string;
  parentId?: string;
  icon?: string;
  articleCount: number;
}

/** 后端公共文章（时间字段为 ISO 字符串） */
export interface PublicArticle {
  id: string;
  title: string;
  content: string;
  translation: string;
  sourceLanguage: Language;
  targetLanguage: Language;
  categoryId: string | null;
  category?: { id: string; name: string; icon?: string | null } | null;
  tags: string[];
  viewCount: number;
  createdAt: string;
  updatedAt: string;
}

/** 投稿状态 */
export type SubmissionStatus = 'PENDING_REVIEW' | 'PUBLISHED' | 'REJECTED' | 'ARCHIVED';

/** 投稿列表项（不含 content/translation） */
export interface SubmissionItem {
  id: string;
  title: string;
  sourceLanguage: Language;
  targetLanguage: Language;
  status: SubmissionStatus;
  reviewNote: string | null;
  reviewedAt: string | null;
  categoryId: string | null;
  category?: { id: string; name: true } | null;
  tags: string[];
  createdAt: string;
  updatedAt: string;
}

/** 分页数据 */
export interface PageData<T> {
  list: T[];
  total: number;
  page: number;
  pageSize: number;
}

export interface AppSettings {
  theme: 'light' | 'dark' | 'system';
  defaultTargetLanguage: Language;
  fontSize: number;
  lineHeight: number;
  fontFamily: 'sans' | 'serif' | 'mono';
  autoSync: boolean;
  speechRate: number;
  // 换词参数
  replaceRatio: number;
  replacePosFilter: PartOfSpeech[];
  replaceDifficulty: Difficulty;
  replaceAvoidDuplicates: boolean;
  // 阅读布局设置
  readingLayout: 'line-by-line' | 'parallel' | 'vertical'; // 行对行/并排/上下
  parallelPosition: 'left-translated' | 'right-translated'; // 并排时译文位置
  verticalPosition: 'top-translated' | 'bottom-translated'; // 上下时译文位置
  parallelRatio: number; // 并排模式下原文/译文宽度占比 (0.3-0.7)
}

