/**
 * 公共文章库 + 学习者投稿 API
 */
import { apiGet, apiPost, apiDelete } from './client';
import type { PublicArticle, SubmissionItem, PageData, Category, Language } from '@/types';

// ─── 公共文章库 ─────────────────────────────

export interface PublicArticleQuery {
  page?: number;
  pageSize?: number;
  keyword?: string;
  categoryId?: string;
  sourceLanguage?: Language;
  targetLanguage?: Language;
  order?: 'asc' | 'desc';
}

/** 公共文章列表（轻量，不含 content/translation） */
export function getPublicArticles(params: PublicArticleQuery = {}) {
  const query = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v !== undefined && v !== '') query.append(k, String(v));
  });
  return apiGet<PageData<PublicArticle>>(`/public/articles?${query.toString()}`);
}

/** 公共文章详情（含 content + translation） */
export function getPublicArticle(id: string) {
  return apiGet<PublicArticle>(`/public/articles/${id}`);
}

/** 公共分类列表 */
export function getPublicCategories() {
  return apiGet<{ list: Array<Category & { _count?: { articles: number } }> }>(`/public/categories`);
}

// ─── 学习者投稿 ─────────────────────────────

export interface SubmitArticleData {
  title: string;
  content: string;
  translation: string;
  sourceLanguage: Language;
  targetLanguage: Language;
  categoryId?: string;
  tags?: string[];
}

/** 投稿到公共库 */
export function submitArticle(data: SubmitArticleData) {
  return apiPost<PublicArticle>('/learner/articles/submit', data);
}

/** 我的投稿列表 */
export function getMySubmissions(params: {
  page?: number;
  pageSize?: number;
  status?: string;
  keyword?: string;
} = {}) {
  const query = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v !== undefined && v !== '') query.append(k, String(v));
  });
  return apiGet<PageData<SubmissionItem>>(`/learner/articles/submissions?${query.toString()}`);
}

/** 撤回投稿 */
export function cancelSubmission(id: string) {
  return apiDelete<null>(`/learner/articles/submissions/${id}`);
}
