/**
 * 腾讯翻译君 TMT API 接入
 * 免费额度：每月 500 万字符（标准版）
 * API 文档：https://cloud.tencent.com/document/api/551/15619
 *
 * 签名在 Vite 服务端中间件完成（vite.config.ts），密钥不暴露给客户端
 */

import type { Language } from '@/types';

// 腾讯 TMT 语种代码映射（与项目 Language 基本一致）
const TENCENT_LANG_MAP: Record<Language, string> = {
  zh: 'zh',
  en: 'en',
  ja: 'ja',
  ru: 'ru',
  es: 'es',
  ko: 'ko',
  fr: 'fr',
  de: 'de',
  ar: 'ar',
};

/**
 * 清洗腾讯翻译结果中常见的噪声：
 * 1. 目标为中文时，去除译文中的英文括注，如 "实验（Laboratory）" → "实验"
 *    （腾讯有时在中文译文末尾附加英文原词，对双语阅读无益）
 * 2. 去除"词语（同词）"形式的重复括注，如 "学习（学习）" → "学习"
 */
function cleanTranslation(text: string, to: Language): string {
  if (!text) return text;
  let cleaned = text;
  if (to === 'zh') {
    // 去除全角/半角括号内的纯英文内容（含空格、连字符、撇号），如 （Laboratory）(AI)
    cleaned = cleaned.replace(/[（(][A-Za-z][A-Za-z\s\-']*[）)]/g, '');
  }
  // 去除"词语（同词）"形式的重复括注
  cleaned = cleaned.replace(/([^\s（()]+)[（(]\1[）)]/g, '$1');
  // 清理残留的多余空格
  cleaned = cleaned.replace(/\s{2,}/g, ' ').trim();
  return cleaned;
}

/**
 * 调用腾讯翻译 API（通过服务端中间件代理，签名在服务器完成）
 * 返回所有翻译结果（支持多行批量翻译）
 */
export async function tencentTranslateRaw(
  text: string,
  from: Language,
  to: Language
): Promise<string[]> {
  const response = await fetch('/api/tencent-translate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      text,
      from: TENCENT_LANG_MAP[from] || 'auto',
      to: TENCENT_LANG_MAP[to] || 'zh',
    }),
  });

  const data = await response.json();

  if (data.error_code) {
    const errorMsg = getTencentErrorTip(data.error_code);
    console.warn(`[翻译] 腾讯返回 [${data.error_code}]: ${data.error_msg}（${errorMsg}）`);
    throw new Error(errorMsg);
  }

  if (!data.trans_result || data.trans_result.length === 0) {
    return [text];
  }

  return data.trans_result.map((item: { dst: string }) => cleanTranslation(item.dst, to));
}

/**
 * 单句翻译（返回第一条翻译结果）
 */
export async function tencentTranslate(
  text: string,
  from: Language,
  to: Language
): Promise<string> {
  const results = await tencentTranslateRaw(text, from, to);
  return results[0] || text;
}

/**
 * 腾讯翻译错误码中文提示
 */
function getTencentErrorTip(code: string): string {
  const tips: Record<string, string> = {
    'AuthFailure.SignatureFailure': '签名错误（请检查 SecretId/SecretKey 是否正确）',
    'AuthFailure.SecretIdNotFound': '密钥不存在',
    'AuthFailure.TokenFailure': '临时证书 Token 错误',
    InternalError: '服务内部错误，请稍后重试',
    InvalidParameter: '参数错误',
    LimitExceeded: '请求频率超过限制',
    MissingParameter: '缺少参数',
    ResourceInsufficient: '资源不足',
    UnauthorizedOperation: '未授权操作',
    UnknownParameter: '未知参数',
    UnsupportedOperation: '操作不支持',
  };
  return tips[code] || `未知错误 (${code})`;
}

/**
 * 批量翻译：将多句文本合并为一次 API 请求（TMT TextTranslateBatch 支持数组）
 * 单次请求上限约 6000 字节，超出则自动分批
 */
const BATCH_SIZE_LIMIT = 5000; // 留 buffer 避免超限

export async function tencentTranslateBatch(
  sentences: string[],
  from: Language,
  to: Language
): Promise<string[]> {
  if (sentences.length === 0) return [];

  const results: string[] = [];
  let batch: string[] = [];
  let batchSize = 0;

  const flushBatch = async () => {
    if (batch.length === 0) return;
    const combined = batch.join('\n');
    const translated = await tencentTranslateRaw(combined, from, to);

    // 对齐：如果返回数量少于发送数量，用空字符串补齐
    for (let i = 0; i < batch.length; i++) {
      results.push(translated[i] || batch[i]);
    }
    batch = [];
    batchSize = 0;
  };

  for (const sentence of sentences) {
    const sentenceSize = new TextEncoder().encode(sentence).length;

    // 单句超限则单独发送
    if (sentenceSize >= BATCH_SIZE_LIMIT) {
      await flushBatch();
      const singleResult = await tencentTranslateRaw(sentence, from, to);
      results.push(singleResult[0] || sentence);
      continue;
    }

    // 当前批次加这句会超限，先发送当前批次
    if (batchSize + sentenceSize > BATCH_SIZE_LIMIT) {
      await flushBatch();
    }

    batch.push(sentence);
    batchSize += sentenceSize;
  }

  // 发送最后一批
  await flushBatch();
  return results;
}

/**
 * 检查腾讯翻译 API 是否"真正可用"。
 * 仅看 env 是否配置不够——密钥可能无效。因此先看 env，再用真实探测翻译验签。
 */
let _configuredCache: boolean | null = null;

export async function isTencentConfigured(): Promise<boolean> {
  if (_configuredCache !== null) return _configuredCache;
  // 1) 先看 env 是否配置（未配置直接 false，不发探测请求）
  try {
    const res = await fetch('/api/tencent-translate');
    const data = await res.json();
    if (!data.configured) {
      _configuredCache = false;
      return false;
    }
  } catch {
    _configuredCache = false;
    return false;
  }
  // 2) env 已配置，但密钥可能无效——做一次真实探测翻译验签
  try {
    await tencentTranslateRaw('hello', 'en', 'zh');
    _configuredCache = true;
  } catch {
    console.warn(
      '[翻译] 腾讯密钥已配置但验证失败，翻译将回退到 MyMemory/百度。请检查 .env 中 TENCENT_SECRET_ID / TENCENT_SECRET_KEY。'
    );
    _configuredCache = false;
  }
  return _configuredCache;
}

/**
 * 单词级翻译：调用腾讯翻译 API 翻译单个词语
 * 用于选词查词场景
 */
export async function translateWordWithTencent(
  word: string,
  from: Language,
  to: Language
): Promise<string | null> {
  try {
    const result = await tencentTranslate(word, from, to);
    // 如果返回结果和原文一样，说明翻译失败
    if (result === word) return null;
    return result;
  } catch {
    return null;
  }
}
