import { useState } from 'react';
import { Settings2, RotateCcw } from 'lucide-react';
import { useArticleStore } from '@/stores/articleStore';
import type { Language, PartOfSpeech, Difficulty } from '@/types';
import { LANGUAGE_NAMES, POS_NAMES, DIFFICULTY_NAMES } from '@/types';

interface ReplaceConfigPanelProps {
  articleId: string;
  onApply: (config: {
    ratio: number;
    posFilter: PartOfSpeech[];
    difficulty: Difficulty;
    avoidDuplicates: boolean;
  }) => void;
}

export default function ReplaceConfigPanel({ articleId, onApply }: ReplaceConfigPanelProps) {
  const { articles, updateReplaceConfig } = useArticleStore();
  const article = articles.find((a) => a.id === articleId);
  const config = article?.replaceConfig;

  const [ratio, setRatio] = useState(config?.ratio ?? 0.3);
  const [language, setLanguage] = useState<Language>(config?.language ?? article?.targetLanguage ?? 'en');
  const [difficulty, setDifficulty] = useState<Difficulty>(config?.difficulty ?? 'beginner');
  const [posFilter, setPosFilter] = useState<PartOfSpeech[]>(config?.posFilter ?? ['noun', 'verb', 'adjective']);
  const [avoidDuplicates, setAvoidDuplicates] = useState(config?.avoidDuplicates ?? true);

  const togglePos = (pos: PartOfSpeech) => {
    setPosFilter((prev) =>
      prev.includes(pos) ? prev.filter((p) => p !== pos) : [...prev, pos]
    );
  };

  const handleApply = () => {
    const applyConfig = {
      ratio,
      posFilter,
      difficulty,
      language,
      avoidDuplicates,
      fixedPhrases: config?.fixedPhrases ?? [],
      customWords: config?.customWords ?? [],
    };
    updateReplaceConfig(articleId, applyConfig);
    onApply({ ratio, posFilter, difficulty, avoidDuplicates });
  };

  return (
    <div className="card p-5 space-y-5">
      <div className="flex items-center gap-2">
        <Settings2 className="w-4 h-4 text-primary-600" />
        <h3 className="font-semibold text-sm text-gray-800 dark:text-gray-100">换词参数设置</h3>
      </div>

      {/* Replace Ratio */}
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-2">
          替换强度：{Math.round(ratio * 100)}%
        </label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.05"
          value={ratio}
          onChange={(e) => setRatio(Number(e.target.value))}
          className="w-full h-2 bg-gray-200 dark:bg-slate-600 rounded-full appearance-none cursor-pointer accent-primary-500"
        />
        <div className="flex justify-between text-[10px] text-gray-400 mt-1">
          <span>0%</span>
          <span>25%</span>
          <span>50%</span>
          <span>75%</span>
          <span>100%</span>
        </div>
      </div>

      {/* Language */}
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">目标语种</label>
        <select
          value={language}
          onChange={(e) => setLanguage(e.target.value as Language)}
          className="input-field text-sm"
        >
          {Object.entries(LANGUAGE_NAMES).map(([key, name]) => (
            <option key={key} value={key}>{name}</option>
          ))}
        </select>
      </div>

      {/* Difficulty */}
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">难度分级</label>
        <div className="flex gap-2">
          {(Object.entries(DIFFICULTY_NAMES) as [Difficulty, string][]).map(([key, name]) => (
            <button
              key={key}
              onClick={() => setDifficulty(key)}
              className={`flex-1 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                difficulty === key
                  ? 'bg-accent-100 text-accent-700 ring-1 ring-accent-300 dark:bg-accent-900 dark:text-accent-300'
                  : 'bg-gray-50 text-gray-500 hover:bg-gray-100 dark:bg-slate-700 dark:text-gray-400'
              }`}
            >
              {name}
            </button>
          ))}
        </div>
      </div>

      {/* Part of Speech Filter */}
      <div>
        <label className="block text-xs font-medium text-gray-500 mb-1.5">词性筛选</label>
        <div className="flex flex-wrap gap-1.5">
          {(Object.entries(POS_NAMES) as [PartOfSpeech, string][]).map(([key, name]) => (
            <button
              key={key}
              onClick={() => togglePos(key)}
              className={`px-2.5 py-1 rounded-lg text-[11px] font-medium transition-all ${
                posFilter.includes(key)
                  ? 'bg-primary-100 text-primary-700 ring-1 ring-primary-300 dark:bg-primary-900 dark:text-primary-300'
                  : 'bg-gray-50 text-gray-500 hover:bg-gray-100 dark:bg-slate-700 dark:text-gray-400'
              }`}
            >
              {name}
            </button>
          ))}
        </div>
      </div>

      {/* Options */}
      <label className="flex items-center gap-2 cursor-pointer">
        <input
          type="checkbox"
          checked={avoidDuplicates}
          onChange={(e) => setAvoidDuplicates(e.target.checked)}
          className="w-4 h-4 rounded border-gray-300 text-primary-500 focus:ring-primary-400"
        />
        <span className="text-xs text-gray-600 dark:text-gray-400">同一篇文章内避免重复替换同一个词</span>
      </label>

      {/* Apply Button */}
      <button onClick={handleApply} className="btn-primary w-full">
        <RotateCcw className="w-4 h-4" />
        应用换词
      </button>
    </div>
  );
}