/**
 * 单词级翻译 API 缓存
 *
 * - 存 Promise 而非值：防止并发选同一词触发 N 次 API（首次 in-flight 期间并发都拿到同一 Promise）
 * - key = `${from}|${to}|${wordLower}`：大小写不敏感、跨语种不冲突
 * - 会话级缓存：不持久化到 localStorage（避免脏数据 + 翻译语种切换不一致）
 * - 复用 translateWord() 的腾讯→百度→MyMemory 降级链
 */

import { translateWord } from '@/services/baiduTranslate';
import type { Language } from '@/types';

const cache = new Map<string, Promise<string | null>>();

export function lookupWord(
  word: string,
  from: Language,
  to: Language
): Promise<string | null> {
  const key = `${from}|${to}|${word.toLowerCase().trim()}`;
  let p = cache.get(key);
  if (!p) {
    p = translateWord(word, from, to).catch(() => null);
    cache.set(key, p);
  }
  return p;
}

/** 切换文章/卸载时清空，避免长时间会话内存膨胀 */
export function clearWordLookupCache(): void {
  cache.clear();
}
