/**
 * 学习数据统计工具
 *
 * 设计原则：
 * - 不持久化新数据，所有指标从现有 store 派生
 * - 全部为纯函数（除 Date.now() 外无副作用）
 * - 集中管理聚合逻辑，便于复用
 */

import type { Article, VocabularyWord } from '@/types';
import { calcStreak, calcTotalDays, toDateKey } from '@/lib/checkIn';
import { isDue } from '@/lib/ebbinghaus';

export interface ArticleStats {
  total: number;
  byLanguage: Record<string, number>;
  recent5: Article[]; // 最近更新的 5 篇
  totalChars: number; // 累计字数
}

export interface VocabStats {
  total: number;
  byLanguage: Record<string, number>;
  byStage: {
    new: number; // 复习 0 次
    learning: number; // 1-3 次
    reviewing: number; // 4-10 次
    mastered: number; // > 10 次
  };
  dueCount: number; // 待复习
  reviewedCount: number; // 累计复习次数
  averageEaseFactor: number; // 平均难度系数
  ratingDistribution: Record<0 | 1 | 2 | 3, number>; // 复习评分分布
}

export interface CheckInStats {
  totalDays: number;
  currentStreak: number;
  longestStreak: number; // 历史最长
  last30Days: { key: string; checked: boolean }[]; // 30 天热力图
  todayChecked: boolean;
}

/** 计算文章统计 */
export function calcArticleStats(articles: Article[]): ArticleStats {
  const byLanguage: Record<string, number> = {};
  let totalChars = 0;
  for (const a of articles) {
    byLanguage[a.targetLanguage] = (byLanguage[a.targetLanguage] || 0) + 1;
    totalChars += (a.content || '').length;
  }
  const recent5 = [...articles]
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .slice(0, 5);
  return { total: articles.length, byLanguage, recent5, totalChars };
}

/** 计算生词统计 */
export function calcVocabStats(words: VocabularyWord[]): VocabStats {
  const byLanguage: Record<string, number> = {};
  const ratingDistribution: Record<0 | 1 | 2 | 3, number> = { 0: 0, 1: 0, 2: 0, 3: 0 };
  let totalEF = 0;
  let efCount = 0;
  let reviewedCount = 0;
  const byStage = { new: 0, learning: 0, reviewing: 0, mastered: 0 };

  for (const w of words) {
    byLanguage[w.language] = (byLanguage[w.language] || 0) + 1;
    reviewedCount += w.reviewCount || 0;

    // 阶段划分
    if (!w.reviewCount || w.reviewCount === 0) byStage.new++;
    else if (w.reviewCount <= 3) byStage.learning++;
    else if (w.reviewCount <= 10) byStage.reviewing++;
    else byStage.mastered++;

    if (typeof w.easeFactor === 'number') {
      totalEF += w.easeFactor;
      efCount++;
    }
    if (typeof w.lastRating === 'number') {
      ratingDistribution[w.lastRating]++;
    }
  }

  return {
    total: words.length,
    byLanguage,
    byStage,
    dueCount: words.filter((w) => isDue(w)).length,
    reviewedCount,
    averageEaseFactor: efCount > 0 ? totalEF / efCount : 2.5,
    ratingDistribution,
  };
}

/** 计算打卡统计 */
export function calcCheckInStats(checkInDays: Record<string, boolean>, now: number = Date.now()): CheckInStats {
  const todayChecked = Boolean(checkInDays[toDateKey(now)]);
  const currentStreak = calcStreak(checkInDays, now);

  // 计算历史最长连胜
  let longestStreak = 0;
  const sortedKeys = Object.keys(checkInDays).filter((k) => checkInDays[k]).sort();
  if (sortedKeys.length > 0) {
    let run = 1;
    let prevDate = new Date(sortedKeys[0]);
    for (let i = 1; i < sortedKeys.length; i++) {
      const cur = new Date(sortedKeys[i]);
      const diff = (cur.getTime() - prevDate.getTime()) / (24 * 60 * 60 * 1000);
      if (Math.round(diff) === 1) {
        run++;
        if (run > longestStreak) longestStreak = run;
      } else {
        run = 1;
      }
      prevDate = cur;
    }
    longestStreak = Math.max(longestStreak, run);
  }

  // 最近 30 天
  const last30Days: { key: string; checked: boolean }[] = [];
  for (let i = 29; i >= 0; i--) {
    const key = toDateKey(now - i * 24 * 60 * 60 * 1000);
    last30Days.push({ key, checked: Boolean(checkInDays[key]) });
  }

  return {
    totalDays: calcTotalDays(checkInDays),
    currentStreak,
    longestStreak,
    last30Days,
    todayChecked,
  };
}

/** 整合所有统计 */
export interface AllStats {
  article: ArticleStats;
  vocab: VocabStats;
  checkIn: CheckInStats;
}

export function calcAllStats(
  articles: Article[],
  words: VocabularyWord[],
  checkInDays: Record<string, boolean>
): AllStats {
  return {
    article: calcArticleStats(articles),
    vocab: calcVocabStats(words),
    checkIn: calcCheckInStats(checkInDays),
  };
}

/** 计算总学习天数（打卡天数 ∪ 有复习记录的天数） */
export function calcActiveDays(
  words: VocabularyWord[],
  checkInDays: Record<string, boolean>
): number {
  const days = new Set<string>();
  for (const k of Object.keys(checkInDays)) {
    if (checkInDays[k]) days.add(k);
  }
  for (const w of words) {
    if (w.lastReviewAt) {
      days.add(toDateKey(w.lastReviewAt));
    }
    if (w.createdAt) {
      days.add(toDateKey(w.createdAt));
    }
  }
  return days.size;
}
