import { X, Volume2, BookmarkPlus } from 'lucide-react';
import { useUIStore } from '@/stores/uiStore';
import { useVocabularyStore } from '@/stores/vocabularyStore';
import { useSettingsStore } from '@/stores/settingsStore';
import type { VocabularyWord } from '@/types';
import { useEffect, useRef } from 'react';
import { speak } from '@/lib/speech';
import { createInitialReviewState } from '@/lib/ebbinghaus';
import { toKatakana } from '@/lib/jaFurigana';

export default function WordModal() {
  const { showWordModal, selectedWord, hideWordDetail } = useUIStore();
  const { words, addWord } = useVocabularyStore();
  const { settings } = useSettingsStore();
  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') hideWordDetail();
    };
    if (showWordModal) {
      document.addEventListener('keydown', handleKeyDown);
      return () => document.removeEventListener('keydown', handleKeyDown);
    }
  }, [showWordModal, hideWordDetail]);

  if (!showWordModal || !selectedWord) return null;

  const isSaved = words.some(
    (w) => w.word === selectedWord.word
  );

  const handleSave = () => {
    if (isSaved) return;
    const lang = selectedWord.language || 'en';
    const newWord: VocabularyWord = {
      id: crypto.randomUUID(),
      word: selectedWord.word,
      translation: selectedWord.translation,
      language: lang,
      phonetic: selectedWord.phonetic,
      partOfSpeech: selectedWord.partOfSpeech,
      reading: selectedWord.reading,
      syllables: selectedWord.syllables,
      sourceArticleId: '',
      sourceSentence: '',
      difficulty: 'beginner',
      reviewCount: 0,
      createdAt: Date.now(),
      ...createInitialReviewState(),
    };
    addWord(newWord);
  };

  const handleSpeak = () => {
    const lang = selectedWord.language || 'en';
    speak({ text: selectedWord.word, lang, rate: settings.speechRate });
  };

  return (
    <div className="modal-overlay" onClick={hideWordDetail}>
      <div
        ref={modalRef}
        className="modal-content max-w-sm"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            {selectedWord.partOfSpeech && (
              <span className="tag bg-macaron-purple/20 text-accent-700 text-xs">
                {selectedWord.partOfSpeech}
              </span>
            )}
          </div>
          <button
            onClick={hideWordDetail}
            className="w-7 h-7 rounded-lg flex items-center justify-center hover:bg-gray-100 dark:hover:bg-slate-700 text-gray-400 hover:text-gray-600 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Word */}
        <div className="mb-3">
          {selectedWord.language === 'ja' && selectedWord.reading ? (
            <>
              <h2 className="text-2xl font-bold text-gray-800 dark:text-gray-100 mb-1">
                <ruby>
                  {selectedWord.word}
                  <rp>(</rp>
                  <rt className="text-xs text-primary-500 dark:text-primary-400">{selectedWord.reading}</rt>
                  <rp>)</rp>
                </ruby>
              </h2>
              <p className="text-xs text-gray-400 mb-1">
                平假名: {selectedWord.reading} · 片假名: {toKatakana(selectedWord.reading)}
              </p>
            </>
          ) : (
            <>
              <h2 className="text-2xl font-bold text-gray-800 dark:text-gray-100 mb-1">
                {selectedWord.word}
              </h2>
              {selectedWord.phonetic && (
                <p className="text-sm text-gray-400 font-mono">/{selectedWord.phonetic}/</p>
              )}
              {selectedWord.syllables && (
                <p className="text-xs text-accent-500">{selectedWord.syllables}</p>
              )}
            </>
          )}
        </div>

        {/* Translation */}
        <p className="text-lg text-gray-600 dark:text-gray-300 mb-6">
          {selectedWord.translation}
        </p>

        {/* Actions */}
        <div className="flex items-center gap-3">
          <button
            onClick={handleSpeak}
            className="btn-secondary !px-3 !py-2"
            title="朗读发音"
          >
            <Volume2 className="w-4 h-4" />
            <span>发音</span>
          </button>
          <button
            onClick={handleSave}
            disabled={isSaved}
            className={isSaved ? 'btn-secondary !px-3 !py-2 opacity-50' : 'btn-primary !px-3 !py-2'}
          >
            <BookmarkPlus className="w-4 h-4" />
            <span>{isSaved ? '已收藏' : '收藏生词'}</span>
          </button>
        </div>
      </div>
    </div>
  );
}