/**
 * 百度翻译 API 接入
 * 免费额度：100 万字符/月
 * API 文档：https://fanyi-api.baidu.com/
 *
 * 签名在 Vite 服务端中间件完成（vite.config.ts），密钥不暴露给客户端
 */

import type { Language } from '@/types';
import { mymemoryTranslate } from './mymemoryTranslate';
import { translateWordWithTencent } from './tencentTranslate';

// 百度翻译语种代码映射
const BAIDU_LANG_MAP: Record<Language, string> = {
  zh: 'zh',
  en: 'en',
  ja: 'jp',
  ru: 'ru',
  es: 'spa',
  ko: 'kor',
  fr: 'fra',
  de: 'de',
  ar: 'ara',
};

/**
 * 调用百度翻译 API（通过服务端中间件代理，签名在服务器完成）
 * 返回所有翻译结果（支持多行批量翻译）
 */
export async function baiduTranslateRaw(
  text: string,
  from: Language,
  to: Language
): Promise<string[]> {
  const response = await fetch('/api/baidu-translate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      text,
      from: BAIDU_LANG_MAP[from] || 'auto',
      to: BAIDU_LANG_MAP[to] || 'en',
    }),
  });

  const data = await response.json();

  if (data.error_code) {
    const errorMsg = getBaiduErrorTip(data.error_code);
    // 降级为 warn：调用方已有 MyMemory 降级链，百度失败不再是致命错误
    console.warn(`[翻译] 百度返回 [${data.error_code}]: ${data.error_msg}（${errorMsg}）`);
    throw new Error(errorMsg);
  }

  if (!data.trans_result || data.trans_result.length === 0) {
    return [text];
  }

  return data.trans_result.map((item: { dst: string }) => item.dst);
}

/**
 * 单句翻译（返回第一条翻译结果）
 */
export async function baiduTranslate(
  text: string,
  from: Language,
  to: Language
): Promise<string> {
  const results = await baiduTranslateRaw(text, from, to);
  return results[0] || text;
}

/**
 * 百度翻译错误码中文提示
 */
function getBaiduErrorTip(code: string): string {
  const tips: Record<string, string> = {
    '52001': '翻译服务超时，请稍后重试',
    '52002': '翻译系统异常，请稍后重试',
    '52003': 'APP ID 或密钥未授权，请检查配置',
    '54000': '请求参数缺失',
    '54001': '签名无效（请检查 APP ID 和密钥是否正确）',
    '54003': '访问频率受限或无权限访问此服务（需在百度翻译开放平台开通翻译服务）',
    '54004': '账户余额不足',
    '54005': '请求频率过高，请稍后重试',
    '58000': '客户端 IP 不在白名单',
    '58001': '源语言不支持',
    '58002': '目标语言不支持',
    '90107': '认证未通过，请确认 APP 已开通翻译服务',
  };
  return tips[code] || `未知错误 (${code})`;
}

/**
 * 批量翻译：将多句文本合并为一次 API 请求（百度 API 用 \n 分隔多行）
 * 单次请求上限约 6000 字节，超出则自动分批
 */
const BATCH_SIZE_LIMIT = 5000; // 留 buffer 避免超限

export async function baiduTranslateBatch(
  sentences: string[],
  from: Language,
  to: Language
): Promise<string[]> {
  if (sentences.length === 0) return [];

  const results: string[] = [];
  let batch: string[] = [];
  let batchSize = 0;

  const flushBatch = async () => {
    if (batch.length === 0) return;
    const combined = batch.join('\n');
    const translated = await baiduTranslateRaw(combined, from, to);

    // 对齐：如果返回数量少于发送数量，用空字符串补齐
    for (let i = 0; i < batch.length; i++) {
      results.push(translated[i] || batch[i]);
    }
    batch = [];
    batchSize = 0;
  };

  for (const sentence of sentences) {
    const sentenceSize = new TextEncoder().encode(sentence).length;

    // 单句超限则单独发送
    if (sentenceSize >= BATCH_SIZE_LIMIT) {
      await flushBatch();
      const singleResult = await baiduTranslateRaw(sentence, from, to);
      results.push(singleResult[0] || sentence);
      continue;
    }

    // 当前批次加这句会超限，先发送当前批次
    if (batchSize + sentenceSize > BATCH_SIZE_LIMIT) {
      await flushBatch();
    }

    batch.push(sentence);
    batchSize += sentenceSize;
  }

  // 发送最后一批
  await flushBatch();
  return results;
}

/**
 * 检查百度翻译 API 是否"真正可用"。
 * 仅看 env 是否配置不够——密钥可能无效（如 54001 签名错误）。
 * 因此先看 env，再用一次真实探测翻译验签，结果缓存（密钥运行期不变）。
 */
let _configuredCache: boolean | null = null;

export async function isBaiduConfigured(): Promise<boolean> {
  if (_configuredCache !== null) return _configuredCache;
  // 1) 先看 env 是否配置（未配置直接 false，不发探测请求）
  try {
    const res = await fetch('/api/baidu-translate');
    const data = await res.json();
    if (!data.configured) {
      _configuredCache = false;
      return false;
    }
  } catch {
    _configuredCache = false;
    return false;
  }
  // 2) env 已配置，但密钥可能无效——做一次真实探测翻译验签
  try {
    await baiduTranslateRaw('hello', 'en', 'zh');
    _configuredCache = true;
  } catch {
    console.warn(
      '[翻译] 百度密钥已配置但验证失败，翻译将回退到 MyMemory。请检查 .env 中 BAIDU_APP_ID / BAIDU_SECRET_KEY。'
    );
    _configuredCache = false;
  }
  return _configuredCache;
}

/**
 * 单词级翻译：用于选词查词场景。
 * 降级链：腾讯 → 百度（仅密钥有效时）→ MyMemory（免费无需 Key）→ null。
 * 这样即使百度密钥未配置/失效，选词查词也不会哑火。
 */
export async function translateWord(
  word: string,
  from: Language,
  to: Language
): Promise<string | null> {
  // 1) 腾讯（优先）
  try {
    const result = await translateWordWithTencent(word, from, to);
    if (result) return result;
  } catch {
    // 继续降级
  }
  // 2) 百度（仅在密钥有效时尝试，避免每次必败的 54001）
  if (await isBaiduConfigured()) {
    try {
      const result = await baiduTranslate(word, from, to);
      if (result && result !== word) return result;
    } catch {
      // 百度单次失败（如限流），继续降级
    }
  }
  // 3) MyMemory 降级
  try {
    const result = await mymemoryTranslate(word, from, to);
    if (result && result !== word) return result;
  } catch {
    // 继续降级
  }
  return null;
}
