import { useMemo } from 'react';
import {
  BarChart3,
  BookOpen,
  BookMarked,
  Flame,
  Trophy,
  Sparkles,
  Target,
  Calendar,
  Award,
} from 'lucide-react';
import { useArticleStore } from '@/stores/articleStore';
import { useVocabularyStore } from '@/stores/vocabularyStore';
import { useCheckInStore } from '@/stores/checkInStore';
import BackButton from '@/components/BackButton';
import { calcAllStats, calcActiveDays } from '@/lib/stats';
import { LANGUAGE_NAMES, type Language } from '@/types';
import { cn } from '@/lib/utils';

/**
 * 详细学习数据页面
 * 包含 30 天热力图 / 词汇掌握分布 / 语种分布 / 关键指标
 */
export default function StatsPage() {
  const articles = useArticleStore((s) => s.articles);
  const words = useVocabularyStore((s) => s.words);
  const checkInDays = useCheckInStore((s) => s.checkInDays);

  const stats = useMemo(
    () => calcAllStats(articles, words, checkInDays),
    [articles, words, checkInDays]
  );
  const activeDays = useMemo(
    () => calcActiveDays(words, checkInDays),
    [words, checkInDays]
  );

  const totalVocab = stats.vocab.total;
  const stagePct = (n: number) => (totalVocab > 0 ? Math.round((n / totalVocab) * 100) : 0);

  const totalRatings =
    stats.vocab.ratingDistribution[0] +
    stats.vocab.ratingDistribution[1] +
    stats.vocab.ratingDistribution[2] +
    stats.vocab.ratingDistribution[3];
  const ratingScore =
    totalRatings > 0
      ? Math.round(
          ((stats.vocab.ratingDistribution[2] * 2 +
            stats.vocab.ratingDistribution[3] * 3 +
            stats.vocab.ratingDistribution[1] * 1) /
            (totalRatings * 3)) *
            100
        )
      : 0;

  // 30 天热力图按周对齐（每 7 个一行，前面补空格）
  const heatmap = stats.checkIn.last30Days;
  const firstDayOfWeek = new Date(heatmap[0].key).getDay(); // 0=日
  const paddedHeatmap: Array<{ key: string; checked: boolean; placeholder: boolean }> = [];
  for (let i = 0; i < firstDayOfWeek; i++) {
    paddedHeatmap.push({ key: `pad-${i}`, checked: false, placeholder: true });
  }
  paddedHeatmap.push(...heatmap.map((d) => ({ ...d, placeholder: false })));

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
      {/* 返回按钮 */}
      <BackButton />

      {/* 顶部标题 */}
      <div className="card p-5 sm:p-6 rounded-2xl mb-6">
        <div className="flex items-center gap-2 mb-1">
          <div className="w-9 h-9 rounded-lg bg-gradient-to-br from-primary-400 to-accent-400 flex items-center justify-center text-white">
            <BarChart3 className="w-4 h-4" />
          </div>
          <div>
            <h1 className="text-lg font-semibold text-gray-800 dark:text-gray-100">
              学习数据
            </h1>
            <p className="text-[11px] text-gray-400">数据实时统计 · 仅本设备</p>
          </div>
        </div>
      </div>

      {/* 总览四宫格 */}
      <div className="grid grid-cols-4 gap-2 sm:gap-3 mb-6">
        <OverviewItem icon={BookOpen} label="文章" value={stats.article.total} color="text-primary-500" />
        <OverviewItem icon={BookMarked} label="生词" value={stats.vocab.total} color="text-accent-500" />
        <OverviewItem icon={Flame} label="打卡" value={stats.checkIn.totalDays} color="text-orange-500" />
        <OverviewItem icon={Calendar} label="活跃" value={activeDays} color="text-blue-500" />
      </div>

      {/* 关键指标 */}
      <div className="card p-5 sm:p-6 rounded-2xl mb-6">
        <h2 className="text-sm font-semibold text-gray-700 dark:text-gray-200 mb-3">关键指标</h2>
        <div className="space-y-4">
          <ProgressRow
            icon={<Flame className="w-3.5 h-3.5" />}
            label="连续打卡"
            value={stats.checkIn.currentStreak}
            suffix="天"
            subtext={`历史最长 ${stats.checkIn.longestStreak} 天`}
            color="bg-gradient-to-r from-orange-400 to-amber-400"
          />
          <ProgressRow
            icon={<RotateIcon />}
            label="累计复习"
            value={stats.vocab.reviewedCount}
            suffix="次"
            subtext={`平均 EF ${stats.vocab.averageEaseFactor.toFixed(2)}`}
            color="bg-gradient-to-r from-primary-400 to-accent-400"
          />
          <ProgressRow
            icon={<Target className="w-3.5 h-3.5" />}
            label="待复习单词"
            value={stats.vocab.dueCount}
            suffix="个"
            subtext={stats.vocab.dueCount > 0 ? '建议今日完成' : '今日已清空'}
            color="bg-gradient-to-r from-blue-400 to-cyan-400"
          />
          <ProgressRow
            icon={<Award className="w-3.5 h-3.5" />}
            label="复习评分"
            value={ratingScore}
            suffix="%"
            subtext={`基于 ${totalRatings} 次评分`}
            color="bg-gradient-to-r from-green-400 to-emerald-400"
          />
        </div>
      </div>

      {/* 30 天热力图（按周对齐） */}
      <div className="card p-5 sm:p-6 rounded-2xl mb-6">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-sm font-semibold text-gray-700 dark:text-gray-200 flex items-center gap-1.5">
            <Calendar className="w-3.5 h-3.5 text-blue-500" />
            最近 30 天学习
          </h2>
          <span className="text-[11px] text-gray-400">
            {heatmap.filter((d) => d.checked).length} / 30 天
          </span>
        </div>

        {/* 周标签 + 网格 */}
        <div className="flex gap-1.5">
          <div className="flex flex-col gap-1 text-[9px] text-gray-400 pt-0.5">
            {['一', '三', '五'].map((d) => (
              <span key={d} className="h-3 leading-3">
                {d}
              </span>
            ))}
          </div>
          <div className="flex-1 grid grid-cols-[repeat(7,minmax(0,1fr))] gap-1">
            {paddedHeatmap.map((d) =>
              d.placeholder ? (
                <div key={d.key} className="aspect-square" />
              ) : (
                <div
                  key={d.key}
                  title={`${d.key} ${d.checked ? '✓ 已学习' : '✗ 未学习'}`}
                  className={cn(
                    'aspect-square rounded transition-all',
                    d.checked
                      ? 'bg-gradient-to-br from-emerald-400 to-green-500 shadow-sm'
                      : 'bg-gray-100 dark:bg-slate-700/60'
                  )}
                />
              )
            )}
          </div>
        </div>

        {/* 图例 */}
        <div className="flex items-center gap-1.5 mt-3 text-[10px] text-gray-400">
          <span>少</span>
          <div className="w-3 h-3 rounded bg-gray-100 dark:bg-slate-700/60" />
          <div className="w-3 h-3 rounded bg-emerald-200" />
          <div className="w-3 h-3 rounded bg-emerald-300" />
          <div className="w-3 h-3 rounded bg-emerald-400" />
          <div className="w-3 h-3 rounded bg-gradient-to-br from-emerald-400 to-green-500" />
          <span>多</span>
        </div>
      </div>

      {/* 词汇掌握分布 */}
      {totalVocab > 0 && (
        <div className="card p-5 sm:p-6 rounded-2xl mb-6">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-sm font-semibold text-gray-700 dark:text-gray-200 flex items-center gap-1.5">
              <Sparkles className="w-3.5 h-3.5 text-primary-500" />
              词汇掌握分布
            </h2>
            <span className="text-[11px] text-gray-400">共 {totalVocab}</span>
          </div>
          <div className="h-3 rounded-full overflow-hidden flex bg-gray-100 dark:bg-slate-700">
            <div
              className="bg-gradient-to-r from-gray-300 to-gray-400 dark:from-slate-500 dark:to-slate-400"
              style={{ width: `${stagePct(stats.vocab.byStage.new)}%` }}
              title={`新词 ${stats.vocab.byStage.new}`}
            />
            <div
              className="bg-gradient-to-r from-yellow-300 to-amber-400"
              style={{ width: `${stagePct(stats.vocab.byStage.learning)}%` }}
              title={`学习中 ${stats.vocab.byStage.learning}`}
            />
            <div
              className="bg-gradient-to-r from-primary-300 to-accent-400"
              style={{ width: `${stagePct(stats.vocab.byStage.reviewing)}%` }}
              title={`复习中 ${stats.vocab.byStage.reviewing}`}
            />
            <div
              className="bg-gradient-to-r from-green-400 to-emerald-500"
              style={{ width: `${stagePct(stats.vocab.byStage.mastered)}%` }}
              title={`已掌握 ${stats.vocab.byStage.mastered}`}
            />
          </div>
          <div className="grid grid-cols-4 gap-2 mt-3 text-center">
            <StageCell color="bg-gray-300 dark:bg-slate-500" label="新词" count={stats.vocab.byStage.new} total={totalVocab} />
            <StageCell color="bg-gradient-to-r from-yellow-300 to-amber-400" label="学习中" count={stats.vocab.byStage.learning} total={totalVocab} />
            <StageCell color="bg-gradient-to-r from-primary-300 to-accent-400" label="复习中" count={stats.vocab.byStage.reviewing} total={totalVocab} />
            <StageCell color="bg-gradient-to-r from-green-400 to-emerald-500" label="已掌握" count={stats.vocab.byStage.mastered} total={totalVocab} />
          </div>
        </div>
      )}

      {/* 语种分布 */}
      {(Object.keys(stats.article.byLanguage).length > 0 ||
        Object.keys(stats.vocab.byLanguage).length > 0) && (
        <div className="card p-5 sm:p-6 rounded-2xl mb-6">
          <div className="grid sm:grid-cols-2 gap-5">
            {Object.keys(stats.article.byLanguage).length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-gray-600 dark:text-gray-300 mb-2 flex items-center gap-1.5">
                  <BookOpen className="w-3.5 h-3.5 text-primary-500" />
                  文章语种分布
                </h3>
                <div className="space-y-1.5">
                  {Object.entries(stats.article.byLanguage)
                    .sort(([, a], [, b]) => b - a)
                    .map(([lang, count]) => {
                      const pct = stats.article.total > 0 ? (count / stats.article.total) * 100 : 0;
                      return (
                        <div key={lang}>
                          <div className="flex justify-between text-[11px] mb-0.5">
                            <span className="text-gray-600 dark:text-gray-400">
                              {LANGUAGE_NAMES[lang as Language] || lang}
                            </span>
                            <span className="text-gray-400 tabular-nums">
                              {count} 篇 · {Math.round(pct)}%
                            </span>
                          </div>
                          <div className="h-1.5 rounded-full bg-gray-100 dark:bg-slate-700 overflow-hidden">
                            <div
                              className="h-full bg-gradient-to-r from-primary-400 to-accent-400 rounded-full"
                              style={{ width: `${pct}%` }}
                            />
                          </div>
                        </div>
                      );
                    })}
                </div>
              </div>
            )}

            {Object.keys(stats.vocab.byLanguage).length > 0 && (
              <div>
                <h3 className="text-xs font-semibold text-gray-600 dark:text-gray-300 mb-2 flex items-center gap-1.5">
                  <BookMarked className="w-3.5 h-3.5 text-accent-500" />
                  生词语种分布
                </h3>
                <div className="space-y-1.5">
                  {Object.entries(stats.vocab.byLanguage)
                    .sort(([, a], [, b]) => b - a)
                    .map(([lang, count]) => {
                      const pct = stats.vocab.total > 0 ? (count / stats.vocab.total) * 100 : 0;
                      return (
                        <div key={lang}>
                          <div className="flex justify-between text-[11px] mb-0.5">
                            <span className="text-gray-600 dark:text-gray-400">
                              {LANGUAGE_NAMES[lang as Language] || lang}
                            </span>
                            <span className="text-gray-400 tabular-nums">
                              {count} 词 · {Math.round(pct)}%
                            </span>
                          </div>
                          <div className="h-1.5 rounded-full bg-gray-100 dark:bg-slate-700 overflow-hidden">
                            <div
                              className="h-full bg-gradient-to-r from-accent-400 to-pink-400 rounded-full"
                              style={{ width: `${pct}%` }}
                            />
                          </div>
                        </div>
                      );
                    })}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* 鼓励文案 */}
      {stats.article.total + stats.vocab.total + stats.checkIn.totalDays === 0 ? (
        <div className="card p-5 rounded-2xl text-center bg-gradient-to-br from-primary-50 to-accent-50 dark:from-primary-950/30 dark:to-accent-950/30">
          <Trophy className="w-10 h-10 mx-auto mb-2 text-gray-300" />
          <p className="text-sm text-gray-500">开始学习后，这里会显示你的学习数据</p>
        </div>
      ) : (
        <div className="card p-4 rounded-2xl text-center bg-gradient-to-r from-primary-50 via-accent-50 to-orange-50 dark:from-primary-950/30 dark:via-accent-950/30 dark:to-orange-950/30">
          <p className="text-sm text-gray-700 dark:text-gray-200">{getEncouragement(stats)}</p>
        </div>
      )}
    </div>
  );
}

/* ===== 子组件 ===== */

function OverviewItem({
  icon: Icon,
  label,
  value,
  color,
}: {
  icon: typeof BookOpen;
  label: string;
  value: number;
  color: string;
}) {
  return (
    <div className="card p-3 rounded-xl text-center">
      <Icon className={cn('w-4 h-4 mx-auto mb-1', color)} />
      <div className="text-xl font-bold tabular-nums text-gray-800 dark:text-gray-100">
        {value}
      </div>
      <div className="text-[10px] text-gray-500 mt-0.5">{label}</div>
    </div>
  );
}

function ProgressRow({
  icon,
  label,
  value,
  suffix,
  subtext,
  color,
}: {
  icon: React.ReactNode;
  label: string;
  value: number;
  suffix: string;
  subtext: string;
  color: string;
}) {
  return (
    <div className="flex items-center gap-3 p-2.5 rounded-xl hover:bg-gray-50 dark:hover:bg-slate-800/40 transition-colors">
      <div className="shrink-0 w-7 h-7 rounded-lg bg-gray-100 dark:bg-slate-700 flex items-center justify-center text-gray-500">
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-baseline gap-1.5">
          <span className="text-xs text-gray-600 dark:text-gray-300">{label}</span>
          <span className="text-sm font-bold tabular-nums text-gray-800 dark:text-gray-100">
            {value}
          </span>
          <span className="text-[10px] text-gray-400">{suffix}</span>
        </div>
        <div className="text-[10px] text-gray-400 mt-0.5">{subtext}</div>
      </div>
      <div className={cn('w-14 h-1 rounded-full', color)} />
    </div>
  );
}

function StageCell({
  color,
  label,
  count,
  total,
}: {
  color: string;
  label: string;
  count: number;
  total: number;
}) {
  const pct = total > 0 ? Math.round((count / total) * 100) : 0;
  return (
    <div className="flex flex-col items-center">
      <div className="text-base font-bold tabular-nums text-gray-800 dark:text-gray-100">
        {count}
      </div>
      <div className="text-[10px] text-gray-500 mt-0.5">{label}</div>
      <div className="text-[9px] text-gray-400 mt-0.5">{pct}%</div>
      <div className={cn('w-full h-0.5 rounded-full mt-1', color)} />
    </div>
  );
}

function RotateIcon() {
  return (
    <svg
      className="w-3.5 h-3.5"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8" />
      <path d="M21 3v5h-5" />
      <path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16" />
      <path d="M3 21v-5h5" />
    </svg>
  );
}

function getEncouragement(stats: ReturnType<typeof calcAllStats>): string {
  const { vocab, checkIn, article } = stats;
  if (checkIn.currentStreak >= 30) return '🏆 30 天+ 连续打卡！你是真正的学习达人！';
  if (checkIn.currentStreak >= 7) return `🔥 已连续打卡 ${checkIn.currentStreak} 天，坚持就是胜利！`;
  if (checkIn.currentStreak >= 3) return `✨ ${checkIn.currentStreak} 天连续打卡，太棒了！`;
  if (vocab.dueCount > 10) return `📚 有 ${vocab.dueCount} 个单词待复习，去生词本看看吧`;
  if (vocab.byStage.mastered >= 10) return `🎓 已掌握 ${vocab.byStage.mastered} 个单词，厉害！`;
  if (article.total === 0) return '📖 导入第一篇文章，开始你的学习之旅';
  if (vocab.total === 0) return '💡 在阅读时点击单词即可加入生词本';
  return '🌟 每天进步一点点，贵在坚持';
}
