import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { toDateKey } from '@/lib/checkIn';
import { getCheckinStatus, checkIn as apiCheckIn, type CheckinStatus, type CheckinResponse } from '@/api/learner';

interface WalletInfo {
  balance: number;
  conversions: number;
}

interface CheckInState {
  /** 打卡记录：YYYY-MM-DD -> true（本地缓存，真实数据以后端为准） */
  checkInDays: Record<string, boolean>;
  /** 最后一次打卡时间戳 */
  lastCheckInAt: number | null;
  /** 当前连续天数（来自后端） */
  streak: number;
  /** 总打卡天数（来自后端） */
  totalDays: number;
  /** 今日是否已打卡 */
  checkedToday: boolean;
  /** 封顶天数 */
  maxStreak: number;
  /** 是否已达封顶（true 时卡片应隐藏） */
  maxStreakReached: boolean;
  /** 今日打卡可获得的币数（未打卡时） */
  nextRewardCoins: number;
  /** 钱包余额（打卡成功后更新） */
  wallet: WalletInfo | null;
  /** 是否正在同步 */
  syncing: boolean;
  /** 是否正在打卡 */
  checking: boolean;
  /** 从后端同步打卡状态 */
  syncFromServer: () => Promise<void>;
  /** 触发一次打卡（今日已打卡则跳过） */
  checkIn: () => Promise<CheckinResponse | null>;
  /** 今日是否已打卡 */
  isCheckedInToday: () => boolean;
  /** 计算当前连胜天数（实时从本地缓存推导，用于快速渲染） */
  getStreak: () => number;
  /** 总打卡天数 */
  getTotalDays: () => number;
  /** 重置（数据管理中可调用） */
  reset: () => void;
}

export const useCheckInStore = create<CheckInState>()(
  persist(
    (set, get) => ({
      checkInDays: {},
      lastCheckInAt: null,
      streak: 0,
      totalDays: 0,
      checkedToday: false,
      maxStreak: 30,
      maxStreakReached: false,
      nextRewardCoins: 0,
      wallet: null,
      syncing: false,
      checking: false,

      syncFromServer: async () => {
        set({ syncing: true });
        try {
          const status: CheckinStatus = await getCheckinStatus();
          // 重建本地 checkInDays 缓存（用于快速渲染）
          const daysMap: Record<string, boolean> = {};
          for (const h of status.history) {
            daysMap[h.dateKey] = true;
          }
          set({
            checkInDays: daysMap,
            streak: status.streak,
            totalDays: status.totalDays,
            checkedToday: status.checkedToday,
            maxStreak: status.maxStreak,
            maxStreakReached: status.maxStreakReached,
            nextRewardCoins: status.nextRewardCoins,
          });
        } catch (e) {
          console.error('同步打卡状态失败:', e);
        } finally {
          set({ syncing: false });
        }
      },

      checkIn: async () => {
        if (get().checking) return null;
        set({ checking: true });
        try {
          const res: CheckinResponse = await apiCheckIn();
          const today = toDateKey();
          set((state) => ({
            checkInDays: { ...state.checkInDays, [today]: true },
            lastCheckInAt: Date.now(),
            streak: res.streak,
            checkedToday: true,
            maxStreakReached: res.maxStreakReached,
            wallet: res.wallet,
            nextRewardCoins: 0,
          }));
          return res;
        } catch (e) {
          console.error('打卡失败:', e);
          throw e;
        } finally {
          set({ checking: false });
        }
      },

      isCheckedInToday: () => get().checkedToday,
      getStreak: () => get().streak,
      getTotalDays: () => get().totalDays,
      reset: () =>
        set({
          checkInDays: {},
          lastCheckInAt: null,
          streak: 0,
          totalDays: 0,
          checkedToday: false,
          maxStreakReached: false,
          nextRewardCoins: 0,
          wallet: null,
        }),
    }),
    {
      name: 'bilingual-reader-checkin',
      // 只持久化本地缓存字段，运行时状态不持久化
      partialize: (state) => ({
        checkInDays: state.checkInDays,
        lastCheckInAt: state.lastCheckInAt,
        streak: state.streak,
        totalDays: state.totalDays,
        checkedToday: state.checkedToday,
        maxStreak: state.maxStreak,
        maxStreakReached: state.maxStreakReached,
        wallet: state.wallet,
      }),
    }
  )
);
