import { useState, useMemo, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { BookOpen } from 'lucide-react';
import BackButton from '@/components/BackButton';
import EmptyState from '@/components/EmptyState';
import AlphabetGrid from '@/components/basics/AlphabetGrid';
import PhoneticTable from '@/components/basics/PhoneticTable';
import KanaGrid from '@/components/basics/KanaGrid';
import KanaTable from '@/components/basics/KanaTable';
import BasicQuiz, { type QuizQuestion } from '@/components/basics/BasicQuiz';
import BasicQuizResult from '@/components/basics/BasicQuizResult';
import { EN_ALPHABET } from '@/data/enAlphabet';
import { EN_PHONETICS } from '@/data/enPhonetics';
import { GOJUON_DATA } from '@/data/jaKana';
import { useBasicsStore } from '@/stores/basicsStore';
import { cn } from '@/lib/utils';

interface LessonMeta {
  id: string;
  name: string;
}

const LESSONS: Record<string, { name: string; lessons: LessonMeta[] }> = {
  en: {
    name: '英语',
    lessons: [
      { id: 'alphabet', name: '字母表' },
      { id: 'phonetics', name: '音标' },
      { id: 'quiz', name: '练习' },
    ],
  },
  ja: {
    name: '日语',
    lessons: [
      { id: 'seion', name: '清音' },
      { id: 'dakuon', name: '浊音' },
      { id: 'youon', name: '拗音' },
      { id: 'quiz', name: '练习' },
    ],
  },
};

/** 从数组中随机取 n 个不重复元素 */
function sample<T>(arr: T[], n: number): T[] {
  const pool = [...arr];
  const result: T[] = [];
  while (result.length < n && pool.length > 0) {
    const idx = Math.floor(Math.random() * pool.length);
    result.push(pool.splice(idx, 1)[0]);
  }
  return result;
}

/** 生成英语字母→音标题目 */
function genEnLetterQuiz(): QuizQuestion[] {
  const pool = sample(EN_ALPHABET, 10);
  return pool.map((letter) => {
    // 干扰项：从其他字母的 soundPron 中取 3 个
    const distractors = sample(
      EN_ALPHABET.filter((l) => l.upper !== letter.upper).map((l) => l.soundPron),
      3
    );
    const options = sample([letter.soundPron, ...distractors], 4);
    return {
      prompt: letter.upper,
      promptRomaji: letter.namePron,
      playText: letter.upper,
      lang: 'en',
      options,
      answer: letter.soundPron,
    };
  });
}

/** 生成日语假名→罗马音题目 */
function genJaKanaQuiz(): QuizQuestion[] {
  // 从清音 + 浊音 + 半浊音中抽样（拗音较难，可选）
  const pool = sample(GOJUON_DATA.filter((k) => k.type !== 'youon' && k.type !== 'special'), 10);
  const allRomaji = GOJUON_DATA.map((k) => k.romaji);
  return pool.map((kana) => {
    const distractors = sample(
      allRomaji.filter((r) => r !== kana.romaji),
      3
    );
    const options = sample([kana.romaji, ...distractors], 4);
    return {
      prompt: kana.hiragana,
      promptRomaji: kana.katakana,
      playText: kana.hiragana,
      lang: 'ja',
      options,
      answer: kana.romaji,
    };
  });
}

export default function BasicsLessonPage() {
  const { language, lessonId } = useParams<{ language: string; lessonId: string }>();
  const navigate = useNavigate();
  const recordQuiz = useBasicsStore((s) => s.recordQuiz);

  // quiz 状态
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [quizCompleted, setQuizCompleted] = useState(false);
  const [quizResult, setQuizResult] = useState<{ correct: number; total: number }>({ correct: 0, total: 0 });

  const langConfig = language ? LESSONS[language] : undefined;
  const currentLesson = langConfig?.lessons.find((l) => l.id === lessonId);
  const isValid = !!langConfig && !!currentLesson;

  // 生成 quiz 题目
  const startQuiz = useCallback(() => {
    const questions = language === 'en' ? genEnLetterQuiz() : genJaKanaQuiz();
    setQuizQuestions(questions);
    setQuizCompleted(false);
  }, [language]);

  const handleQuizComplete = useCallback(
    (correct: number, total: number) => {
      setQuizResult({ correct, total });
      setQuizCompleted(true);
      if (language && lessonId) {
        recordQuiz(`${language}:${lessonId}`, correct, total);
      }
    },
    [language, lessonId, recordQuiz]
  );

  // 渲染课程内容
  const renderContent = useMemo(() => {
    if (!isValid) return null;

    // quiz 课程
    if (lessonId === 'quiz') {
      // 已完成 → 显示结果
      if (quizCompleted) {
        return (
          <BasicQuizResult
            correct={quizResult.correct}
            total={quizResult.total}
            onRetry={startQuiz}
            onBack={() => navigate('/basics')}
          />
        );
      }
      // 题目已生成 → 答题中
      if (quizQuestions.length > 0) {
        return <BasicQuiz questions={quizQuestions} onComplete={handleQuizComplete} />;
      }
      // 未开始 → 显示开始按钮
      return (
        <div className="text-center py-12">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-primary-100 to-accent-100 dark:from-primary-900 dark:to-accent-900 flex items-center justify-center mx-auto mb-4">
            <BookOpen className="w-7 h-7 text-primary-500" />
          </div>
          <h3 className="text-lg font-semibold text-gray-800 dark:text-gray-100 mb-2">
            {langConfig.name}基础练习
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-6 max-w-sm mx-auto">
            共 10 题，4 选 1。完成后会显示正确率并记入学习统计。
          </p>
          <button onClick={startQuiz} className="btn-primary">
            开始练习
          </button>
        </div>
      );
    }

    // 非quiz课程：渲染对应展示组件
    if (language === 'en') {
      if (lessonId === 'alphabet') return <AlphabetGrid letters={EN_ALPHABET} />;
      if (lessonId === 'phonetics') return <PhoneticTable phonetics={EN_PHONETICS} />;
    }
    if (language === 'ja') {
      if (lessonId === 'seion') {
        return <KanaGrid kana={GOJUON_DATA.filter((k) => k.type === 'clear' || k.type === 'special')} />;
      }
      if (lessonId === 'dakuon') {
        return <KanaTable kana={GOJUON_DATA.filter((k) => k.type === 'voiced' || k.type === 'semi-voiced')} />;
      }
      if (lessonId === 'youon') {
        return <KanaTable kana={GOJUON_DATA.filter((k) => k.type === 'youon')} />;
      }
    }
    return null;
  }, [isValid, lessonId, language, langConfig, quizCompleted, quizQuestions, quizResult, startQuiz, handleQuizComplete, navigate]);

  if (!isValid) {
    return (
      <div className="flex items-center justify-center h-full">
        <EmptyState
          icon={<BookOpen className="w-12 h-12" />}
          title="课程不存在"
          description="该语种或课程暂未开放，请返回选择其他课程"
          action={
            <button onClick={() => navigate('/basics')} className="btn-primary">
              返回基础学习
            </button>
          }
        />
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
      {/* 顶部工具栏 */}
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center gap-2">
          <BackButton variant="icon" fallback="/basics" />
          <div>
            <h1 className="text-lg font-semibold text-gray-800 dark:text-gray-100">
              {langConfig.name} · {currentLesson.name}
            </h1>
            <span className="text-[11px] text-gray-400">{langConfig.name}基础学习</span>
          </div>
        </div>
      </div>

      {/* 同语种课程切换 Tab */}
      <div className="flex items-center gap-1.5 mb-6 overflow-x-auto pb-1 scrollbar-thin">
        {langConfig.lessons.map((lesson) => {
          const active = lesson.id === lessonId;
          return (
            <button
              key={lesson.id}
              onClick={() => navigate(`/basics/${language}/${lesson.id}`)}
              className={cn(
                'px-3 py-1.5 rounded-xl text-xs font-medium whitespace-nowrap transition-all',
                active
                  ? 'bg-primary-500 text-white shadow-sm'
                  : 'bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
              )}
            >
              {lesson.name}
            </button>
          );
        })}
      </div>

      {/* 课程内容 */}
      <div className="min-h-[300px]">{renderContent}</div>
    </div>
  );
}
