/**
 * 本地账户管理工具（仿登录，不接入后端 API）
 * 用户数据存储在 localStorage，仅用于测试/演示
 */

const ACCOUNTS_KEY = 'bilingual-reader-accounts';
const CURRENT_USER_KEY = 'bilingual-reader-current-user';

export interface LocalAccount {
  username: string;
  password: string;
  createdAt: number;
}

export interface CurrentUser {
  username: string;
}

/** 获取所有注册账户 */
export function getAccounts(): LocalAccount[] {
  try {
    const raw = localStorage.getItem(ACCOUNTS_KEY);
    return raw ? (JSON.parse(raw) as LocalAccount[]) : [];
  } catch {
    return [];
  }
}

/** 保存账户列表 */
function saveAccounts(accounts: LocalAccount[]): void {
  localStorage.setItem(ACCOUNTS_KEY, JSON.stringify(accounts));
}

/** 注册新账户（用户名唯一校验） */
export function addAccount(username: string, password: string): { ok: boolean; error?: string } {
  const accounts = getAccounts();
  if (accounts.some((a) => a.username === username)) {
    return { ok: false, error: '用户名已被注册' };
  }
  accounts.push({ username, password, createdAt: Date.now() });
  saveAccounts(accounts);
  return { ok: true };
}

/** 验证登录 */
export function verifyAccount(username: string, password: string): { ok: boolean; error?: string } {
  const accounts = getAccounts();
  const found = accounts.find((a) => a.username === username);
  if (!found) {
    return { ok: false, error: '用户名不存在' };
  }
  if (found.password !== password) {
    return { ok: false, error: '密码错误' };
  }
  return { ok: true };
}

/** 获取当前登录用户 */
export function getCurrentUser(): CurrentUser | null {
  try {
    const raw = localStorage.getItem(CURRENT_USER_KEY);
    return raw ? (JSON.parse(raw) as CurrentUser) : null;
  } catch {
    return null;
  }
}

/** 设置当前登录用户 */
export function setCurrentUser(username: string): void {
  localStorage.setItem(CURRENT_USER_KEY, JSON.stringify({ username }));
}

/** 清除当前登录用户 */
export function clearCurrentUser(): void {
  localStorage.removeItem(CURRENT_USER_KEY);
}
