import type { ViewMode } from '@/types';
import type { TranslationPair } from '@/services/translationService';
import type { HighlightWord } from '@/hooks/useTextSelection';
import { cn } from '@/lib/utils';
import { useWalletStore } from '@/stores/walletStore';
import { Loader2, Languages, RefreshCw, AlertCircle, X, CheckCircle2, Info, Coins } from 'lucide-react';

// Re-export for parent use
export type { HighlightWord };

interface TranslationContentProps {
  viewMode: ViewMode;
  translationPairs: TranslationPair[];
  highlightWord: HighlightWord | null;
  isTranslating: boolean;
  translationError: string;
  /**
   * 源语种 = 目标语种，已跳过翻译。展示蓝色信息条而非绿色"翻译完成"。
   */
  noTranslationNeeded?: boolean;
  /** 翻译进度 0-100 */
  translationProgress?: number;
  /** 进度文字 */
  translationProgressText?: string;
  fontSize: number;
  fontFamily: string;
  lineHeight: number;
  parallelPosition: string;
  verticalPosition: string;
  splitRatio: number;
  verticalSplitRatio: number;
  highlightedParagraph: number | null;
  onTranslate: () => void;
  onRetry?: () => void;
  onCancel?: () => void;
  onOriginalMouseUp: () => void;
  onTranslatedMouseUp: () => void;
  onParagraphClick: (index: number) => void;
  onHorizontalDragStart?: (e: React.MouseEvent) => void;
  onVerticalDragStart?: (e: React.MouseEvent) => void;
  containerRef?: React.Ref<HTMLDivElement>;
}

const FONT_CLASS: Record<string, string> = {
  sans: 'font-sans',
  serif: 'font-serif',
  mono: 'font-mono',
};

/**
 * 在译文中高亮对应的单词（绿色背景，变形词上方标注原型）
 */
function renderHighlightedText(text: string, hl: HighlightWord | null): React.ReactNode {
  if (!hl) return <span>{text}</span>;

  const lowerText = text.toLowerCase();
  const lowerMatched = hl.matched.toLowerCase();
  const idx = lowerText.indexOf(lowerMatched);

  if (idx === -1) return <span>{text}</span>;

  const isMorphed = hl.matched.toLowerCase() !== hl.original.toLowerCase();

  return (
    <>
      {text.slice(0, idx)}
      <span className="relative inline-block">
        <span className="bg-macaron-green/40 dark:bg-macaron-green/30 rounded px-0.5 font-medium text-green-800 dark:text-green-200">
          {text.slice(idx, idx + hl.matched.length)}
        </span>
        {isMorphed && (
          <span className="absolute -top-[18px] left-1/2 -translate-x-1/2 whitespace-nowrap text-[10px] leading-none bg-primary-600 dark:bg-primary-500 text-white rounded px-1.5 py-0.5 shadow-sm pointer-events-none z-10">
            {hl.original}
          </span>
        )}
      </span>
      {text.slice(idx + hl.matched.length)}
    </>
  );
}

export default function TranslationContent({
  viewMode,
  translationPairs,
  highlightWord,
  isTranslating,
  translationError,
  noTranslationNeeded = false,
  translationProgress = 0,
  translationProgressText = '',
  fontSize,
  fontFamily,
  lineHeight,
  parallelPosition,
  verticalPosition,
  splitRatio,
  verticalSplitRatio,
  highlightedParagraph,
  onTranslate,
  onRetry,
  onCancel,
  onOriginalMouseUp,
  onTranslatedMouseUp,
  onParagraphClick,
  onHorizontalDragStart,
  onVerticalDragStart,
  containerRef,
}: TranslationContentProps) {
  const fontClass = FONT_CLASS[fontFamily] || 'font-sans';
  const translationFontSize = Math.max(fontSize - 1, 13);

  return (
    <div className="max-w-4xl mx-auto flex-1 min-h-0 overflow-hidden flex flex-col">
      {/* Translation error with retry */}
      {translationError && !isTranslating && (
        <div className="flex items-start gap-3 p-4 mb-4 rounded-xl bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-800">
          <AlertCircle className="w-5 h-5 text-red-500 shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-red-800 dark:text-red-300">翻译失败</p>
            <p className="text-xs text-red-600 dark:text-red-400 mt-1 break-words">{translationError}</p>
          </div>
          {onRetry && (
            <button
              onClick={onRetry}
              className="shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 text-xs font-medium hover:bg-red-200 dark:hover:bg-red-900/60 transition-colors"
            >
              <RefreshCw className="w-3.5 h-3.5" />
              重试
            </button>
          )}
        </div>
      )}

      {/* Translation progress bar */}
      {isTranslating && (
        <div className="mb-6 rounded-xl bg-gradient-to-br from-primary-50 to-accent-50 dark:from-primary-950/40 dark:to-accent-950/40 border border-primary-200/50 dark:border-primary-800/50 p-4">
          <div className="flex items-center justify-between mb-2.5">
            <div className="flex items-center gap-2.5 min-w-0 flex-1">
              <Loader2 className="w-4 h-4 text-primary-500 animate-spin shrink-0" />
              <span className="text-sm font-medium text-gray-700 dark:text-gray-200 truncate">
                {translationProgressText || '正在准备翻译...'}
              </span>
            </div>
            <div className="flex items-center gap-3 shrink-0 ml-3">
              <span className="text-sm font-semibold text-primary-600 dark:text-primary-400 tabular-nums">
                {translationProgress}%
              </span>
              {onCancel && (
                <button
                  onClick={onCancel}
                  className="flex items-center gap-1 px-2 py-1 rounded-md text-xs text-gray-500 hover:text-gray-700 dark:hover:text-gray-300 hover:bg-white/60 dark:hover:bg-slate-800/60 transition-colors"
                  title="取消翻译"
                >
                  <X className="w-3.5 h-3.5" />
                  取消
                </button>
              )}
            </div>
          </div>
          {/* Progress bar */}
          <div className="h-2 rounded-full bg-white/60 dark:bg-slate-800/60 overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-primary-400 to-accent-400 transition-all duration-300 ease-out rounded-full"
              style={{ width: `${translationProgress}%` }}
            />
          </div>
        </div>
      )}

      {/* Translation success notice */}
      {!isTranslating && !translationError && translationPairs.length > 0 && translationProgress === 100 && noTranslationNeeded && (
        <div className="mb-3 flex items-center gap-2 text-xs text-blue-600 dark:text-blue-400">
          <Info className="w-3.5 h-3.5" />
          源语种与目标语种相同，已直接展示原文
        </div>
      )}

      {!isTranslating && !translationError && translationPairs.length > 0 && translationProgress === 100 && !noTranslationNeeded && (
        <div className="mb-3 flex items-center gap-2 text-xs text-green-600 dark:text-green-400">
          <CheckCircle2 className="w-3.5 h-3.5" />
          翻译完成
        </div>
      )}

      {/* Translation action bar */}
      {!isTranslating && !translationError && translationPairs.length === 0 && (
        <div className="flex flex-col items-center gap-2 mb-6">
          <button onClick={onTranslate} className="btn-primary">
            <Languages className="w-4 h-4" />
            开始翻译（行对行对照）
          </button>
          <WalletBadge />
        </div>
      )}

      {!isTranslating && !translationError && translationPairs.length > 0 && (
        <div className="flex flex-col items-center gap-2 mb-6">
          <button onClick={onTranslate} className="btn-secondary">
            <RefreshCw className="w-4 h-4" />
            重新翻译
          </button>
          <WalletBadge />
        </div>
      )}

      {translationPairs.length > 0 && (
        <div className="relative" ref={containerRef}>
          {viewMode === 'single-original' && (
            <SingleOriginalView
              pairs={translationPairs}
              fontSize={fontSize}
              lineHeight={lineHeight}
              fontClass={fontClass}
              onMouseUp={onOriginalMouseUp}
            />
          )}

          {viewMode === 'single-translation' && (
            <SingleTranslationView
              pairs={translationPairs}
              fontSize={translationFontSize}
              lineHeight={lineHeight}
              highlightWord={highlightWord}
              onMouseUp={onTranslatedMouseUp}
            />
          )}

          {viewMode === 'line-by-line' && (
            <LineByLineView
              pairs={translationPairs}
              fontSize={fontSize}
              translationFontSize={translationFontSize}
              lineHeight={lineHeight}
              fontClass={fontClass}
              highlightWord={highlightWord}
              onOriginalMouseUp={onOriginalMouseUp}
              onTranslatedMouseUp={onTranslatedMouseUp}
            />
          )}

          {viewMode === 'side-by-side' && (
            <SideBySideView
              pairs={translationPairs}
              fontSize={fontSize}
              translationFontSize={translationFontSize}
              lineHeight={lineHeight}
              fontClass={fontClass}
              parallelPosition={parallelPosition}
              splitRatio={splitRatio}
              highlightedParagraph={highlightedParagraph}
              highlightWord={highlightWord}
              onParagraphClick={onParagraphClick}
              onOriginalMouseUp={onOriginalMouseUp}
              onTranslatedMouseUp={onTranslatedMouseUp}
              onHorizontalDragStart={onHorizontalDragStart}
            />
          )}

          {viewMode === 'top-bottom' && (
            <TopBottomView
              pairs={translationPairs}
              fontSize={fontSize}
              translationFontSize={translationFontSize}
              lineHeight={lineHeight}
              fontClass={fontClass}
              parallelPosition={verticalPosition}
              verticalSplitRatio={verticalSplitRatio}
              highlightWord={highlightWord}
              onOriginalMouseUp={onOriginalMouseUp}
              onTranslatedMouseUp={onTranslatedMouseUp}
              onVerticalDragStart={onVerticalDragStart}
            />
          )}
        </div>
      )}
    </div>
  );
}

// ─── Sub-views ───────────────────────────────────────

interface PairListProps {
  pairs: TranslationPair[];
  fontSize: number;
  lineHeight: number;
  fontClass: string;
  onMouseUp: () => void;
}

function SingleOriginalView({ pairs, fontSize, lineHeight, fontClass, onMouseUp }: PairListProps) {
  return (
    <div className="space-y-1">
      {pairs.map((pair, idx) => {
        if (!pair.original && !pair.translated) return <div key={idx} className="h-4" />;
        return (
          <div
            key={idx}
            className={`text-gray-800 dark:text-gray-100 px-4 py-2 rounded-lg hover:bg-primary-50/50 dark:hover:bg-primary-950/30 transition-colors select-text ${fontClass}`}
            style={{ fontSize: `${fontSize}px`, lineHeight }}
            onMouseUp={onMouseUp}
          >
            {pair.original}
          </div>
        );
      })}
    </div>
  );
}

function SingleTranslationView({ pairs, fontSize, lineHeight, highlightWord, onMouseUp }: {
  pairs: TranslationPair[];
  fontSize: number;
  lineHeight: number;
  highlightWord: HighlightWord | null;
  onMouseUp: () => void;
}) {
  return (
    <div className="space-y-1">
      {pairs.map((pair, idx) => {
        if (!pair.original && !pair.translated) return <div key={idx} className="h-4" />;
        return (
          <div
            key={idx}
            className="text-gray-600 dark:text-gray-300 bg-macaron-warm/50 dark:bg-slate-800/50 px-4 py-3 rounded-lg border-l-2 border-macaron-green/30 transition-colors select-text"
            style={{ fontSize: `${fontSize}px`, lineHeight }}
            onMouseUp={onMouseUp}
          >
            {renderHighlightedText(pair.translated, highlightWord)}
          </div>
        );
      })}
    </div>
  );
}

function LineByLineView({ pairs, fontSize, translationFontSize, lineHeight, fontClass, highlightWord, onOriginalMouseUp, onTranslatedMouseUp }: {
  pairs: TranslationPair[];
  fontSize: number;
  translationFontSize: number;
  lineHeight: number;
  fontClass: string;
  highlightWord: HighlightWord | null;
  onOriginalMouseUp: () => void;
  onTranslatedMouseUp: () => void;
}) {
  return (
    <div className="space-y-1">
      {pairs.map((pair, idx) => {
        if (!pair.original && !pair.translated) return <div key={idx} className="h-4" />;
        return (
          <div key={idx} className="group">
            <div
              className={`text-gray-800 dark:text-gray-100 px-4 py-2 rounded-lg hover:bg-primary-50/50 dark:hover:bg-primary-950/30 transition-colors select-text ${fontClass}`}
              style={{ fontSize: `${fontSize}px`, lineHeight }}
              onMouseUp={onOriginalMouseUp}
            >
              {pair.original}
            </div>
            <div
              className="text-gray-600 dark:text-gray-300 bg-macaron-warm/50 dark:bg-slate-800/50 px-4 py-3 rounded-lg ml-4 border-l-2 border-macaron-green/30 transition-colors select-text"
              style={{ fontSize: `${translationFontSize}px`, lineHeight }}
              onMouseUp={onTranslatedMouseUp}
            >
              {renderHighlightedText(pair.translated, highlightWord)}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function SideBySideView({ pairs, fontSize, translationFontSize, lineHeight, fontClass, parallelPosition, splitRatio, highlightedParagraph, highlightWord, onParagraphClick, onOriginalMouseUp, onTranslatedMouseUp, onHorizontalDragStart }: {
  pairs: TranslationPair[];
  fontSize: number;
  translationFontSize: number;
  lineHeight: number;
  fontClass: string;
  parallelPosition: string;
  splitRatio: number;
  highlightedParagraph: number | null;
  highlightWord: HighlightWord | null;
  onParagraphClick: (index: number) => void;
  onOriginalMouseUp: () => void;
  onTranslatedMouseUp: () => void;
  onHorizontalDragStart?: (e: React.MouseEvent) => void;
}) {
  const isLeftTranslated = parallelPosition === 'left-translated';

  return (
    <div className="flex flex-1 min-h-0">
      {/* 左栏 */}
      <div className="overflow-y-auto scrollbar-hide flex-shrink-0" style={{ width: `${splitRatio * 100}%` }}>
        <div className="sticky top-0 bg-[var(--color-bg)] z-10 py-2">
          <div className="text-xs text-gray-400 px-4">{isLeftTranslated ? '译文' : '原文'}</div>
        </div>
        <div className="space-y-1 px-4 pb-4">
          {pairs.map((pair, idx) => {
            if (!pair.original && !pair.translated) return <div key={idx} className="h-4" />;
            const text = isLeftTranslated ? pair.translated : pair.original;
            const isHighlighted = highlightedParagraph === idx;
            return (
              <div
                key={idx}
                className={cn(
                  'px-4 py-2 rounded-lg transition-colors select-text cursor-pointer',
                  isHighlighted && 'ring-2 ring-primary-400 bg-primary-50 dark:bg-primary-900/30',
                  isLeftTranslated
                    ? 'text-gray-600 dark:text-gray-300 bg-macaron-warm/50 dark:bg-slate-800/50 border-l-2 border-macaron-green/30'
                    : `text-gray-800 dark:text-gray-100 hover:bg-primary-50/50 dark:hover:bg-primary-950/30 ${fontClass}`
                )}
                style={{ fontSize: `${isLeftTranslated ? translationFontSize : fontSize}px`, lineHeight }}
                onClick={() => onParagraphClick(idx)}
                onMouseUp={isLeftTranslated ? onTranslatedMouseUp : onOriginalMouseUp}
              >
                {isLeftTranslated ? renderHighlightedText(text, null) : text}
              </div>
            );
          })}
        </div>
      </div>

      {/* 拖动分隔条 */}
      {onHorizontalDragStart && (
        <div
          className="w-1 bg-gray-200 dark:bg-slate-700 hover:bg-primary-400 cursor-col-resize flex-shrink-0 transition-colors"
          onMouseDown={onHorizontalDragStart}
        />
      )}

      {/* 右栏 */}
      <div className="overflow-y-auto scrollbar-hide flex-1">
        <div className="sticky top-0 bg-[var(--color-bg)] z-10 py-2">
          <div className="text-xs text-gray-400 px-4">{isLeftTranslated ? '原文' : '译文'}</div>
        </div>
        <div className="space-y-1 px-4 pb-4">
          {pairs.map((pair, idx) => {
            if (!pair.original && !pair.translated) return <div key={idx} className="h-4" />;
            const isRightTranslated = !isLeftTranslated;
            const text = isRightTranslated ? pair.translated : pair.original;
            const isHighlighted = highlightedParagraph === idx;
            return (
              <div
                key={idx}
                className={cn(
                  'px-4 py-2 rounded-lg transition-colors select-text cursor-pointer',
                  isHighlighted && 'ring-2 ring-primary-400 bg-primary-50 dark:bg-primary-900/30',
                  isRightTranslated
                    ? 'text-gray-600 dark:text-gray-300 bg-macaron-warm/50 dark:bg-slate-800/50 border-l-2 border-macaron-green/30'
                    : `text-gray-800 dark:text-gray-100 hover:bg-primary-50/50 dark:hover:bg-primary-950/30 ${fontClass}`
                )}
                style={{ fontSize: `${isRightTranslated ? translationFontSize : fontSize}px`, lineHeight }}
                onClick={() => onParagraphClick(idx)}
                onMouseUp={isRightTranslated ? onTranslatedMouseUp : onOriginalMouseUp}
              >
                {isRightTranslated ? renderHighlightedText(text, highlightWord) : text}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function TopBottomView({ pairs, fontSize, translationFontSize, lineHeight, fontClass, parallelPosition, verticalSplitRatio, highlightWord, onOriginalMouseUp, onTranslatedMouseUp, onVerticalDragStart }: {
  pairs: TranslationPair[];
  fontSize: number;
  translationFontSize: number;
  lineHeight: number;
  fontClass: string;
  parallelPosition: string;
  verticalSplitRatio: number;
  highlightWord: HighlightWord | null;
  onOriginalMouseUp: () => void;
  onTranslatedMouseUp: () => void;
  onVerticalDragStart?: (e: React.MouseEvent) => void;
}) {
  const isTopTranslated = parallelPosition === 'top-translated';

  return (
    <div className="flex flex-col flex-1 min-h-0">
      {/* 上栏 */}
      <div className="overflow-y-auto scrollbar-hide" style={{ height: `${verticalSplitRatio * 100}%` }}>
        <div className="sticky top-0 bg-[var(--color-bg)] z-10 py-2">
          <div className="text-xs text-gray-400 px-4">{isTopTranslated ? '译文' : '原文'}</div>
        </div>
        <div className="space-y-1 px-4 pb-4">
          {pairs.map((pair, idx) => {
            if (!pair.original && !pair.translated) return <div key={idx} className="h-4" />;
            const text = isTopTranslated ? pair.translated : pair.original;
            const fs = isTopTranslated ? translationFontSize : fontSize;
            return (
              <div
                key={idx}
                className={`px-4 py-2 rounded-lg transition-colors select-text ${isTopTranslated
                  ? 'text-gray-600 dark:text-gray-300 bg-macaron-warm/50 dark:bg-slate-800/50 border-l-2 border-macaron-green/30'
                  : `text-gray-800 dark:text-gray-100 hover:bg-primary-50/50 dark:hover:bg-primary-950/30 ${fontClass}`
                }`}
                style={{ fontSize: `${fs}px`, lineHeight }}
                onMouseUp={isTopTranslated ? onTranslatedMouseUp : onOriginalMouseUp}
              >
                {isTopTranslated ? renderHighlightedText(text, null) : text}
              </div>
            );
          })}
        </div>
      </div>

      {/* 拖动分隔条 */}
      {onVerticalDragStart && (
        <div
          className="h-1 bg-gray-200 dark:bg-slate-700 hover:bg-primary-400 cursor-row-resize flex-shrink-0 transition-colors"
          onMouseDown={onVerticalDragStart}
        />
      )}

      {/* 下栏 */}
      <div className="overflow-y-auto scrollbar-hide flex-1">
        <div className="sticky top-0 bg-[var(--color-bg)] z-10 py-2">
          <div className="text-xs text-gray-400 px-4">{isTopTranslated ? '原文' : '译文'}</div>
        </div>
        <div className="space-y-1 px-4 pb-4">
          {pairs.map((pair, idx) => {
            if (!pair.original && !pair.translated) return <div key={idx} className="h-4" />;
            const isBottomTranslated = !isTopTranslated;
            const text = isBottomTranslated ? pair.translated : pair.original;
            const fs = isBottomTranslated ? translationFontSize : fontSize;
            return (
              <div
                key={idx}
                className={`px-4 py-2 rounded-lg transition-colors select-text ${isBottomTranslated
                  ? 'text-gray-600 dark:text-gray-300 bg-macaron-warm/50 dark:bg-slate-800/50 border-l-2 border-macaron-green/30'
                  : `text-gray-800 dark:text-gray-100 hover:bg-primary-50/50 dark:hover:bg-primary-950/30 ${fontClass}`
                }`}
                style={{ fontSize: `${fs}px`, lineHeight }}
                onMouseUp={isBottomTranslated ? onTranslatedMouseUp : onOriginalMouseUp}
              >
                {isBottomTranslated ? renderHighlightedText(text, highlightWord) : text}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

/** 钱包余额徽章：显示在翻译按钮下方 */
function WalletBadge() {
  const balance = useWalletStore((s) => s.balance);
  const conversions = useWalletStore((s) => s.conversions);
  return (
    <div className="flex items-center gap-2 text-[11px] text-gray-400 dark:text-gray-500">
      <span className="flex items-center gap-1">
        <Coins className="w-3 h-3 text-amber-500" />
        <span className="text-amber-600 dark:text-amber-400 font-medium">{balance} 币</span>
      </span>
      <span className="text-gray-300 dark:text-gray-600">·</span>
      <span className="text-emerald-600 dark:text-emerald-400 font-medium">{conversions} 次翻译</span>
      <span className="text-gray-400 dark:text-gray-500">(长文本 &gt;2000 字扣次数)</span>
    </div>
  );
}
