import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface QuizStat {
  total: number;
  correct: number;
}

interface BasicsState {
  /** 已学假名（hiragana 字符串，如 'あ' 'きゃ'） */
  learnedKana: string[];
  /** 已学字母（upper 字符，如 'A'） */
  learnedLetters: string[];
  /** 测验统计：key 形如 `${language}:${lessonId}:${mode}` */
  quizStats: Record<string, QuizStat>;
  markKanaLearned: (hiragana: string) => void;
  unmarkKanaLearned: (hiragana: string) => void;
  markLetterLearned: (upper: string) => void;
  unmarkLetterLearned: (upper: string) => void;
  toggleKanaLearned: (hiragana: string) => void;
  toggleLetterLearned: (upper: string) => void;
  isKanaLearned: (hiragana: string) => boolean;
  isLetterLearned: (upper: string) => boolean;
  recordQuiz: (key: string, correct: number, total: number) => void;
  resetProgress: () => void;
}

export const useBasicsStore = create<BasicsState>()(
  persist(
    (set, get) => ({
      learnedKana: [],
      learnedLetters: [],
      quizStats: {},

      markKanaLearned: (hiragana) =>
        set((state) => ({
          learnedKana: state.learnedKana.includes(hiragana)
            ? state.learnedKana
            : [...state.learnedKana, hiragana],
        })),

      unmarkKanaLearned: (hiragana) =>
        set((state) => ({
          learnedKana: state.learnedKana.filter((k) => k !== hiragana),
        })),

      markLetterLearned: (upper) =>
        set((state) => ({
          learnedLetters: state.learnedLetters.includes(upper)
            ? state.learnedLetters
            : [...state.learnedLetters, upper],
        })),

      unmarkLetterLearned: (upper) =>
        set((state) => ({
          learnedLetters: state.learnedLetters.filter((l) => l !== upper),
        })),

      toggleKanaLearned: (hiragana) => {
        const learned = get().learnedKana.includes(hiragana);
        if (learned) get().unmarkKanaLearned(hiragana);
        else get().markKanaLearned(hiragana);
      },

      toggleLetterLearned: (upper) => {
        const learned = get().learnedLetters.includes(upper);
        if (learned) get().unmarkLetterLearned(upper);
        else get().markLetterLearned(upper);
      },

      isKanaLearned: (hiragana) => get().learnedKana.includes(hiragana),

      isLetterLearned: (upper) => get().learnedLetters.includes(upper),

      recordQuiz: (key, correct, total) =>
        set((state) => {
          const prev = state.quizStats[key];
          return {
            quizStats: {
              ...state.quizStats,
              [key]: prev
                ? { total: prev.total + total, correct: prev.correct + correct }
                : { total, correct },
            },
          };
        }),

      resetProgress: () =>
        set({ learnedKana: [], learnedLetters: [], quizStats: {} }),
    }),
    {
      name: 'bilingual-reader-basics',
    }
  )
);
