import { Check } from 'lucide-react';
import type { KanaEntry, KanaType } from '@/data/jaKana';
import { speak } from '@/lib/speech';
import { useBasicsStore } from '@/stores/basicsStore';
import { cn } from '@/lib/utils';

interface KanaTableProps {
  kana: KanaEntry[];
}

const SECTION_LABELS: Record<string, string> = {
  voiced: '浊音（が行・ざ行・だ行・ば行）',
  'semi-voiced': '半浊音（ぱ行）',
  youon: '拗音',
};

const SECTION_ORDER: KanaType[] = ['voiced', 'semi-voiced', 'youon'];

export default function KanaTable({ kana }: KanaTableProps) {
  const { isKanaLearned, toggleKanaLearned } = useBasicsStore();

  const handlePlay = (entry: KanaEntry) => {
    speak({ text: entry.hiragana, lang: 'ja' });
  };

  const sections = SECTION_ORDER.map((type) => ({
    type,
    label: SECTION_LABELS[type] || type,
    items: kana.filter((k) => k.type === type),
  })).filter((s) => s.items.length > 0);

  return (
    <div className="space-y-6">
      {sections.map((section) => (
        <div key={section.type}>
          <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2.5 flex items-center gap-2">
            <span className="inline-block w-1 h-4 rounded-full bg-pink-500" />
            {section.label}
            <span className="text-xs font-normal text-gray-400">({section.items.length})</span>
          </h3>
          {/* 浊音/半浊音用 5 列网格；拗音用 3 列紧凑网格 */}
          <div className={cn(
            'grid gap-2',
            section.type === 'youon' ? 'grid-cols-3 sm:grid-cols-6' : 'grid-cols-3 sm:grid-cols-5'
          )}>
            {section.items.map((entry) => {
              const learned = isKanaLearned(entry.hiragana);
              return (
                <button
                  key={`${entry.type}-${entry.hiragana}`}
                  onClick={() => handlePlay(entry)}
                  onContextMenu={(e) => {
                    e.preventDefault();
                    toggleKanaLearned(entry.hiragana);
                  }}
                  className={cn(
                    'relative aspect-square rounded-xl flex flex-col items-center justify-center transition-all duration-200 border',
                    learned
                      ? 'bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-950/40 dark:to-teal-950/40 border-emerald-300 dark:border-emerald-700'
                      : 'bg-white dark:bg-slate-800 border-gray-100 dark:border-slate-700 hover:border-pink-300 dark:hover:border-pink-600 hover:shadow-sm hover:-translate-y-0.5'
                  )}
                  title={`${entry.hiragana} / ${entry.katakana} (${entry.romaji}) · 右键标记已学`}
                >
                  {learned && (
                    <span className="absolute top-1 right-1 w-3.5 h-3.5 rounded-full bg-emerald-500 text-white flex items-center justify-center">
                      <Check className="w-2 h-2" />
                    </span>
                  )}
                  <span className="text-xl font-bold text-gray-800 dark:text-gray-100 leading-none">
                    {entry.hiragana}
                  </span>
                  <span className="absolute top-1 left-1 text-[10px] text-gray-400 dark:text-gray-500">
                    {entry.katakana}
                  </span>
                  <span className="text-[9px] text-gray-400 dark:text-gray-500 mt-0.5">
                    {entry.romaji}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}
