import { useState, useEffect, useRef, useMemo } from 'react';
import { useParams, useNavigate, Navigate, useLocation } from 'react-router-dom';
import {
  BookOpen,
  Volume2,
  Columns2,
  LayoutList,
  FileText,
  Languages,
  LayoutGrid,
  Eye,
} from 'lucide-react';
import { usePublicArticleStore } from '@/stores/publicArticleStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { useUIStore } from '@/stores/uiStore';
import { useAuthStore } from '@/stores/authStore';
import WordModal from '@/components/WordModal';
import WordPopup from '@/components/WordPopup';
import EmptyState from '@/components/EmptyState';
import BackButton from '@/components/BackButton';
import TranslationContent from '@/components/TranslationContent';
import type { Article, ViewMode } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import { cn } from '@/lib/utils';
import { speak } from '@/lib/speech';
import { useSplitPane } from '@/hooks/useSplitPane';
import { useTextSelection } from '@/hooks/useTextSelection';
import { buildTranslationPairs } from '@/lib/translationPairs';
import type { TranslationPair } from '@/services/translationService';

export default function PublicReadPage() {
  const { articleId } = useParams<{ articleId: string }>();
  const navigate = useNavigate();
  const location = useLocation();
  const { currentArticle, loading, fetchArticle } = usePublicArticleStore();
  const { viewMode, setViewMode } = useUIStore();
  const { settings } = useSettingsStore();
  const isGuest = useAuthStore((s) => s.isGuest);

  const { horizontalRatio, verticalRatio, containerRef: splitPaneRef, startHorizontalDrag, startVerticalDrag } = useSplitPane();

  // 将 PublicArticle 适配为 useTextSelection 需要的 Article 类型
  const article: Article | null = currentArticle
    ? {
        id: currentArticle.id,
        title: currentArticle.title,
        content: currentArticle.content,
        translation: currentArticle.translation,
        sourceLanguage: currentArticle.sourceLanguage,
        targetLanguage: currentArticle.targetLanguage,
        categoryId: currentArticle.categoryId || 'default',
        createdAt: new Date(currentArticle.createdAt).getTime(),
        updatedAt: new Date(currentArticle.updatedAt).getTime(),
        tags: currentArticle.tags,
      }
    : null;

  const {
    highlightWord,
    selectedWord,
    setSelectedWord,
    handleOriginalTextSelection,
    handleTranslatedTextSelection,
  } = useTextSelection(
    currentArticle
      ? buildTranslationPairs(currentArticle.content, currentArticle.translation)
      : [],
    article
  );

  const [highlightedParagraph, setHighlightedParagraph] = useState<number | null>(null);
  const highlightTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (articleId) {
      fetchArticle(articleId);
    }
  }, [articleId, fetchArticle]);

  // 清理高亮定时器
  useEffect(() => {
    return () => {
      if (highlightTimerRef.current) clearTimeout(highlightTimerRef.current);
    };
  }, []);

  const translationPairs: TranslationPair[] = useMemo(() => {
    if (!currentArticle) return [];
    return buildTranslationPairs(currentArticle.content, currentArticle.translation);
  }, [currentArticle]);

  const handleParagraphClick = (index: number) => {
    if (highlightTimerRef.current) clearTimeout(highlightTimerRef.current);
    if (highlightedParagraph === index) {
      setHighlightedParagraph(null);
      return;
    }
    setHighlightedParagraph(index);
    highlightTimerRef.current = setTimeout(() => setHighlightedParagraph(null), 5000);
  };

  const viewModeOptions: { value: ViewMode; icon: React.ReactNode; label: string }[] = [
    { value: 'line-by-line', icon: <Columns2 className="w-3.5 h-3.5" />, label: '行对行' },
    { value: 'side-by-side', icon: <LayoutGrid className="w-3.5 h-3.5" />, label: '并排' },
    { value: 'top-bottom', icon: <LayoutList className="w-3.5 h-3.5" />, label: '上下' },
    { value: 'single-original', icon: <FileText className="w-3.5 h-3.5" />, label: '原文' },
    { value: 'single-translation', icon: <Languages className="w-3.5 h-3.5" />, label: '译文' },
  ];

  // 游客无权查看公共文章详情，重定向到登录页（放在所有 hooks 之后）
  if (isGuest) {
    return <Navigate to="/auth" state={{ from: location.pathname }} replace />;
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-sm text-gray-400">加载中...</div>
      </div>
    );
  }

  if (!article || !currentArticle) {
    return (
      <div className="flex items-center justify-center h-full">
        <EmptyState
          icon={<BookOpen className="w-12 h-12" />}
          title="文章不存在"
          description="该文章可能已被下架或删除"
          action={
            <button onClick={() => navigate('/library')} className="btn-primary">
              <BackButton variant="icon" fallback="/library" /> 返回公共文章库
            </button>
          }
        />
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Top Toolbar */}
      <div className="sticky top-0 z-20 bg-[var(--color-bg)] border-b border-gray-200 dark:border-gray-700 px-4 sm:px-6">
        <div className="flex items-center justify-between h-14 max-w-6xl mx-auto">
          {/* Left */}
          <div className="flex items-center gap-3">
            <BackButton variant="icon" fallback="/library" />
            <div>
              <h1 className="text-sm font-semibold text-gray-800 dark:text-gray-100 truncate max-w-[200px] sm:max-w-[400px]">
                {article.title}
              </h1>
              <span className="text-[11px] text-gray-400 flex items-center gap-2">
                {LANGUAGE_NAMES[article.targetLanguage]} · {article.content.length} 字
                <span className="flex items-center gap-0.5">
                  <Eye className="w-3 h-3" />
                  {currentArticle.viewCount}
                </span>
              </span>
            </div>
          </div>

          {/* Right - View mode toggles + Speak */}
          <div className="flex items-center gap-1.5">
            <div className="hidden sm:flex bg-gray-100 dark:bg-slate-700 rounded-xl p-0.5">
              {viewModeOptions.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => setViewMode(opt.value)}
                  className={cn(
                    'flex items-center gap-1 px-2.5 py-1.5 rounded-[10px] text-xs font-medium transition-all',
                    viewMode === opt.value
                      ? 'bg-white dark:bg-slate-600 text-gray-700 dark:text-gray-200 shadow-sm'
                      : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                  )}
                >
                  {opt.icon}
                  <span>{opt.label}</span>
                </button>
              ))}
            </div>

            {/* Speak */}
            <button
              onClick={() => {
                speak({ text: article.content.slice(0, 200), lang: article.sourceLanguage === 'zh' ? 'zh' : 'en', rate: settings.speechRate });
              }}
              className="btn-ghost !p-2"
              title="朗读"
            >
              <Volume2 className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-auto">
        <div className="max-w-6xl mx-auto p-4 sm:p-6 lg:p-8">
          <TranslationContent
            viewMode={viewMode}
            translationPairs={translationPairs}
            highlightWord={highlightWord}
            isTranslating={false}
            translationError=""
            noTranslationNeeded={false}
            translationProgress={100}
            translationProgressText="已翻译完成"
            fontSize={settings.fontSize}
            fontFamily={settings.fontFamily}
            lineHeight={settings.lineHeight}
            parallelPosition={settings.parallelPosition}
            verticalPosition={settings.verticalPosition}
            splitRatio={horizontalRatio}
            verticalSplitRatio={verticalRatio}
            highlightedParagraph={highlightedParagraph}
            onTranslate={() => {}}
            onRetry={() => {}}
            onCancel={() => {}}
            onOriginalMouseUp={handleOriginalTextSelection}
            onTranslatedMouseUp={handleTranslatedTextSelection}
            onParagraphClick={handleParagraphClick}
            onHorizontalDragStart={startHorizontalDrag}
            onVerticalDragStart={startVerticalDrag}
            containerRef={splitPaneRef}
          />
        </div>
      </div>

      {/* Word Detail Modal */}
      <WordModal />

      {/* Word Popup */}
      {selectedWord && article && (
        <WordPopup
          word={selectedWord.word}
          position={selectedWord.position}
          onClose={() => setSelectedWord(null)}
          articleId={article.id}
          sourceSentence={selectedWord.sourceSentence}
          targetLanguage={article.targetLanguage}
        />
      )}
    </div>
  );
}
