import { useState, useEffect, useCallback } from 'react';
import { useNavigate, Navigate, useLocation } from 'react-router-dom';
import { Send, Clock, CheckCircle2, XCircle, Trash2, Eye } from 'lucide-react';
import { getMySubmissions, cancelSubmission } from '@/api/publicArticle';
import type { SubmissionItem, SubmissionStatus } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import BackButton from '@/components/BackButton';
import EmptyState from '@/components/EmptyState';
import { ConfirmDialog, useConfirm } from '@/components/ConfirmDialog';
import { cn } from '@/lib/utils';
import { useAuthStore } from '@/stores/authStore';

const STATUS_CONFIG: Record<SubmissionStatus, { label: string; color: string; icon: React.ReactNode }> = {
  PENDING_REVIEW: {
    label: '待审核',
    color: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/40 dark:text-yellow-300',
    icon: <Clock className="w-3 h-3" />,
  },
  PUBLISHED: {
    label: '已通过',
    color: 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300',
    icon: <CheckCircle2 className="w-3 h-3" />,
  },
  REJECTED: {
    label: '已拒绝',
    color: 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300',
    icon: <XCircle className="w-3 h-3" />,
  },
  ARCHIVED: {
    label: '已归档',
    color: 'bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400',
    icon: <Clock className="w-3 h-3" />,
  },
};

export default function MySubmissionsPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const isGuest = useAuthStore((s) => s.isGuest);
  const [submissions, setSubmissions] = useState<SubmissionItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeStatus, setActiveStatus] = useState<SubmissionStatus | 'all'>('all');
  const { state: confirmState, confirm, handleConfirm, handleCancel } = useConfirm();

  const loadSubmissions = useCallback(async () => {
    if (isGuest) return;
    setLoading(true);
    try {
      const data = await getMySubmissions({
        page: 1,
        pageSize: 50,
        status: activeStatus !== 'all' ? activeStatus : undefined,
      });
      setSubmissions(data.list);
    } catch (e) {
      console.error('[我的投稿] 加载失败:', e);
    } finally {
      setLoading(false);
    }
  }, [activeStatus, isGuest]);

  useEffect(() => {
    loadSubmissions();
  }, [loadSubmissions]);

  // 游客无权查看投稿列表，重定向到登录页（放在所有 hooks 之后）
  if (isGuest) {
    return <Navigate to="/auth" state={{ from: location.pathname }} replace />;
  }

  const handleCancelSubmission = async (id: string) => {
    const ok = await confirm('撤回投稿', '确定撤回这篇投稿吗？撤回后文章将从公共库删除。');
    if (ok) {
      try {
        await cancelSubmission(id);
        setSubmissions(submissions.filter((s) => s.id !== id));
      } catch (e) {
        console.error('[我的投稿] 撤回失败:', e);
      }
    }
  };

  const statusTabs: { value: SubmissionStatus | 'all'; label: string }[] = [
    { value: 'all', label: '全部' },
    { value: 'PENDING_REVIEW', label: '待审核' },
    { value: 'PUBLISHED', label: '已通过' },
    { value: 'REJECTED', label: '已拒绝' },
  ];

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
      <BackButton />

      {/* Header */}
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800 dark:text-gray-100 flex items-center gap-2">
          <Send className="w-5 h-5 text-primary-500" />
          我的投稿
        </h1>
        <p className="text-sm text-gray-500 mt-0.5">
          查看你分享到公共文章库的文章及其审核状态
        </p>
      </div>

      {/* Status Filter */}
      <div className="flex items-center gap-2 mb-6 overflow-x-auto pb-1 scrollbar-thin">
        {statusTabs.map((tab) => (
          <button
            key={tab.value}
            onClick={() => setActiveStatus(tab.value)}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all',
              activeStatus === tab.value
                ? 'bg-primary-100 text-primary-700 dark:bg-primary-900 dark:text-primary-300'
                : 'bg-gray-100 text-gray-600 dark:bg-slate-700 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
            )}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Content */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <div className="text-sm text-gray-400">加载中...</div>
        </div>
      ) : submissions.length > 0 ? (
        <div className="space-y-3">
          {submissions.map((sub) => {
            const config = STATUS_CONFIG[sub.status];
            return (
              <div
                key={sub.id}
                className="card p-4 group hover:shadow-md transition-shadow"
              >
                <div className="flex items-start justify-between gap-3 mb-2">
                  <div className="flex-1 min-w-0">
                    <h3 className="font-semibold text-gray-800 dark:text-gray-100 text-sm truncate">
                      {sub.title}
                    </h3>
                    <div className="flex items-center gap-2 mt-1.5 flex-wrap">
                      <span className="tag-language text-[10px] px-2 py-0.5">
                        {LANGUAGE_NAMES[sub.targetLanguage] || sub.targetLanguage}
                      </span>
                      <span
                        className={cn(
                          'inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[10px] font-medium',
                          config.color
                        )}
                      >
                        {config.icon}
                        {config.label}
                      </span>
                      <span className="text-[10px] text-gray-400">
                        {new Date(sub.createdAt).toLocaleDateString('zh-CN')}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-1.5 shrink-0">
                    {sub.status === 'PUBLISHED' && (
                      <button
                        onClick={() => navigate(`/library/${sub.id}`)}
                        className="btn-ghost !p-1.5"
                        title="查看"
                      >
                        <Eye className="w-3.5 h-3.5" />
                      </button>
                    )}
                    {(sub.status === 'PENDING_REVIEW' || sub.status === 'REJECTED') && (
                      <button
                        onClick={() => handleCancelSubmission(sub.id)}
                        className="btn-ghost !p-1.5 text-red-400 hover:text-red-600"
                        title="撤回"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                </div>

                {/* Rejected reason */}
                {sub.status === 'REJECTED' && sub.reviewNote && (
                  <div className="mt-2 p-2.5 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800">
                    <p className="text-xs text-red-600 dark:text-red-400">
                      <span className="font-medium">拒绝原因：</span>
                      {sub.reviewNote}
                    </p>
                  </div>
                )}

                {/* Tags */}
                {sub.tags.length > 0 && (
                  <div className="flex items-center gap-1.5 mt-2 flex-wrap">
                    {sub.tags.map((tag) => (
                      <span
                        key={tag}
                        className="tag bg-gray-100 dark:bg-slate-700 text-gray-500 dark:text-gray-400 text-[10px] px-2 py-0.5"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      ) : (
        <EmptyState
          icon={<Send className="w-12 h-12" />}
          title="还没有投稿"
          description="在阅读文章时，翻译完成后可以分享到公共文章库"
          action={
            <button onClick={() => navigate('/articles')} className="btn-primary">
              去导入文章
            </button>
          }
        />
      )}

      <ConfirmDialog
        open={confirmState.open}
        title={confirmState.title}
        message={confirmState.message}
        onConfirm={handleConfirm}
        onCancel={handleCancel}
      />
    </div>
  );
}
