/**
 * English syllable splitting for display
 * Splits English words into syllables with · separator (e.g., "dic·tion·ar·y")
 * Uses a rule-based algorithm covering common English patterns.
 */

const VOWELS = /[aeiouy]/i;

/**
 * Split an English word into syllable parts
 */
export function splitSyllables(word: string): string[] {
  const w = word.toLowerCase().replace(/[^a-z']/g, '');
  if (w.length <= 2) return [word];

  const vowelIndices: number[] = [];
  for (let i = 0; i < w.length; i++) {
    if (VOWELS.test(w[i])) vowelIndices.push(i);
  }

  // Single vowel → single syllable
  if (vowelIndices.length <= 1) return [word];

  // Find syllable boundaries between vowel pairs
  const boundaries: number[] = [];

  for (let i = 0; i < vowelIndices.length - 1; i++) {
    const v1 = vowelIndices[i];
    const v2 = vowelIndices[i + 1];
    const gap = v2 - v1 - 1; // consonants between vowels

    if (gap === 0) {
      // Adjacent vowels (e.g., "ae", "oe") → no split
      continue;
    } else if (gap === 1) {
      // VCV pattern: consonant goes with second vowel (e.g., "o·pen")
      // But not if the first vowel is short and stressed (e.g., "cab·in")
      // Simple heuristic: C goes with second vowel
      boundaries.push(v1 + 1);
    } else {
      // VCCV pattern: split after first consonant (e.g., "doc·tor")
      // Unless the consonant cluster can start a syllable (e.g., "con·grat·u·late")
      // Simple heuristic: split after first consonant
      boundaries.push(v1 + 2);
    }
  }

  if (boundaries.length === 0) return [word];

  // Build syllable segments
  const segments: string[] = [];
  let start = 0;
  for (const b of boundaries) {
    if (b > start) {
      segments.push(w.slice(start, b));
      start = b;
    }
  }
  if (start < w.length) {
    segments.push(w.slice(start));
  }

  // Post-processing: merge single-letter segments
  const merged: string[] = [];
  for (let i = 0; i < segments.length; i++) {
    if (segments[i].length === 1 && VOWELS.test(segments[i]) && merged.length > 0) {
      merged[merged.length - 1] += segments[i];
    } else {
      merged.push(segments[i]);
    }
  }

  // Apply common English syllable rules
  // "le" after consonant forms its own syllable (ta·ble, peo·ple)
  for (let i = 0; i < merged.length - 1; i++) {
    const seg = merged[i];
    const next = merged[i + 1];
    if (next === 'le' && seg.length > 0 && !VOWELS.test(seg[seg.length - 1])) {
      continue; // keep "le" as its own syllable
    }
  }

  // If "le" ending got merged incorrectly, fix it
  const result = merged.join('·');
  const fixed = result.replace(/·([bcdfghjklmnpqrstvwxyz]+)le$/i, '$1·le');

  return fixed.split('·');
}

/**
 * Return word with syllable dots: "dictionary" → "dic·tion·ar·y"
 * Falls back to original word if splitting fails.
 */
export function showSyllables(word: string): string {
  const parts = splitSyllables(word);
  if (parts.length <= 1) return word;
  const result = parts.join('·');
  // Avoid overly long syllable display
  if (result.length > word.length * 2) return word;
  return result;
}