import { useMemo, useState, useEffect } from 'react';
import { Flame, CheckCircle2, Sparkles, Coins } from 'lucide-react';
import { useCheckInStore } from '@/stores/checkInStore';
import { cn } from '@/lib/utils';

interface CheckInCardProps {
  onCheckIn?: () => void;
}

export default function CheckInCard({ onCheckIn }: CheckInCardProps) {
  const {
    streak,
    checkedToday,
    maxStreakReached,
    nextRewardCoins,
    wallet,
    checking,
    checkIn,
    syncFromServer,
  } = useCheckInStore();

  const [justChecked, setJustChecked] = useState(false);
  const [awardedCoins, setAwardedCoins] = useState(0);
  const [error, setError] = useState('');

  // 挂载时同步后端状态
  useEffect(() => {
    syncFromServer();
  }, [syncFromServer]);

  const recent7Days = useMemo(() => {
    const totalSlots = Math.max(7, streak + 2);
    const list: Array<{ day: number; status: 'done' | 'today' | 'upcoming' }> = [];
    for (let i = 1; i <= totalSlots; i++) {
      let status: 'done' | 'today' | 'upcoming';
      if (i <= streak) {
        status = 'done';
      } else if (i === streak + 1 && !checkedToday) {
        status = 'today';
      } else {
        status = 'upcoming';
      }
      list.push({ day: i, status });
    }
    return list;
  }, [streak, checkedToday]);

  const handleCheckIn = async () => {
    setError('');
    try {
      const res = await checkIn();
      if (res) {
        setJustChecked(true);
        setAwardedCoins(res.coinsAwarded);
        setTimeout(() => {
          setJustChecked(false);
          setAwardedCoins(0);
        }, 2500);
        onCheckIn?.();
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : '打卡失败';
      setError(msg);
      setTimeout(() => setError(''), 3000);
    }
  };

  // 30 天封顶：卡片自动消失
  if (maxStreakReached) {
    return null;
  }

  return (
    <div
      className={cn(
        'relative rounded-2xl p-4 transition-all duration-500 overflow-hidden',
        checkedToday
          ? 'bg-gradient-to-br from-emerald-50 via-teal-50 to-cyan-50 dark:from-emerald-950/30 dark:via-teal-950/20 dark:to-cyan-950/20 border border-emerald-100/60 dark:border-emerald-900/40'
          : 'bg-white dark:bg-slate-800 border border-gray-100 dark:border-gray-700/60 shadow-sm'
      )}
    >
      {/* 装饰光斑 */}
      <div className="pointer-events-none absolute -top-8 -right-8 w-32 h-32 rounded-full opacity-40 blur-2xl transition-colors duration-500"
        style={{
          background: checkedToday
            ? 'radial-gradient(circle, rgba(52, 211, 153, 0.3) 0%, transparent 70%)'
            : 'radial-gradient(circle, rgba(251, 146, 60, 0.15) 0%, transparent 70%)',
        }}
      />

      {/* 头部 */}
      <div className="relative flex items-center justify-between gap-3">
        <div className="flex items-center gap-3 min-w-0">
          <div
            className={cn(
              'w-11 h-11 rounded-xl flex items-center justify-center shrink-0 transition-all duration-500',
              checkedToday
                ? 'bg-gradient-to-br from-emerald-400 to-teal-500 text-white shadow-lg shadow-emerald-200/60 dark:shadow-emerald-900/40'
                : 'bg-gradient-to-br from-orange-400 to-amber-500 text-white shadow-lg shadow-orange-200/60 dark:shadow-orange-900/40'
            )}
          >
            <Flame className={cn('w-5 h-5 transition-transform', streak > 0 && 'fill-white', justChecked && 'animate-pulse')} />
          </div>
          <div className="min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <span className="text-sm font-bold text-gray-800 dark:text-gray-100">
                学习打卡
              </span>
              {streak > 0 && (
                <span className={cn(
                'text-xs font-bold px-1.5 py-0.5 rounded-md',
                checkedToday
                  ? 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/40 dark:text-emerald-400'
                  : 'bg-orange-100 text-orange-500 dark:bg-orange-900/40 dark:text-orange-400'
              )}>
                {streak} 天连胜
                </span>
              )}
              {justChecked && (
                <span className="flex items-center gap-1 text-xs font-medium text-emerald-500 animate-bounce">
                  <Sparkles className="w-3 h-3" />
                  太棒了
                  {awardedCoins > 0 && (
                    <span className="flex items-center gap-0.5 ml-1 text-amber-500 font-bold">
                      <Coins className="w-3 h-3" />
                      +{awardedCoins}
                    </span>
                  )}
                </span>
              )}
            </div>
            <p className="text-[11px] text-gray-400 dark:text-gray-500 mt-0.5">
              {checkedToday
                ? '今日已完成打卡，继续保持'
                : nextRewardCoins > 0
                ? `点击打卡，今日可得 ${nextRewardCoins} 币`
                : '点击打卡，开启今日学习'}
            </p>
          </div>
        </div>

        <button
          onClick={handleCheckIn}
          disabled={checkedToday || checking}
          className={cn(
            'relative flex items-center gap-1.5 px-4 py-2 rounded-xl font-semibold text-xs transition-all shrink-0',
            checkedToday
              ? 'bg-emerald-500 text-white shadow-md shadow-emerald-200/60 dark:shadow-emerald-900/40 cursor-default'
              : checking
              ? 'bg-gray-300 dark:bg-slate-600 text-gray-500 cursor-wait'
              : 'bg-gray-900 dark:bg-white text-white dark:text-gray-900 hover:opacity-90 active:scale-95 shadow-md'
          )}
        >
          {checkedToday ? (
            <>
              <CheckCircle2 className="w-4 h-4" />
              已打卡
            </>
          ) : checking ? (
            '打卡中...'
          ) : (
            <>
              <Flame className="w-4 h-4" />
              立即打卡
            </>
          )}
        </button>
      </div>

      {/* 错误提示 */}
      {error && (
        <div className="mt-2 text-[11px] text-red-500 bg-red-50 dark:bg-red-900/20 rounded-lg px-2 py-1">
          {error}
        </div>
      )}

      {/* 分隔线 */}
      <div className={cn(
        'my-3 h-px',
        checkedToday
          ? 'bg-gradient-to-r from-transparent via-emerald-200/50 to-transparent dark:via-emerald-800/30'
          : 'bg-gradient-to-r from-transparent via-gray-200 to-transparent dark:via-gray-700'
      )} />

      {/* 热力图 */}
      <div className="relative">
        <div
          className={cn(
            'grid gap-1.5',
            recent7Days.length > 7
              ? 'grid-auto-flow-col auto-cols-[36px] overflow-x-auto scrollbar-hide'
              : 'grid-cols-7'
          )}
        >
          {recent7Days.map((d) => {
            return (
              <div key={d.day} className="flex flex-col items-center gap-1 shrink-0">
                <div
                  title={d.status === 'done' ? `第 ${d.day} 天 · 已完成` : d.status === 'today' ? '今日目标' : `第 ${d.day} 天`}
                  className={cn(
                    'w-9 h-9 rounded-lg flex items-center justify-center text-[11px] font-semibold transition-all duration-300 tabular-nums',
                    d.status === 'done'
                      ? 'bg-gradient-to-br from-emerald-400 to-teal-500 text-white shadow-sm shadow-emerald-200/50 dark:shadow-emerald-900/30'
                      : d.status === 'today'
                      ? 'bg-gradient-to-br from-amber-300 to-orange-400 text-white shadow-sm shadow-orange-200/50 ring-2 ring-amber-200/60 dark:ring-amber-700/50'
                      : 'bg-gray-100 dark:bg-slate-700/50 text-gray-400 dark:text-gray-500'
                  )}
                >
                  {d.day}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* 底部信息栏 */}
      <div className="mt-3 flex items-center justify-between text-[10px] text-gray-400 dark:text-gray-500">
        <span>连续打卡越多，奖励越丰厚</span>
        <div className="flex items-center gap-2">
          {wallet && (
            <span className="flex items-center gap-1">
              <Coins className="w-3 h-3 text-amber-500" />
              <span className="text-amber-600 dark:text-amber-400 font-medium">{wallet.balance}</span>
              <span className="text-gray-300 dark:text-gray-600">·</span>
              <span className="text-emerald-600 dark:text-emerald-400 font-medium">{wallet.conversions} 次翻译</span>
            </span>
          )}
          <span>连续打卡 {streak} 天</span>
        </div>
      </div>
    </div>
  );
}
