/**
 * 日语假名注音（振假名）工具。
 * 依赖 jaReadingDict 词典，提供汉字→假名/罗马音的查询与 HTML ruby 渲染。
 *
 * 参考设计规范 2.3：
 *  - getReading：精确匹配 → 单字组合匹配
 *  - renderFurigana：汉字段替换为 <ruby>汉字<rt>假名</rt></ruby>
 */

import { JA_READING_DICT, type JaReadingEntry } from '@/services/jaReadingDict';

/** CJK 统一表意文字 + 扩展 A 区的汉字范围 */
const KANJI_RE = /[\u4e00-\u9fff\u3400-\u4dbf]/;

/** 是否包含汉字 */
export function hasKanji(text: string): boolean {
  return KANJI_RE.test(text);
}

/**
 * 平假名 → 片假名（码点 +0x60，覆盖 ぁ-ゖ 即 U+3041-U+3096）。
 * 范围外字符原样保留。
 */
export function toKatakana(hiragana: string): string {
  let out = '';
  for (const ch of hiragana) {
    const code = ch.codePointAt(0)!;
    if (code >= 0x3041 && code <= 0x3096) {
      out += String.fromCodePoint(code + 0x60);
    } else {
      out += ch;
    }
  }
  return out;
}

// ─── 平假名 → 罗马音映射表 ───────────────────────────────────────
// 拗音（双字符）优先匹配
const ROMAJI_TWO: Record<string, string> = {
  // 清音拗音
  'きゃ': 'kya', 'きゅ': 'kyu', 'きょ': 'kyo',
  'しゃ': 'sha', 'しゅ': 'shu', 'しょ': 'sho',
  'ちゃ': 'cha', 'ちゅ': 'chu', 'ちょ': 'cho',
  'にゃ': 'nya', 'にゅ': 'nyu', 'にょ': 'nyo',
  'ひゃ': 'hya', 'ひゅ': 'hyu', 'ひょ': 'hyo',
  'みゃ': 'mya', 'みゅ': 'myu', 'みょ': 'myo',
  'りゃ': 'rya', 'りゅ': 'ryu', 'りょ': 'ryo',
  // 浊音拗音
  'ぎゃ': 'gya', 'ぎゅ': 'gyu', 'ぎょ': 'gyo',
  'じゃ': 'ja', 'じゅ': 'ju', 'じょ': 'jo',
  'びゃ': 'bya', 'びゅ': 'byu', 'びょ': 'byo',
  // 半浊音拗音
  'ぴゃ': 'pya', 'ぴゅ': 'pyu', 'ぴょ': 'pyo',
  // 小仮名组合（外来音）
  'てぃ': 'ti', 'でぃ': 'di', 'ふぁ': 'fa', 'ふぃ': 'fi', 'ふぇ': 'fe', 'ふぉ': 'fo',
  'どぅ': 'du', 'とぅ': 'tu',
};

const ROMAJI_ONE: Record<string, string> = {
  // あ行
  'あ': 'a', 'い': 'i', 'う': 'u', 'え': 'e', 'お': 'o',
  // か行
  'か': 'ka', 'き': 'ki', 'く': 'ku', 'け': 'ke', 'こ': 'ko',
  // さ行
  'さ': 'sa', 'し': 'shi', 'す': 'su', 'せ': 'se', 'そ': 'so',
  // た行
  'た': 'ta', 'ち': 'chi', 'つ': 'tsu', 'て': 'te', 'と': 'to',
  // な行
  'な': 'na', 'に': 'ni', 'ぬ': 'nu', 'ね': 'ne', 'の': 'no',
  // は行
  'は': 'ha', 'ひ': 'hi', 'ふ': 'fu', 'へ': 'he', 'ほ': 'ho',
  // ま行
  'ま': 'ma', 'み': 'mi', 'む': 'mu', 'め': 'me', 'も': 'mo',
  // や行
  'や': 'ya', 'ゆ': 'yu', 'よ': 'yo',
  // ら行
  'ら': 'ra', 'り': 'ri', 'る': 'ru', 'れ': 're', 'ろ': 'ro',
  // わ行
  'わ': 'wa', 'を': 'wo',
  // 拨音
  'ん': 'n',
  // 浊音
  'が': 'ga', 'ぎ': 'gi', 'ぐ': 'gu', 'げ': 'ge', 'ご': 'go',
  'ざ': 'za', 'じ': 'ji', 'ず': 'zu', 'ぜ': 'ze', 'ぞ': 'zo',
  'だ': 'da', 'ぢ': 'ji', 'づ': 'zu', 'で': 'de', 'ど': 'do',
  // 半浊音
  'ば': 'ba', 'び': 'bi', 'ぶ': 'bu', 'べ': 'be', 'ぼ': 'bo',
  'ぱ': 'pa', 'ぴ': 'pi', 'ぷ': 'pu', 'ぺ': 'pe', 'ぽ': 'po',
  // 小仮名
  'ぁ': 'a', 'ぃ': 'i', 'ぅ': 'u', 'ぇ': 'e', 'ぉ': 'o',
  'ゃ': 'ya', 'ゅ': 'yu', 'ょ': 'yo',
  'ゎ': 'wa',
};

/**
 * 平假名 → 罗马音。先匹配双字符（拗音），再单字符；っ（促音）重复下一个辅音首字母。
 */
export function toRomaji(hiragana: string): string {
  let out = '';
  const chars = [...hiragana];
  let i = 0;
  while (i < chars.length) {
    const two = chars[i] + (chars[i + 1] ?? '');
    if (chars[i] === 'っ' || chars[i] === 'ッ') {
      // 促音：重复下一个字符的罗马音首字母
      const nextRomaji = chars[i + 1] ? (ROMAJI_TWO[chars[i + 1] + (chars[i + 2] ?? '')] ?? ROMAJI_ONE[chars[i + 1]] ?? '') : '';
      if (nextRomaji) {
        out += nextRomaji[0];
        i += 1;
        continue;
      }
      i += 1;
      continue;
    }
    if (ROMAJI_TWO[two]) {
      out += ROMAJI_TWO[two];
      i += 2;
      continue;
    }
    out += ROMAJI_ONE[chars[i]] ?? chars[i];
    i += 1;
  }
  return out;
}

/**
 * 查询单词的假名注音。
 * 1. 精确匹配 JA_READING_DICT[word]
 * 2. 单字组合匹配：逐字查词典，汉字取读音，非汉字保留
 * 无汉字或完全无匹配时返回 undefined。
 */
export function getReading(word: string): JaReadingEntry | undefined {
  if (!word) return undefined;

  // 1. 精确匹配
  const exact = JA_READING_DICT[word]?.[0];
  if (exact) return exact;

  // 2. 仅当含汉字时做单字组合
  if (!hasKanji(word)) return undefined;

  const chars = [...word];
  let hiragana = '';
  let matchedAny = false;
  for (const ch of chars) {
    const entry = JA_READING_DICT[ch]?.[0];
    if (entry) {
      hiragana += entry.hiragana;
      matchedAny = true;
    } else {
      // 非汉字字符（假名/标点）直接保留
      hiragana += ch;
    }
  }

  if (!matchedAny) return undefined;

  return {
    kanji: word,
    hiragana,
    katakana: toKatakana(hiragana),
    romaji: toRomaji(hiragana),
    level: '?',
    meaning: '',
  };
}

/**
 * 在文本中将汉字段替换为 <ruby>汉字<rt>假名</rt></ruby> HTML。
 * 无法注音的汉字段原样保留。
 */
export function renderFurigana(text: string): string {
  return text.replace(/[\u4e00-\u9fff\u3400-\u4dbf]+/g, (match) => {
    const entry = getReading(match);
    if (!entry || entry.hiragana === match) return match;
    return `<ruby>${match}<rt>${entry.hiragana}</rt></ruby>`;
  });
}
