import { useState, useEffect, useCallback, useRef } from 'react';
import { translateWord } from '@/services/baiduTranslate';
import { CN_EN_DICT } from '@/services/replacementEngine';
import type { TranslationPair } from '@/services/translationService';
import type { Article, Language } from '@/types';
import { isSourceLanguageText } from '@/lib/langCharSet';
import { lookupWord, clearWordLookupCache } from '@/lib/wordLookupCache';

/**
 * 译文中要高亮的单词。
 *
 * - `matched`  : 译文里实际高亮的子串
 * - `original` : 原型/原词；与 matched 不同时在词上方显示徽章
 * - `direction`: 高亮方向（中文→外文 / 外文→中文），方便未来按方向区分样式
 */
export interface HighlightWord {
  matched: string;
  original: string;
  sourceLanguage?: Language;
  direction?: 'cn-in-translated' | 'foreign-in-translated';
}

interface SelectedWord {
  word: string;
  position: { x: number; y: number };
  sourceSentence: string;
}

export function useTextSelection(
  translationPairs: TranslationPair[],
  article: Article | null | undefined
) {
  const [highlightWord, setHighlightWord] = useState<HighlightWord | null>(null);
  const [selectedWord, setSelectedWord] = useState<SelectedWord | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // ────────────────────────────────────────────────────────────────
  // 旧路径：source=zh 且选中中文 → 在译文中找英文并高亮（保留原逻辑）
  // ────────────────────────────────────────────────────────────────
  const handleOriginalTextSelection = useCallback(() => {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) {
      setHighlightWord(null);
      return;
    }

    const selectedText = selection.toString().trim();
    if (!selectedText) {
      setHighlightWord(null);
      return;
    }

    if (!article) return;

    const src = article.sourceLanguage;
    const isChineseSel = /[\u4e00-\u9fff]/.test(selectedText);
    const isForeignSel = !isChineseSel && isSourceLanguageText(selectedText, src);

    const matchedPair = translationPairs.find(p => p.original?.includes(selectedText));
    if (!matchedPair?.translated) return;

    // ── 分支 A：旧逻辑 - 中文→英文高亮（零破坏） ──
    if (src === 'zh' && isChineseSel) {
      // 1. 内置词典查找
      const dictEntry = CN_EN_DICT[selectedText];
      if (dictEntry && article.targetLanguage === 'en') {
        const translated = matchedPair.translated;
        const lowerTranslated = translated.toLowerCase();
        const dictEn = dictEntry[0].en;

        if (lowerTranslated.includes(dictEn.toLowerCase())) {
          setHighlightWord({ matched: dictEn, original: dictEn, sourceLanguage: src, direction: 'cn-in-translated' });
          return;
        }
        // 词根匹配
        const stemDict = dictEn.toLowerCase().replace(/(s|es|ed|ing|ly|er|est)$/, '');
        for (const w of translated.split(/\s+/).filter(w => /[a-zA-Z]/.test(w))) {
          const stemW = w.toLowerCase().replace(/(s|es|ed|ing|ly|er|est)$/, '');
          if (stemDict === stemW && w.length > 2) {
            setHighlightWord({ matched: w, original: dictEn, sourceLanguage: src, direction: 'cn-in-translated' });
            return;
          }
        }
        setHighlightWord({ matched: dictEn, original: dictEn, sourceLanguage: src, direction: 'cn-in-translated' });
        return;
      }

      // 2. API 翻译
      translateWord(selectedText, article.sourceLanguage, article.targetLanguage)
        .then(apiResult => {
          if (!apiResult) {
            setHighlightWord(null);
            return;
          }
          const translated = matchedPair.translated;

          if (article.targetLanguage === 'en') {
            const lowerApi = apiResult.toLowerCase();
            const lowerTrans = translated.toLowerCase();

            if (lowerTrans.includes(lowerApi)) {
              setHighlightWord({ matched: apiResult, original: apiResult, sourceLanguage: src, direction: 'cn-in-translated' });
              return;
            }
            const stemApi = lowerApi.replace(/(s|es|ed|ing|ly|er|est)$/, '');
            for (const w of translated.split(/\s+/).filter(w => /[a-zA-Z]/.test(w))) {
              const stemW = w.toLowerCase().replace(/(s|es|ed|ing|ly|er|est)$/, '');
              if (stemApi === stemW && w.length > 2) {
                setHighlightWord({ matched: w, original: apiResult, sourceLanguage: src, direction: 'cn-in-translated' });
                return;
              }
            }
          } else {
            if (translated.includes(apiResult)) {
              setHighlightWord({ matched: apiResult, original: apiResult, sourceLanguage: src, direction: 'cn-in-translated' });
              return;
            }
          }
          setHighlightWord({ matched: apiResult, original: apiResult, sourceLanguage: src, direction: 'cn-in-translated' });
        });
      return;
    }

    // ── 分支 B：新功能 - 选外文 → 译文中高亮对应中文 ──
    if (isForeignSel) {
      void highlightForeignInChinese(
        selectedText,
        matchedPair.translated,
        src,
        setHighlightWord
      );
      return;
    }

    setHighlightWord(null);
  }, [translationPairs, article]);

  // ────────────────────────────────────────────────────────────────
  // 译文区域选词：显示释义弹窗（行为不变）
  // ────────────────────────────────────────────────────────────────
  const handleTranslatedTextSelection = useCallback(() => {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) {
      setSelectedWord(null);
      return;
    }

    const selectedText = selection.toString().trim();
    if (!selectedText) {
      setSelectedWord(null);
      return;
    }

    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();

    let sourceSentence = '';
    if (article) {
      const matchedPair = translationPairs.find(p => {
        const trans = p.translated || '';
        if (article.targetLanguage === 'en') {
          return trans.toLowerCase().includes(selectedText.toLowerCase());
        }
        return trans.includes(selectedText);
      });
      if (matchedPair) {
        sourceSentence = matchedPair.original;
      }
    }

    setSelectedWord({
      word: selectedText,
      position: { x: rect.left + rect.width / 2, y: rect.top },
      sourceSentence,
    });
  }, [translationPairs, article]);

  // 点击外部清除选中（排除 WordPopup 区域）
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      if (target.closest('[data-word-popup="true"]')) return;
      if (containerRef.current && !containerRef.current.contains(target)) {
        setHighlightWord(null);
        setSelectedWord(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // 切换文章时清空翻译缓存，避免长会话内存膨胀
  useEffect(() => {
    return () => clearWordLookupCache();
  }, [article?.id]);

  const clearHighlight = useCallback(() => setHighlightWord(null), []);

  return {
    highlightWord,
    selectedWord,
    setSelectedWord,
    containerRef,
    handleOriginalTextSelection,
    handleTranslatedTextSelection,
    clearHighlight,
  };
}

// ────────────────────────────────────────────────────────────────
// 新功能内部实现：选中一个外文词，在译文里找对应的中文译词并高亮
// ────────────────────────────────────────────────────────────────
async function highlightForeignInChinese(
  selected: string,
  translated: string,
  src: Language,
  set: (hw: HighlightWord | null) => void
) {
  // 1) 调 API 查中文原型（腾讯→百度→MyMemory 自动降级）
  const cnLemma = await lookupWord(selected, src, 'zh');
  if (!cnLemma) {
    set(null);
    return;
  }

  // 2) 从 API 返回的中文译文中提取纯中文候选词（去标点/去空/去重/长词优先）
  const candidates = Array.from(
    new Set(cnLemma.split(/[^\u4e00-\u9fff]+/).filter(Boolean))
  ).sort((a, b) => b.length - a.length);

  if (candidates.length === 0) {
    set(null);
    return;
  }

  // 3) 在译文里找最长命中
  for (const c of candidates) {
    if (translated.includes(c)) {
      set({
        matched: c,
        original: selected,
        sourceLanguage: src,
        direction: 'foreign-in-translated',
      });
      return;
    }
  }

  // 4) 兜底：API 返回了候选但译文无任何命中（罕见，如译文过短）→ 不高亮
  set(null);
}
