import { create } from 'zustand';
import type { PublicArticle, Category } from '@/types';
import {
  getPublicArticles,
  getPublicArticle,
  getPublicCategories,
  type PublicArticleQuery,
} from '@/api/publicArticle';

interface PublicArticleState {
  articles: PublicArticle[];
  total: number;
  loading: boolean;
  categories: Category[];
  currentArticle: PublicArticle | null;
  currentPage: number;
  fetchArticles: (params?: PublicArticleQuery) => Promise<void>;
  fetchArticle: (id: string) => Promise<PublicArticle | null>;
  fetchCategories: () => Promise<void>;
  setCurrentArticle: (a: PublicArticle | null) => void;
}

export const usePublicArticleStore = create<PublicArticleState>((set) => ({
  articles: [],
  total: 0,
  loading: false,
  categories: [],
  currentArticle: null,
  currentPage: 1,

  fetchArticles: async (params = {}) => {
    set({ loading: true });
    try {
      const data = await getPublicArticles({ page: 1, pageSize: 20, ...params });
      set({
        articles: data.list,
        total: data.total,
        currentPage: data.page,
        loading: false,
      });
    } catch (e) {
      set({ loading: false });
      console.error('[公共文章库] 加载失败:', e);
    }
  },

  fetchArticle: async (id: string) => {
    set({ loading: true });
    try {
      const article = await getPublicArticle(id);
      set({ currentArticle: article, loading: false });
      return article;
    } catch (e) {
      set({ loading: false });
      console.error('[公共文章库] 加载详情失败:', e);
      return null;
    }
  },

  fetchCategories: async () => {
    try {
      const data = await getPublicCategories();
      const categories: Category[] = data.list.map((c) => ({
        id: c.id,
        name: c.name,
        icon: c.icon || undefined,
        articleCount: c._count?.articles || 0,
      }));
      set({ categories });
    } catch (e) {
      console.error('[公共文章库] 加载分类失败:', e);
    }
  },

  setCurrentArticle: (a) => set({ currentArticle: a }),
}));
