import { create } from 'zustand';
import type { ReadMode, ViewMode, Language } from '@/types';

interface SelectedWord {
  word: string;
  translation: string;
  phonetic?: string;
  partOfSpeech?: string;
  language?: Language;
  reading?: string;
  syllables?: string;
}

interface UIState {
  readMode: ReadMode;
  viewMode: ViewMode;
  selectedLanguage: Language;
  showSidebar: boolean;
  showWordModal: boolean;
  selectedWord: SelectedWord | null;
  /** 登录提示弹窗（游客尝试受限操作时显示） */
  showLoginPrompt: boolean;
  setReadMode: (mode: ReadMode) => void;
  setViewMode: (mode: ViewMode) => void;
  setSelectedLanguage: (lang: Language) => void;
  toggleSidebar: () => void;
  showWordDetail: (word: SelectedWord) => void;
  hideWordDetail: () => void;
  setShowLoginPrompt: (v: boolean) => void;
}

export const useUIStore = create<UIState>()((set) => ({
  readMode: 'parallel',
  viewMode: 'line-by-line',
  selectedLanguage: 'en',
  showSidebar: true,
  showWordModal: false,
  selectedWord: null,
  showLoginPrompt: false,
  setReadMode: (mode) => set({ readMode: mode }),
  setViewMode: (mode) => set({ viewMode: mode }),
  setSelectedLanguage: (lang) => set({ selectedLanguage: lang }),
  toggleSidebar: () => set((state) => ({ showSidebar: !state.showSidebar })),
  showWordDetail: (word) => set({ showWordModal: true, selectedWord: word }),
  hideWordDetail: () => set({ showWordModal: false, selectedWord: null }),
  setShowLoginPrompt: (v) => set({ showLoginPrompt: v }),
}));