import { create } from 'zustand';
import { getWallet, spendConversion, exchangeCoins, type WalletInfo } from '@/api/learner';

interface WalletState {
  balance: number;
  conversions: number;
  syncing: boolean;
  /** 从后端同步钱包余额 */
  syncFromServer: () => Promise<void>;
  /** 消费一次长文本翻译（短文本免费不扣，后端自动判断） */
  spend: (articleId: string | undefined, contentLen: number) => Promise<{ charged: boolean; ok: boolean }>;
  /** 用虚拟币兑换翻译次数 */
  exchange: (count: number) => Promise<boolean>;
  /** 直接设置余额（打卡成功后由 checkInStore 回调更新） */
  setWallet: (w: WalletInfo) => void;
}

export const useWalletStore = create<WalletState>((set) => ({
  balance: 0,
  conversions: 0,
  syncing: false,

  syncFromServer: async () => {
    set({ syncing: true });
    try {
      const w = await getWallet();
      set({ balance: w.balance, conversions: w.conversions });
    } catch (e) {
      console.error('同步钱包失败:', e);
    } finally {
      set({ syncing: false });
    }
  },

  spend: async (articleId, contentLen) => {
    try {
      const res = await spendConversion(articleId, contentLen);
      set({ balance: res.wallet.balance, conversions: res.wallet.conversions });
      return { charged: res.charged, ok: true };
    } catch (e) {
      console.error('消费翻译次数失败:', e);
      return { charged: true, ok: false };
    }
  },

  exchange: async (count) => {
    try {
      const res = await exchangeCoins(count);
      set({ balance: res.wallet.balance, conversions: res.wallet.conversions });
      return true;
    } catch (e) {
      console.error('兑换失败:', e);
      return false;
    }
  },

  setWallet: (w) => set({ balance: w.balance, conversions: w.conversions }),
}));
