import { useState, useEffect, useRef } from 'react';
import { Plus, X, Volume2 } from 'lucide-react';
import { useVocabularyStore } from '@/stores/vocabularyStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { EN_CN_DICT, POS_LABELS } from '@/services/enCnDict';
import { translateWord } from '@/services/baiduTranslate';
import { showSyllables } from '@/lib/syllables';
import { createInitialReviewState } from '@/lib/ebbinghaus';
import { getReading } from '@/lib/jaFurigana';
import { speak } from '@/lib/speech';
import type { VocabularyWord, Language } from '@/types';

interface WordPopupProps {
  word: string;
  position: { x: number; y: number };
  onClose: () => void;
  articleId: string;
  sourceSentence: string;
  targetLanguage: Language;
}

export default function WordPopup({ word, position, onClose, articleId, sourceSentence, targetLanguage }: WordPopupProps) {
  const popupRef = useRef<HTMLDivElement>(null);
  const { addWord, words } = useVocabularyStore();
  const { settings } = useSettingsStore();
  const [isAdded, setIsAdded] = useState(false);
  const [apiTranslation, setApiTranslation] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  // 是否为英文（使用本地词典）
  const isEnglish = targetLanguage === 'en';

  // 英文：查找本地词典的多重释义
  const wordLower = word.toLowerCase().replace(/[^a-z]/g, '');
  const entries = isEnglish ? (EN_CN_DICT[wordLower] || []) : [];

  // 日语：查假名注音
  const jaReading = targetLanguage === 'ja' ? getReading(word) : undefined;

  // 点击外部关闭
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (popupRef.current && !popupRef.current.contains(e.target as Node)) {
        onClose();
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  // 检查是否已收藏
  useEffect(() => {
    const exists = words.some(w => w.word.toLowerCase() === word.toLowerCase());
    setIsAdded(exists);
  }, [word, words]);

  // 日语词典命中且有释义时也无需调 API
  const hasJaDictMeaning = targetLanguage === 'ja' && !!jaReading?.meaning;

  // 获取翻译：英文优先用词典，其他语种/词典缺失时调用 API
  useEffect(() => {
    // 英文有本地词条 / 日语有词典释义时不需要 API
    if ((isEnglish && entries.length > 0) || hasJaDictMeaning) return;

    if (word) {
      setIsLoading(true);
      translateWord(word, targetLanguage, 'zh')
        .then(result => {
          if (result) {
            setApiTranslation(result);
          }
        })
        .finally(() => {
          setIsLoading(false);
        });
    }
  }, [word, targetLanguage, isEnglish, entries.length, hasJaDictMeaning]);

  // 朗读发音（统一使用 speak 工具，自动适配目标语言）
  const handleSpeak = () => {
    speak({ text: word, lang: targetLanguage, rate: settings.speechRate });
  };

  // 添加到生词本
  const handleAdd = () => {
    if (isAdded) return;

    // 获取翻译：英文取词典第一条释义，其他语种取 API 翻译结果
    let translation: string;
    let phonetic: string | undefined;
    let partOfSpeech: string | undefined;

    if (isEnglish && entries.length > 0) {
      translation = entries[0].meanings.join('、');
      phonetic = entries[0].phonetic;
      partOfSpeech = entries[0].pos;
    } else {
      translation = apiTranslation || word;
    }

    const newWord: VocabularyWord = {
      id: crypto.randomUUID(),
      word,
      translation,
      language: targetLanguage,
      phonetic,
      partOfSpeech,
      reading: targetLanguage === 'ja' ? jaReading?.hiragana : undefined,
      syllables: isEnglish ? showSyllables(word) : undefined,
      sourceArticleId: articleId,
      sourceSentence,
      difficulty: 'beginner',
      reviewCount: 0,
      createdAt: Date.now(),
      ...createInitialReviewState(),
    };

    addWord(newWord);
    setIsAdded(true);
  };

  // 加载中状态
  if (isLoading) {
    return (
      <div
        ref={popupRef}
        className="fixed z-50 bg-white dark:bg-slate-800 rounded-lg shadow-lg border border-gray-200 dark:border-slate-700 p-4 min-w-[200px]"
        data-word-popup="true"
        style={{
          left: `${position.x}px`,
          top: `${position.y}px`,
          transform: 'translate(-50%, -100%)',
        }}
      >
        <div className="flex items-center justify-center gap-2">
          <div className="w-4 h-4 border-2 border-primary-500 border-t-transparent rounded-full animate-spin"></div>
          <span className="text-sm text-gray-500">查询中...</span>
        </div>
      </div>
    );
  }

  // 英文且有词典词条：显示完整多重释义
  if (entries.length > 0) {
    return (
      <div
        ref={popupRef}
        className="fixed z-50 bg-white dark:bg-slate-800 rounded-lg shadow-lg border border-gray-200 dark:border-slate-700 p-4 min-w-[240px] max-w-[320px]"
        data-word-popup="true"
        style={{
          left: `${position.x}px`,
          top: `${position.y}px`,
          transform: 'translate(-50%, -100%)',
        }}
      >
        {/* 头部 */}
      <div className="flex items-start justify-between mb-3">
        <div>
          <h3 className="font-bold text-xl text-gray-800 dark:text-gray-100">{word}</h3>
          <p className="text-xs text-gray-400 mt-0.5">{showSyllables(word)}</p>
        </div>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 shrink-0">
          <X className="w-4 h-4" />
        </button>
      </div>

        {/* 音标 */}
        {entries[0]?.phonetic && (
          <p className="text-xs text-gray-500 dark:text-gray-400 mb-3 font-mono">
            /{entries[0].phonetic}/
          </p>
        )}

        {/* 释义列表 */}
        <div className="space-y-2 mb-4 max-h-[200px] overflow-y-auto">
          {entries.map((entry, idx) => (
            <div key={idx} className="flex items-start gap-2">
              <span className="text-xs font-medium text-primary-600 dark:text-primary-400 bg-primary-50 dark:bg-primary-900/30 px-1.5 py-0.5 rounded shrink-0">
                {POS_LABELS[entry.pos] || entry.pos}
              </span>
              <span className="text-sm text-gray-700 dark:text-gray-300">
                {entry.meanings.join('、')}
              </span>
            </div>
          ))}
        </div>

        {/* 操作按钮 */}
        <div className="flex gap-2 pt-2 border-t border-gray-100 dark:border-slate-700">
          <button onClick={handleSpeak}
            className="flex items-center gap-1 px-3 py-1.5 text-sm bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 rounded-md transition-colors"
          >
            <Volume2 className="w-3.5 h-3.5" />
            朗读
          </button>
          <button onClick={handleAdd} disabled={isAdded}
            className={`flex items-center gap-1 px-3 py-1.5 text-sm rounded-md transition-colors flex-1 justify-center ${
              isAdded
                ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 cursor-not-allowed'
                : 'bg-primary-500 hover:bg-primary-600 text-white'
            }`}
          >
            <Plus className="w-3.5 h-3.5" />
            {isAdded ? '已添加到生词本' : '添加到生词本'}
          </button>
        </div>
      </div>
    );
  }

  // 日语且有词典注音：显示假名注音
  if (targetLanguage === 'ja' && jaReading) {
    const jaTranslation = jaReading.meaning || apiTranslation || word;
    return (
      <div
        ref={popupRef}
        className="fixed z-50 bg-white dark:bg-slate-800 rounded-lg shadow-lg border border-gray-200 dark:border-slate-700 p-4 min-w-[240px] max-w-[320px]"
        data-word-popup="true"
        style={{
          left: `${position.x}px`,
          top: `${position.y}px`,
          transform: 'translate(-50%, -100%)',
        }}
      >
        {/* 头部 - 振假名 */}
        <div className="flex items-start justify-between mb-3">
          <div>
            <h3 className="font-bold text-xl text-gray-800 dark:text-gray-100">
              <ruby>
                {word}
                <rp>(</rp>
                <rt className="text-xs text-primary-500 dark:text-primary-400">{jaReading.hiragana}</rt>
                <rp>)</rp>
              </ruby>
            </h3>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 shrink-0">
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* 平/片/罗马音 */}
        <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-gray-500 dark:text-gray-400 mb-3">
          <span><strong className="text-gray-600 dark:text-gray-300">平假名:</strong> {jaReading.hiragana}</span>
          <span><strong className="text-gray-600 dark:text-gray-300">片假名:</strong> {jaReading.katakana}</span>
          <span><strong className="text-gray-600 dark:text-gray-300">罗马音:</strong> {jaReading.romaji}</span>
        </div>

        {/* JLPT 等级 */}
        {jaReading.level && jaReading.level !== '?' && (
          <span className="inline-block text-[10px] font-semibold bg-pink-100 dark:bg-pink-900/30 text-pink-700 dark:text-pink-300 px-1.5 py-0.5 rounded mb-2">
            {jaReading.level}
          </span>
        )}

        {/* 释义 */}
        <p className="text-sm text-gray-700 dark:text-gray-300 mb-4 leading-relaxed">{jaTranslation}</p>

        {/* 操作按钮 */}
        <div className="flex gap-2 pt-2 border-t border-gray-100 dark:border-slate-700">
          <button onClick={handleSpeak}
            className="flex items-center gap-1 px-3 py-1.5 text-sm bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 rounded-md transition-colors"
          >
            <Volume2 className="w-3.5 h-3.5" />
            朗读
          </button>
          <button onClick={handleAdd} disabled={isAdded}
            className={`flex items-center gap-1 px-3 py-1.5 text-sm rounded-md transition-colors flex-1 justify-center ${
              isAdded
                ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 cursor-not-allowed'
                : 'bg-primary-500 hover:bg-primary-600 text-white'
            }`}
          >
            <Plus className="w-3.5 h-3.5" />
            {isAdded ? '已添加到生词本' : '添加到生词本'}
          </button>
        </div>
      </div>
    );
  }

  {/* Non-EN or no dictionary entry: API result */}
  return (
    <div
      ref={popupRef}
      className="fixed z-50 bg-white dark:bg-slate-800 rounded-lg shadow-lg border border-gray-200 dark:border-slate-700 p-4 min-w-[220px] max-w-[320px]"
      data-word-popup="true"
      style={{
        left: `${position.x}px`,
        top: `${position.y}px`,
        transform: 'translate(-50%, -100%)',
      }}
    >
      <div className="flex items-start justify-between mb-2">
        <div>
          <h3 className="font-bold text-lg text-gray-800 dark:text-gray-100">{word}</h3>
          {targetLanguage === 'en' && (
            <p className="text-xs text-gray-400 mt-0.5">{showSyllables(word)}</p>
          )}
        </div>
        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 shrink-0">
          <X className="w-4 h-4" />
        </button>
      </div>

      {apiTranslation ? (
        <p className="text-sm text-gray-700 dark:text-gray-300 mb-3 leading-relaxed">{apiTranslation}</p>
      ) : (
        <p className="text-sm text-gray-500 dark:text-gray-400 mb-3">未找到释义，可手动添加到生词本</p>
      )}

      <div className="flex gap-2">
        <button onClick={handleSpeak}
          className="flex items-center gap-1 px-3 py-1.5 text-sm bg-gray-100 dark:bg-slate-700 hover:bg-gray-200 dark:hover:bg-slate-600 rounded-md transition-colors"
        >
          <Volume2 className="w-3.5 h-3.5" />
          朗读
        </button>
        <button onClick={handleAdd} disabled={isAdded}
          className={`flex items-center gap-1 px-3 py-1.5 text-sm rounded-md transition-colors flex-1 justify-center ${
            isAdded
              ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400 cursor-not-allowed'
              : 'bg-primary-500 hover:bg-primary-600 text-white'
          }`}
        >
          <Plus className="w-3.5 h-3.5" />
          {isAdded ? '已添加' : '添加生词'}
        </button>
      </div>
    </div>
  );
}
