import { Volume2 } from 'lucide-react';
import type { PhoneticEntry } from '@/data/enPhonetics';
import { PHONETIC_CATEGORY_LABELS, PHONETIC_CATEGORY_ORDER } from '@/data/enPhonetics';
import { speak } from '@/lib/speech';

interface PhoneticTableProps {
  phonetics: PhoneticEntry[];
}

export default function PhoneticTable({ phonetics }: PhoneticTableProps) {
  const handlePlay = (phonetic: PhoneticEntry) => {
    // IPA 符号无法直接 TTS，朗读第一个示例词
    const word = phonetic.examples[0] || '';
    if (word) speak({ text: word, lang: 'en' });
  };

  // 按分类分组
  const grouped = PHONETIC_CATEGORY_ORDER.map((cat) => ({
    category: cat,
    label: PHONETIC_CATEGORY_LABELS[cat] || cat,
    items: phonetics.filter((p) => p.category === cat),
  })).filter((g) => g.items.length > 0);

  return (
    <div className="space-y-6">
      {grouped.map((group) => (
        <div key={group.category}>
          <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2.5 flex items-center gap-2">
            <span className="inline-block w-1 h-4 rounded-full bg-primary-500" />
            {group.label}
            <span className="text-xs font-normal text-gray-400">({group.items.length})</span>
          </h3>
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
            {group.items.map((phonetic) => (
              <button
                key={phonetic.ipa}
                onClick={() => handlePlay(phonetic)}
                className="group flex items-center gap-2.5 p-2.5 rounded-xl bg-white dark:bg-slate-800 border border-gray-100 dark:border-slate-700 hover:border-primary-300 dark:hover:border-primary-600 hover:shadow-sm transition-all text-left"
              >
                <span className="text-lg font-mono font-semibold text-primary-600 dark:text-primary-400 shrink-0">
                  {phonetic.ipa}
                </span>
                <div className="min-w-0 flex-1">
                  <div className="text-xs text-gray-500 dark:text-gray-400 truncate">
                    {phonetic.examples.join(', ')}
                  </div>
                  {phonetic.similarTo && (
                    <div className="text-[10px] text-orange-400 dark:text-orange-500">
                      易混 {phonetic.similarTo}
                    </div>
                  )}
                </div>
                <Volume2 className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 group-hover:text-primary-500 transition-colors shrink-0" />
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
