/**
 * MyMemory 翻译 API 接入
 * 优点：完全免费、无需 API Key、注册即可使用
 * 缺点：单 IP 默认 5000 字/天（匿名），提升需要邮箱注册
 * 文档：https://mymemory.translated.net/doc/spec.php
 *
 * 用途：作为"零配置"翻译引擎的默认选项，无需在 .env 中配置任何密钥。
 */

import type { Language } from '@/types';

// MyMemory 语种代码与我们的 Language 映射完全一致（ISO 639-1）
const MYMEMORY_LANG_MAP: Record<Language, string> = {
  zh: 'zh-CN',
  en: 'en',
  ja: 'ja',
  ru: 'ru',
  es: 'es',
  ko: 'ko',
  fr: 'fr',
  de: 'de',
  ar: 'ar',
};

interface MyMemoryResponse {
  responseData: { translatedText: string; match: number };
  responseStatus: number | string;
  responseDetails?: string;
}

/**
 * 单次翻译（GET 请求，简单但有 URL 长度限制）
 */
export async function mymemoryTranslate(
  text: string,
  from: Language,
  to: Language
): Promise<string> {
  const fromCode = MYMEMORY_LANG_MAP[from] || 'auto';
  const toCode = MYMEMORY_LANG_MAP[to] || 'en';
  const url = new URL('https://api.mymemory.translated.net/get');
  url.searchParams.set('q', text);
  url.searchParams.set('langpair', `${fromCode}|${toCode}`);

  const res = await fetch(url.toString());
  if (!res.ok) {
    throw new Error(`MyMemory 请求失败: HTTP ${res.status}`);
  }
  const data = (await res.json()) as MyMemoryResponse;
  if (Number(data.responseStatus) !== 200) {
    throw new Error(
      `MyMemory 返回错误: ${data.responseStatus} ${data.responseDetails ?? ''}`
    );
  }
  return data.responseData.translatedText;
}

/**
 * 批量翻译：MyMemory 没有真正的批量端点，并行调用单次接口。
 * 为避免触发限流，使用 6 并发（实测安全）。
 */
const BATCH_CONCURRENCY = 6;

export async function mymemoryTranslateBatch(
  sentences: string[],
  from: Language,
  to: Language
): Promise<string[]> {
  if (sentences.length === 0) return [];

  const results: string[] = new Array(sentences.length);
  let cursor = 0;

  // 简单的并发池
  const worker = async () => {
    while (cursor < sentences.length) {
      const idx = cursor++;
      try {
        results[idx] = await mymemoryTranslate(sentences[idx], from, to);
      } catch {
        results[idx] = sentences[idx]; // 失败回退原文
      }
    }
  };

  const workers = Array.from(
    { length: Math.min(BATCH_CONCURRENCY, sentences.length) },
    () => worker()
  );
  await Promise.all(workers);
  return results;
}

/**
 * 检测 MyMemory 是否可达（轻量 ping）
 */
let _myMemoryAvailableCache: boolean | null = null;
let _myMemoryAvailableCacheAt = 0;
const MYMEMORY_TTL = 60_000; // 1 分钟缓存

export async function isMyMemoryAvailable(): Promise<boolean> {
  if (
    _myMemoryAvailableCache !== null &&
    Date.now() - _myMemoryAvailableCacheAt < MYMEMORY_TTL
  ) {
    return _myMemoryAvailableCache;
  }
  try {
    const res = await fetch(
      'https://api.mymemory.translated.net/get?q=ping&langpair=en|zh-CN',
      { method: 'GET' }
    );
    _myMemoryAvailableCache = res.ok;
  } catch {
    _myMemoryAvailableCache = false;
  }
  _myMemoryAvailableCacheAt = Date.now();
  return _myMemoryAvailableCache;
}
