import { useState, useEffect, useRef, useCallback } from 'react';

interface UseSplitPaneOptions {
  initialRatio?: number;
  minRatio?: number;
  maxRatio?: number;
}

export function useSplitPane(options: UseSplitPaneOptions = {}) {
  const { initialRatio = 0.5, minRatio = 0.2, maxRatio = 0.8 } = options;

  const [horizontalRatio, setHorizontalRatio] = useState(initialRatio);
  const [verticalRatio, setVerticalRatio] = useState(initialRatio);
  const [isDragging, setIsDragging] = useState<'horizontal' | 'vertical' | null>(null);
  const dragStartRef = useRef<{ clientX: number; clientY: number; ratio: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const startHorizontalDrag = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragStartRef.current = { clientX: e.clientX, clientY: e.clientY, ratio: horizontalRatio };
    setIsDragging('horizontal');
  }, [horizontalRatio]);

  const startVerticalDrag = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragStartRef.current = { clientX: e.clientX, clientY: e.clientY, ratio: verticalRatio };
    setIsDragging('vertical');
  }, [verticalRatio]);

  useEffect(() => {
    if (!isDragging) return;

    document.body.style.userSelect = 'none';
    document.body.style.cursor = isDragging === 'horizontal' ? 'col-resize' : 'row-resize';

    const handleMouseMove = (e: MouseEvent) => {
      e.preventDefault();
      if (!dragStartRef.current || !containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();

      if (isDragging === 'horizontal') {
        const delta = e.clientX - dragStartRef.current.clientX;
        const newRatio = dragStartRef.current.ratio + delta / rect.width;
        setHorizontalRatio(Math.max(minRatio, Math.min(maxRatio, newRatio)));
      } else {
        const delta = e.clientY - dragStartRef.current.clientY;
        const newRatio = dragStartRef.current.ratio + delta / rect.height;
        setVerticalRatio(Math.max(minRatio, Math.min(maxRatio, newRatio)));
      }
    };

    const handleMouseUp = () => {
      setIsDragging(null);
      dragStartRef.current = null;
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.userSelect = '';
      document.body.style.cursor = '';
    };
  }, [isDragging, minRatio, maxRatio]);

  return {
    horizontalRatio,
    verticalRatio,
    isDragging,
    containerRef,
    startHorizontalDrag,
    startVerticalDrag,
  };
}
