/**
 * 艾宾浩斯 SM-2 间隔重复算法
 *
 * 经典 SuperMemo-2 算法实现：
 * - 每次复习后根据用户评级（0-3）计算下次复习间隔
 * - 维护难度系数 easeFactor（EF），反映用户对单词的"容易度"
 * - 完全忘记（Again）会重置连续次数并降低 EF
 *
 * 评级说明：
 *   0 = Again：完全忘记 → 重置为 1 天后复习
 *   1 = Hard：很吃力   → 间隔 × 1.2（EF 微降）
 *   2 = Good：认识了   → 间隔 × EF（EF 不变）
 *   3 = Easy：很简单   → 间隔 × EF × 1.3（EF 提升）
 */

import type { ReviewRating } from '@/types';

export interface ReviewInput {
  /** 当前难度系数，默认 2.5 */
  easeFactor: number;
  /** 当前间隔（天） */
  interval: number;
  /** 当前连续正确次数 */
  repetitions: number;
}

export interface ReviewResult {
  /** 新的难度系数 */
  easeFactor: number;
  /** 新的间隔（天） */
  interval: number;
  /** 新的连续正确次数 */
  repetitions: number;
  /** 下次复习时间戳（毫秒） */
  nextReviewAt: number;
}

/** 最小难度系数（防止一直降导致复习频率过高） */
const MIN_EASE_FACTOR = 1.3;
/** 默认难度系数 */
const DEFAULT_EASE_FACTOR = 2.5;

/**
 * 根据评级计算下次复习参数
 */
export function calculateNextReview(
  input: ReviewInput,
  rating: ReviewRating,
  now: number = Date.now()
): ReviewResult {
  let { easeFactor, interval, repetitions } = input;

  // 兜底：处理旧数据缺字段的情况
  if (!easeFactor || easeFactor < MIN_EASE_FACTOR) easeFactor = DEFAULT_EASE_FACTOR;
  if (!interval || interval < 0) interval = 0;
  if (!repetitions || repetitions < 0) repetitions = 0;

  if (rating === 0) {
    // 完全忘记：重置进度，EF 降低
    repetitions = 0;
    interval = 1;
    easeFactor = Math.max(MIN_EASE_FACTOR, easeFactor - 0.2);
  } else {
    // 1/2/3 都算正确
    repetitions += 1;

    if (repetitions === 1) {
      // 第一次正确：1 天后
      interval = 1;
    } else if (repetitions === 2) {
      // 第二次正确：3 天后
      interval = 3;
    } else {
      // 第三次及以上：按当前 EF 缩放
      let multiplier = easeFactor;
      if (rating === 1) multiplier = 1.2; // Hard
      else if (rating === 2) multiplier = easeFactor; // Good
      else if (rating === 3) multiplier = easeFactor * 1.3; // Easy
      interval = Math.round(interval * multiplier);
    }

    // 调整 EF
    if (rating === 1) easeFactor = Math.max(MIN_EASE_FACTOR, easeFactor - 0.15);
    else if (rating === 2) easeFactor = Math.max(MIN_EASE_FACTOR, easeFactor);
    else if (rating === 3) easeFactor = easeFactor + 0.15; // EF 只增不减上限
  }

  return {
    easeFactor: Math.round(easeFactor * 100) / 100,
    interval,
    repetitions,
    nextReviewAt: now + interval * 24 * 60 * 60 * 1000,
  };
}

/** 创建新单词的初始复习参数（首次添加：1 天后复习） */
export function createInitialReviewState(now: number = Date.now()): Pick<
  import('@/types').VocabularyWord,
  'easeFactor' | 'interval' | 'repetitions' | 'nextReviewAt'
> {
  return {
    easeFactor: DEFAULT_EASE_FACTOR,
    interval: 1,
    repetitions: 0,
    nextReviewAt: now + 24 * 60 * 60 * 1000,
  };
}

/** 判断单词是否到期需要复习（now >= nextReviewAt） */
export function isDue(word: { nextReviewAt: number }, now: number = Date.now()): boolean {
  return word.nextReviewAt <= now;
}

/** 友好显示"距下次复习" */
export function formatTimeUntil(timestamp: number, now: number = Date.now()): string {
  const diff = timestamp - now;
  if (diff <= 0) return '现在可复习';

  const minutes = Math.floor(diff / (60 * 1000));
  const hours = Math.floor(diff / (60 * 60 * 1000));
  const days = Math.floor(diff / (24 * 60 * 60 * 1000));

  if (minutes < 60) return `${minutes} 分钟后`;
  if (hours < 24) return `${hours} 小时后`;
  if (days < 30) return `${days} 天后`;
  const months = Math.floor(days / 30);
  if (months < 12) return `${months} 个月后`;
  return `${Math.floor(days / 365)} 年后`;
}

/** 评级显示信息 */
export const REVIEW_RATINGS: Record<ReviewRating, { label: string; color: string; description: string }> = {
  0: { label: '再看看', color: 'red', description: '完全忘记，重置进度' },
  1: { label: '吃力', color: 'orange', description: '很吃力，缩短间隔' },
  2: { label: '记住了', color: 'primary', description: '认识，标准间隔' },
  3: { label: '简单', color: 'green', description: '轻松，拉长间隔' },
};
