/**
 * Learner / 打卡 / 钱包 相关 API。
 */
import { apiGet, apiPost } from './client';

export interface WalletInfo {
  balance: number;
  conversions: number;
}

export interface RegisterDeviceResponse {
  token: string;
  learnerId: string;
  isNew: boolean;
  wallet: WalletInfo;
}

export interface CheckinStatus {
  streak: number;
  totalDays: number;
  checkedToday: boolean;
  maxStreak: number;
  maxStreakReached: boolean;
  nextRewardCoins: number;
  history: Array<{
    id: string;
    dateKey: string;
    dayIndex: number;
    coinsAwarded: number;
  }>;
}

export interface MeResponse {
  learnerId: string;
  wallet: WalletInfo;
  checkin: {
    streak: number;
    totalDays: number;
    checkedToday: boolean;
    maxStreak: number;
    maxStreakReached: boolean;
  };
}

export interface CheckinResponse {
  checkIn: { id: string; dateKey: string; dayIndex: number; coinsAwarded: number };
  wallet: WalletInfo;
  streak: number;
  coinsAwarded: number;
  maxStreakReached: boolean;
}

export interface SpendResponse {
  wallet: WalletInfo;
  charged: boolean;
  spentFromBalance?: number;
}

/** 匿名设备注册 */
export function registerDevice(deviceId: string) {
  return apiPost<RegisterDeviceResponse>('/learner/device', { deviceId }, undefined);
}

/** 获取当前 learner 信息（钱包 + 打卡状态） */
export function getMe() {
  return apiGet<MeResponse>('/learner/me');
}

/** 获取打卡状态 */
export function getCheckinStatus() {
  return apiGet<CheckinStatus>('/checkin/status');
}

/** 执行今日打卡 */
export function checkIn() {
  return apiPost<CheckinResponse>('/checkin');
}

/** 获取钱包余额 */
export function getWallet() {
  return apiGet<WalletInfo>('/wallet');
}

/** 消费一次长文本翻译 */
export function spendConversion(articleId: string | undefined, contentLen: number) {
  return apiPost<SpendResponse>('/wallet/spend', { articleId, contentLen });
}

/** 用虚拟币兑换翻译次数 */
export function exchangeCoins(count: number) {
  return apiPost<{ wallet: WalletInfo }>('/wallet/exchange', { count });
}
