import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  BookOpen,
  Shuffle,
  Volume2,
  Settings2,
  RotateCcw,
  RefreshCw,
  Eye,
  EyeOff,
  Columns2,
  LayoutList,
  FileText,
  Languages,
  Info,
  LayoutGrid,
  Share2,
} from 'lucide-react';
import { useArticleStore } from '@/stores/articleStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { useUIStore } from '@/stores/uiStore';
import { useCheckInStore } from '@/stores/checkInStore';
import { useAuthStore } from '@/stores/authStore';
import WordModal from '@/components/WordModal';
import WordPopup from '@/components/WordPopup';
import ReplaceConfigPanel from '@/components/ReplaceConfigPanel';
import EmptyState from '@/components/EmptyState';
import BackButton from '@/components/BackButton';
import TranslationContent from '@/components/TranslationContent';
import ShareToPublicModal from '@/components/ShareToPublicModal';
import { generateReplacements, supportsWordReplacement } from '@/services/replacementEngine';
import type { WordReplacement, PartOfSpeech, Difficulty } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import { cn } from '@/lib/utils';
import { speak } from '@/lib/speech';
import { useSplitPane } from '@/hooks/useSplitPane';
import { useTextSelection } from '@/hooks/useTextSelection';
import { useTranslation } from '@/hooks/useTranslation';
import type { ViewMode } from '@/types';

export default function ReadPage() {
  const { articleId } = useParams<{ articleId: string }>();
  const navigate = useNavigate();
  const { articles, currentArticle, setCurrentArticle, updateWordReplacements, updateArticle } = useArticleStore();
  const { readMode, setReadMode, viewMode, setViewMode, showWordDetail, setShowLoginPrompt } = useUIStore();
  const { settings } = useSettingsStore();
  const isGuest = useAuthStore((s) => s.isGuest);

  // ─── Custom hooks ────────────────────────────────────
  const { horizontalRatio, verticalRatio, containerRef: splitPaneRef, startHorizontalDrag, startVerticalDrag } = useSplitPane();

  const {
    translationPairs,
    isTranslating,
    translationError,
    noTranslationNeeded,
    translationProgress,
    translationProgressText,
    handleTranslate,
    retryTranslation,
    cancelTranslation,
    restoreTranslation,
  } = useTranslation(updateArticle);

  const article = articles.find((a) => a.id === articleId) || currentArticle;

  // 进入文章 = 学习行为，自动打卡
  const checkIn = useCheckInStore((s) => s.checkIn);
  useEffect(() => {
    if (article) {
      checkIn();
    }
    // 仅在文章变化时触发一次
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [article?.id]);

  const {
    highlightWord,
    selectedWord,
    setSelectedWord,
    handleOriginalTextSelection,
    handleTranslatedTextSelection,
  } = useTextSelection(translationPairs, article);

  // ─── Local state ─────────────────────────────────────
  const [showConfig, setShowConfig] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [replacements, setReplacements] = useState<WordReplacement[]>([]);
  const [showTranslation, setShowTranslation] = useState(true);
  const [fontSize] = useState(settings.fontSize);
  const [highlightedParagraph, setHighlightedParagraph] = useState<number | null>(null);
  const highlightTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Use splitPane's containerRef for text selection container
  const translationContainerRef = splitPaneRef;

  // ─── Paragraph highlight ─────────────────────────────
  const handleParagraphClick = (index: number) => {
    if (highlightTimerRef.current) clearTimeout(highlightTimerRef.current);
    if (highlightedParagraph === index) {
      setHighlightedParagraph(null);
      return;
    }
    setHighlightedParagraph(index);
    highlightTimerRef.current = setTimeout(() => setHighlightedParagraph(null), 5000);
  };

  // ─── Article init / cleanup ──────────────────────────
  useEffect(() => {
    if (article) {
      setCurrentArticle(article);
      if (article.wordReplacements) {
        setReplacements(article.wordReplacements);
      }
      restoreTranslation(article);
    }
    return () => setCurrentArticle(null);
  }, [articleId]);

  // ─── Word replacement ────────────────────────────────
  const renderContent = (text: string, showReplacements: boolean) => {
    if (!showReplacements || replacements.length === 0) {
      return <p className="leading-relaxed whitespace-pre-wrap">{text}</p>;
    }

    const parts: React.ReactNode[] = [];
    let lastIndex = 0;
    const sortedReplacements = [...replacements].sort((a, b) => a.position - b.position);

    sortedReplacements.forEach((rep, idx) => {
      if (rep.position > lastIndex) {
        parts.push(<span key={`text-${idx}`}>{text.slice(lastIndex, rep.position)}</span>);
      }
      parts.push(
        <span
          key={`word-${idx}`}
          className="word-chip animate-bounce-in"
          onClick={() =>
            showWordDetail({
              word: rep.replacementWord,
              translation: rep.translation,
              phonetic: rep.phonetic,
              partOfSpeech: rep.partOfSpeech,
              language: article?.targetLanguage,
              reading: rep.reading,
            })
          }
        >
          {article?.targetLanguage === 'ja' && rep.reading ? (
            <ruby>
              {rep.replacementWord}
              <rp>(</rp>
              <rt className="text-[0.6em] text-primary-500 dark:text-primary-400">{rep.reading}</rt>
              <rp>)</rp>
            </ruby>
          ) : (
            rep.replacementWord
          )}
        </span>
      );
      lastIndex = rep.position + rep.originalWord.length;
    });

    if (lastIndex < text.length) {
      parts.push(<span key="text-end">{text.slice(lastIndex)}</span>);
    }

    return <p className="leading-relaxed whitespace-pre-wrap">{parts}</p>;
  };

  const handleGenerateReplacements = (overrideConfig?: {
    ratio: number;
    posFilter: PartOfSpeech[];
    difficulty: Difficulty;
    avoidDuplicates: boolean;
  }) => {
    const config = overrideConfig || {
      ratio: settings.replaceRatio,
      posFilter: settings.replacePosFilter,
      difficulty: settings.replaceDifficulty,
      avoidDuplicates: settings.replaceAvoidDuplicates,
    };

    const results = generateReplacements(article!.content, {
      ratio: config.ratio,
      posFilter: config.posFilter,
      difficulty: config.difficulty,
      language: article!.targetLanguage,
      avoidDuplicates: config.avoidDuplicates,
    });

    const newReplacements: WordReplacement[] = results.map((r) => ({
      originalWord: r.originalWord,
      replacementWord: r.replacementWord,
      position: r.position,
      partOfSpeech: r.partOfSpeech,
      phonetic: r.phonetic,
      translation: r.translation,
      reading: r.reading,
    }));

    setReplacements(newReplacements);
    updateWordReplacements(article!.id, newReplacements);
  };

  const isWordReplaceSupported = article ? supportsWordReplacement(article.targetLanguage) : false;

  // ─── View mode options ───────────────────────────────
  const viewModeOptions: { value: ViewMode; icon: React.ReactNode; label: string }[] = [
    { value: 'line-by-line', icon: <Columns2 className="w-3.5 h-3.5" />, label: '行对行' },
    { value: 'side-by-side', icon: <LayoutGrid className="w-3.5 h-3.5" />, label: '并排' },
    { value: 'top-bottom', icon: <LayoutList className="w-3.5 h-3.5" />, label: '上下' },
    { value: 'single-original', icon: <FileText className="w-3.5 h-3.5" />, label: '原文' },
    { value: 'single-translation', icon: <Languages className="w-3.5 h-3.5" />, label: '译文' },
  ];

  // ─── Empty state ─────────────────────────────────────
  if (!article) {
    return (
      <div className="flex items-center justify-center h-full">
        <EmptyState
          icon={<BookOpen className="w-12 h-12" />}
          title="文章不存在"
          description="请返回文章列表选择一篇"
          action={
            <button onClick={() => navigate('/')} className="btn-primary">
              <ArrowLeft className="w-4 h-4" /> 返回首页
            </button>
          }
        />
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col">
      {/* Top Toolbar */}
      <div className="sticky top-0 z-20 bg-[var(--color-bg)] border-b border-gray-200 dark:border-gray-700 px-4 sm:px-6">
        <div className="flex items-center justify-between h-14 max-w-6xl mx-auto">
          {/* Left */}
          <div className="flex items-center gap-3">
            <BackButton variant="icon" fallback="/articles" />
            <div>
              <h1 className="text-sm font-semibold text-gray-800 dark:text-gray-100 truncate max-w-[200px] sm:max-w-[400px]">
                {article.title}
              </h1>
              <span className="text-[11px] text-gray-400">
                {LANGUAGE_NAMES[article.targetLanguage]} · {article.content.length} 字
              </span>
            </div>
          </div>

          {/* Right - Mode toggles */}
          <div className="flex items-center gap-1.5">
            {/* Read mode */}
            <div className="flex bg-gray-100 dark:bg-slate-700 rounded-xl p-0.5">
              <button
                onClick={() => setReadMode('parallel')}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-[10px] text-xs font-medium transition-all',
                  readMode === 'parallel'
                    ? 'bg-white dark:bg-slate-600 text-primary-600 dark:text-primary-400 shadow-sm'
                    : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                )}
              >
                <BookOpen className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">对照</span>
              </button>
              <button
                onClick={() => setReadMode('replace')}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-[10px] text-xs font-medium transition-all',
                  readMode === 'replace'
                    ? 'bg-white dark:bg-slate-600 text-accent-600 dark:text-accent-400 shadow-sm'
                    : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                )}
              >
                <Shuffle className="w-3.5 h-3.5" />
                <span className="hidden sm:inline">换词</span>
              </button>
            </div>

            {/* View mode - only in parallel mode */}
            {readMode === 'parallel' && (
              <div className="hidden sm:flex bg-gray-100 dark:bg-slate-700 rounded-xl p-0.5">
                {viewModeOptions.map((opt) => (
                  <button
                    key={opt.value}
                    onClick={() => setViewMode(opt.value)}
                    className={cn(
                      'flex items-center gap-1 px-2.5 py-1.5 rounded-[10px] text-xs font-medium transition-all',
                      viewMode === opt.value
                        ? 'bg-white dark:bg-slate-600 text-gray-700 dark:text-gray-200 shadow-sm'
                        : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
                    )}
                  >
                    {opt.icon}
                    <span>{opt.label}</span>
                  </button>
                ))}
              </div>
            )}

            {/* Config button for replace mode */}
            {readMode === 'replace' && (
              <button
                onClick={() => setShowConfig(!showConfig)}
                className={cn('btn-ghost !p-2', showConfig && 'bg-primary-50 text-primary-600')}
                title="换词设置"
              >
                <Settings2 className="w-4 h-4" />
              </button>
            )}

            {/* Speak */}
            <button
              onClick={() => {
                speak({ text: article.content.slice(0, 200), lang: 'zh', rate: settings.speechRate });
              }}
              className="btn-ghost !p-2"
              title="朗读"
            >
              <Volume2 className="w-4 h-4" />
            </button>

            {/* Share to public library */}
            <button
              onClick={() => {
                if (isGuest) {
                  setShowLoginPrompt(true);
                  return;
                }
                setShowShare(true);
              }}
              className={cn('btn-ghost !p-2', !article.translation && 'opacity-40 cursor-not-allowed')}
              title={article.translation ? '分享到公共库' : '请先翻译后再分享'}
              disabled={!article.translation}
            >
              <Share2 className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-auto">
        <div className="max-w-6xl mx-auto p-4 sm:p-6 lg:p-8">
          {readMode === 'parallel' ? (
            <TranslationContent
              viewMode={viewMode}
              translationPairs={translationPairs}
              highlightWord={highlightWord}
              isTranslating={isTranslating}
              translationError={translationError}
              noTranslationNeeded={noTranslationNeeded}
              translationProgress={translationProgress}
              translationProgressText={translationProgressText}
              fontSize={fontSize}
              fontFamily={settings.fontFamily}
              lineHeight={settings.lineHeight}
              parallelPosition={settings.parallelPosition}
              verticalPosition={settings.verticalPosition}
              splitRatio={horizontalRatio}
              verticalSplitRatio={verticalRatio}
              highlightedParagraph={highlightedParagraph}
              onTranslate={() => handleTranslate(article)}
              onRetry={() => retryTranslation(article)}
              onCancel={cancelTranslation}
              onOriginalMouseUp={handleOriginalTextSelection}
              onTranslatedMouseUp={handleTranslatedTextSelection}
              onParagraphClick={handleParagraphClick}
              onHorizontalDragStart={startHorizontalDrag}
              onVerticalDragStart={startVerticalDrag}
              containerRef={translationContainerRef}
            />
          ) : (
            /* Word Replace Mode */
            <div className="max-w-3xl mx-auto">
              {/* Language support notice */}
              {!isWordReplaceSupported && (
                <div className="flex items-start gap-3 p-4 mb-4 rounded-xl bg-accent-50 dark:bg-accent-950/30 border border-accent-200 dark:border-accent-800">
                  <Info className="w-5 h-5 text-accent-600 dark:text-accent-400 shrink-0 mt-0.5" />
                  <div>
                    <p className="text-sm font-medium text-accent-800 dark:text-accent-300">
                      当前语种暂不支持单词级混合替换
                    </p>
                    <p className="text-xs text-accent-600 dark:text-accent-400 mt-1">
                      单词级混合显示目前仅支持英语模块。
                      日语、俄语、西班牙语因词形变化复杂，暂时仅提供整句对照翻译。
                      请将目标语种切换为英语以体验混合替换功能。
                    </p>
                  </div>
                </div>
              )}

              {readMode === 'replace' && showConfig && (
                <div className="mb-6 max-w-sm animate-slide-up">
                  <ReplaceConfigPanel
                    articleId={article.id}
                    onApply={(config) => {
                      handleGenerateReplacements(config);
                      setShowConfig(false);
                    }}
                  />
                </div>
              )}

              {/* Replace mode actions */}
              {readMode === 'replace' && !showConfig && (
                <div className="flex items-center gap-2 mb-4 flex-wrap">
                  <button onClick={() => handleGenerateReplacements()} className="btn-primary !py-1.5 !px-3 text-xs">
                    <RefreshCw className="w-3.5 h-3.5" /> 随机换词
                  </button>
                  <button
                    onClick={() => setShowTranslation(!showTranslation)}
                    className={cn('!py-1.5 !px-3 text-xs', showTranslation ? 'btn-secondary' : 'btn-ghost')}
                  >
                    {showTranslation ? <Eye className="w-3.5 h-3.5" /> : <EyeOff className="w-3.5 h-3.5" />}
                    {showTranslation ? '显示释义' : '遮罩模式'}
                  </button>
                  <button
                    onClick={() => {
                      setReplacements([]);
                      updateWordReplacements(article.id, []);
                    }}
                    className="btn-ghost !py-1.5 !px-3 text-xs"
                  >
                    <RotateCcw className="w-3.5 h-3.5" /> 还原原文
                  </button>
                  {replacements.length > 0 && (
                    <span className="text-[11px] text-gray-400 ml-auto">
                      已替换 {replacements.length} 个词语
                    </span>
                  )}
                </div>
              )}

              <div className="card p-5 sm:p-6" style={{ fontSize: `${fontSize}px` }}>
                {renderContent(article.content, replacements.length > 0)}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Word Detail Modal */}
      <WordModal />

      {/* Word Popup - for translated text selection */}
      {selectedWord && article && (
        <WordPopup
          word={selectedWord.word}
          position={selectedWord.position}
          onClose={() => setSelectedWord(null)}
          articleId={articleId || ''}
          sourceSentence={selectedWord.sourceSentence}
          targetLanguage={article.targetLanguage}
        />
      )}

      {/* Share to public library modal */}
      {article && (
        <ShareToPublicModal
          isOpen={showShare}
          onClose={() => setShowShare(false)}
          article={article}
        />
      )}
    </div>
  );
}
