/**
 * 统一的 speechSynthesis 工具
 * 包含错误处理和语种映射
 */

const SPEECH_LANG_MAP: Record<string, string> = {
  zh: 'zh-CN',
  en: 'en-US',
  ja: 'ja-JP',
  ru: 'ru-RU',
  es: 'es-ES',
  ko: 'ko-KR',
  fr: 'fr-FR',
  de: 'de-DE',
  ar: 'ar-SA',
};

interface SpeakOptions {
  text: string;
  lang?: string;
  rate?: number;
  pitch?: number;
  volume?: number;
}

/**
 * 朗读文本（统一入口，自带错误处理）
 */
export function speak(options: SpeakOptions): void {
  if (!('speechSynthesis' in window)) {
    console.warn('[Speech] 当前浏览器不支持语音合成');
    return;
  }

  const { text, lang = 'en', rate = 1, pitch = 1, volume = 1 } = options;

  window.speechSynthesis.cancel();

  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = SPEECH_LANG_MAP[lang] || lang;
  utterance.rate = rate;
  utterance.pitch = pitch;
  utterance.volume = volume;

  // 选择匹配的语音
  const voices = window.speechSynthesis.getVoices();
  const speechLang = SPEECH_LANG_MAP[lang] || lang;
  const matchedVoice =
    voices.find((v) => v.lang.startsWith(speechLang)) ||
    voices.find((v) => v.lang.startsWith(lang));
  if (matchedVoice) {
    utterance.voice = matchedVoice;
  }

  utterance.onerror = (e) => {
    // 'interrupted' and 'canceled' are normal when user clicks another word
    if (e.error !== 'interrupted' && e.error !== 'canceled') {
      console.warn('[Speech] 语音合成错误:', e.error);
    }
  };

  window.speechSynthesis.speak(utterance);
}
