import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { AppSettings } from '@/types';

interface SettingsState {
  settings: AppSettings;
  updateSettings: (data: Partial<AppSettings>) => void;
  toggleTheme: () => void;
}

const defaultSettings: AppSettings = {
  theme: 'light',
  defaultTargetLanguage: 'en',
  fontSize: 16,
  lineHeight: 1.8,
  fontFamily: 'sans',
  autoSync: false,
  speechRate: 1,
  replaceRatio: 0.3,
  replacePosFilter: ['noun', 'verb', 'adjective'],
  replaceDifficulty: 'beginner',
  replaceAvoidDuplicates: true,
  // 阅读布局默认值
  readingLayout: 'line-by-line',
  parallelPosition: 'left-translated',
  verticalPosition: 'top-translated',
  parallelRatio: 0.5,
};

export const useSettingsStore = create<SettingsState>()(
  persist(
    (set) => ({
      settings: defaultSettings,
      updateSettings: (data) =>
        set((state) => ({
          settings: { ...state.settings, ...data },
        })),
      toggleTheme: () =>
        set((state) => ({
          settings: {
            ...state.settings,
            theme: state.settings.theme === 'light' ? 'dark' : 'light',
          },
        })),
    }),
    {
      name: 'bilingual-reader-settings',
      merge: (persisted: unknown, current: SettingsState) => {
        const p = (persisted ?? {}) as Partial<{ settings: Partial<AppSettings> }>;
        return {
          ...current,
          settings: { ...defaultSettings, ...p.settings },
        };
      },
    }
  )
);