import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { Article, Category, ReplaceConfig, WordReplacement } from '@/types';

interface ArticleState {
  articles: Article[];
  categories: Category[];
  currentArticle: Article | null;
  addArticle: (article: Article) => void;
  updateArticle: (id: string, data: Partial<Article>) => void;
  deleteArticle: (id: string) => void;
  setCurrentArticle: (article: Article | null) => void;
  addCategory: (category: Category) => void;
  deleteCategory: (id: string) => void;
  updateReplaceConfig: (articleId: string, config: ReplaceConfig) => void;
  updateWordReplacements: (articleId: string, replacements: WordReplacement[]) => void;
}

export const useArticleStore = create<ArticleState>()(
  persist(
    (set) => ({
      articles: [],
      categories: [
        { id: 'default', name: '默认分类', icon: '📚', articleCount: 0 },
        { id: 'daily', name: '日常阅读', icon: '📖', articleCount: 0 },
        { id: 'exam', name: '考试素材', icon: '📝', articleCount: 0 },
        { id: 'essay', name: '美文', icon: '✨', articleCount: 0 },
        { id: 'work', name: '职场文档', icon: '💼', articleCount: 0 },
      ],
      currentArticle: null,
      addArticle: (article) =>
        set((state) => {
          const updatedCategories = state.categories.map((cat) =>
            cat.id === article.categoryId
              ? { ...cat, articleCount: cat.articleCount + 1 }
              : cat
          );
          return { articles: [article, ...state.articles], categories: updatedCategories };
        }),
      updateArticle: (id, data) =>
        set((state) => ({
          articles: state.articles.map((a) =>
            a.id === id ? { ...a, ...data, updatedAt: Date.now() } : a
          ),
          currentArticle:
            state.currentArticle?.id === id
              ? { ...state.currentArticle, ...data, updatedAt: Date.now() }
              : state.currentArticle,
        })),
      deleteArticle: (id) =>
        set((state) => {
          const article = state.articles.find((a) => a.id === id);
          const updatedCategories = article
            ? state.categories.map((cat) =>
                cat.id === article.categoryId
                  ? { ...cat, articleCount: Math.max(0, cat.articleCount - 1) }
                  : cat
              )
            : state.categories;
          return {
            articles: state.articles.filter((a) => a.id !== id),
            categories: updatedCategories,
            currentArticle:
              state.currentArticle?.id === id ? null : state.currentArticle,
          };
        }),
      setCurrentArticle: (article) => set({ currentArticle: article }),
      addCategory: (category) =>
        set((state) => ({ categories: [...state.categories, category] })),
      deleteCategory: (id) => {
        if (id === 'default') return;
        set((state) => ({
          categories: state.categories.filter((c) => c.id !== id),
          articles: state.articles.map((a) =>
            a.categoryId === id ? { ...a, categoryId: 'default' } : a
          ),
        }));
      },
      updateReplaceConfig: (articleId, config) =>
        set((state) => ({
          articles: state.articles.map((a) =>
            a.id === articleId ? { ...a, replaceConfig: config, updatedAt: Date.now() } : a
          ),
          currentArticle:
            state.currentArticle?.id === articleId
              ? { ...state.currentArticle, replaceConfig: config, updatedAt: Date.now() }
              : state.currentArticle,
        })),
      updateWordReplacements: (articleId, replacements) =>
        set((state) => ({
          articles: state.articles.map((a) =>
            a.id === articleId ? { ...a, wordReplacements: replacements, updatedAt: Date.now() } : a
          ),
          currentArticle:
            state.currentArticle?.id === articleId
              ? { ...state.currentArticle, wordReplacements: replacements, updatedAt: Date.now() }
              : state.currentArticle,
        })),
    }),
    { name: 'bilingual-reader-articles' }
  )
);