import { useState } from 'react';
import { Check } from 'lucide-react';
import type { KanaEntry } from '@/data/jaKana';
import { KANA_ROWS, KANA_COLUMNS } from '@/data/jaKana';
import { speak } from '@/lib/speech';
import { useBasicsStore } from '@/stores/basicsStore';
import { cn } from '@/lib/utils';

interface KanaGridProps {
  kana: KanaEntry[];
}

export default function KanaGrid({ kana }: KanaGridProps) {
  const [mode, setMode] = useState<'hiragana' | 'katakana'>('hiragana');
  const { isKanaLearned, toggleKanaLearned } = useBasicsStore();

  // 建立查找表：row + column → KanaEntry
  const lookup = new Map<string, KanaEntry>();
  kana.forEach((k) => {
    if (k.type === 'clear' || k.type === 'special') {
      lookup.set(`${k.row}|${k.column}`, k);
    }
  });

  const handlePlay = (entry: KanaEntry) => {
    speak({ text: entry.hiragana, lang: 'ja' });
  };

  const handleClick = (entry: KanaEntry) => {
    handlePlay(entry);
  };

  const handleToggle = (entry: KanaEntry) => {
    toggleKanaLearned(entry.hiragana);
  };

  return (
    <div>
      {/* 模式切换 */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex bg-gray-100 dark:bg-slate-700 rounded-xl p-0.5">
          <button
            onClick={() => setMode('hiragana')}
            className={cn(
              'px-3 py-1.5 rounded-[10px] text-xs font-medium transition-all',
              mode === 'hiragana'
                ? 'bg-white dark:bg-slate-600 text-primary-600 dark:text-primary-400 shadow-sm'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
            )}
          >
            平假名
          </button>
          <button
            onClick={() => setMode('katakana')}
            className={cn(
              'px-3 py-1.5 rounded-[10px] text-xs font-medium transition-all',
              mode === 'katakana'
                ? 'bg-white dark:bg-slate-600 text-primary-600 dark:text-primary-400 shadow-sm'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700'
            )}
          >
            片假名
          </button>
        </div>
        <span className="text-xs text-gray-400">点击朗读 · 右键标记已学</span>
      </div>

      {/* 五十音图网格：行标 + 5 列 */}
      <div className="overflow-x-auto">
        <div className="min-w-[420px]">
          {/* 表头：段标 */}
          <div className="grid grid-cols-6 gap-1.5 mb-1.5">
            <div />
            {KANA_COLUMNS.map((col) => (
              <div key={col} className="text-center text-xs font-medium text-gray-400 py-1">
                {col}段
              </div>
            ))}
          </div>

          {/* 各行 */}
          {KANA_ROWS.map((row) => (
            <div key={row} className="grid grid-cols-6 gap-1.5 mb-1.5">
              {/* 行标 */}
              <div className="flex items-center justify-center text-xs font-medium text-gray-400">
                {row}行
              </div>
              {/* 5 段 */}
              {KANA_COLUMNS.map((col) => {
                const entry = lookup.get(`${row}|${col}`);
                if (!entry) {
                  // 空位（や行/わ行的空缺）
                  return <div key={col} className="aspect-square rounded-xl bg-gray-50 dark:bg-slate-800/40" />;
                }
                const learned = isKanaLearned(entry.hiragana);
                const primary = mode === 'hiragana' ? entry.hiragana : entry.katakana;
                const secondary = mode === 'hiragana' ? entry.katakana : entry.hiragana;
                return (
                  <button
                    key={col}
                    onClick={() => handleClick(entry)}
                    onContextMenu={(e) => {
                      e.preventDefault();
                      handleToggle(entry);
                    }}
                    className={cn(
                      'relative aspect-square rounded-xl flex flex-col items-center justify-center transition-all duration-200 border',
                      learned
                        ? 'bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-950/40 dark:to-teal-950/40 border-emerald-300 dark:border-emerald-700'
                        : 'bg-white dark:bg-slate-800 border-gray-100 dark:border-slate-700 hover:border-primary-300 dark:hover:border-primary-600 hover:shadow-sm hover:-translate-y-0.5'
                    )}
                    title={`${entry.hiragana} / ${entry.katakana} (${entry.romaji})`}
                  >
                    {learned && (
                      <span className="absolute top-1 right-1 w-3.5 h-3.5 rounded-full bg-emerald-500 text-white flex items-center justify-center">
                        <Check className="w-2 h-2" />
                      </span>
                    )}
                    <span className="text-xl sm:text-2xl font-bold text-gray-800 dark:text-gray-100 leading-none">
                      {primary}
                    </span>
                    <span className="absolute top-1 left-1 text-[10px] text-gray-400 dark:text-gray-500">
                      {secondary}
                    </span>
                    <span className="text-[9px] text-gray-400 dark:text-gray-500 mt-0.5">
                      {entry.romaji}
                    </span>
                  </button>
                );
              })}
            </div>
          ))}

          {/* 拨音 ん 单独行 */}
          {(() => {
            const nEntry = kana.find((k) => k.type === 'special');
            if (!nEntry) return null;
            const learned = isKanaLearned(nEntry.hiragana);
            const primary = mode === 'hiragana' ? nEntry.hiragana : nEntry.katakana;
            const secondary = mode === 'hiragana' ? nEntry.katakana : nEntry.hiragana;
            return (
              <div className="grid grid-cols-6 gap-1.5">
                <div className="flex items-center justify-center text-xs font-medium text-gray-400">
                  拨音
                </div>
                <button
                  onClick={() => handleClick(nEntry)}
                  onContextMenu={(e) => {
                    e.preventDefault();
                    handleToggle(nEntry);
                  }}
                  className={cn(
                    'col-span-5 relative rounded-xl py-2 flex items-center justify-center gap-3 transition-all border',
                    learned
                      ? 'bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-950/40 dark:to-teal-950/40 border-emerald-300 dark:border-emerald-700'
                      : 'bg-white dark:bg-slate-800 border-gray-100 dark:border-slate-700 hover:border-primary-300 dark:hover:border-primary-600 hover:shadow-sm'
                  )}
                  title={`${nEntry.hiragana} / ${nEntry.katakana} (${nEntry.romaji})`}
                >
                  {learned && (
                    <span className="absolute top-1 right-1 w-3.5 h-3.5 rounded-full bg-emerald-500 text-white flex items-center justify-center">
                      <Check className="w-2 h-2" />
                    </span>
                  )}
                  <span className="text-2xl font-bold text-gray-800 dark:text-gray-100">{primary}</span>
                  <span className="text-xs text-gray-400 dark:text-gray-500">{secondary}</span>
                  <span className="text-[10px] text-gray-400 dark:text-gray-500">({nEntry.romaji})</span>
                </button>
              </div>
            );
          })()}
        </div>
      </div>
    </div>
  );
}
