import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Library, Search, Grid3X3, List, Eye } from 'lucide-react';
import { usePublicArticleStore } from '@/stores/publicArticleStore';
import { useUIStore } from '@/stores/uiStore';
import { useAuthStore } from '@/stores/authStore';
import ArticleCard from '@/components/ArticleCard';
import EmptyState from '@/components/EmptyState';
import BackButton from '@/components/BackButton';
import type { Article, PublicArticle, Language } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import { cn } from '@/lib/utils';

/** 将 PublicArticle 转为 ArticleCard 兼容的 Article 格式（时间戳转换） */
function toArticleLike(p: PublicArticle): Article {
  return {
    id: p.id,
    title: p.title,
    content: p.content,
    translation: p.translation,
    sourceLanguage: p.sourceLanguage,
    targetLanguage: p.targetLanguage,
    categoryId: p.categoryId || 'default',
    createdAt: new Date(p.createdAt).getTime(),
    updatedAt: new Date(p.updatedAt).getTime(),
    tags: p.tags,
  };
}

export default function PublicLibraryPage() {
  const navigate = useNavigate();
  const { articles, total, loading, categories, fetchArticles, fetchCategories } = usePublicArticleStore();
  const { setSelectedLanguage, setShowLoginPrompt } = useUIStore();
  const isGuest = useAuthStore((s) => s.isGuest);
  const [activeCategory, setActiveCategory] = useState('all');
  const [activeLanguage, setActiveLanguage] = useState<Language | 'all'>('all');
  const [keyword, setKeyword] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  useEffect(() => {
    fetchCategories();
  }, [fetchCategories]);

  const loadArticles = useCallback(() => {
    fetchArticles({
      page: 1,
      pageSize: 50,
      keyword: keyword || undefined,
      categoryId: activeCategory !== 'all' ? activeCategory : undefined,
      targetLanguage: activeLanguage !== 'all' ? activeLanguage : undefined,
    });
  }, [fetchArticles, keyword, activeCategory, activeLanguage]);

  useEffect(() => {
    loadArticles();
  }, [loadArticles]);

  const languages = Object.entries(LANGUAGE_NAMES).slice(0, 5) as [Language, string][];

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
      <BackButton />

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
        <div>
          <h1 className="text-xl font-bold text-gray-800 dark:text-gray-100 flex items-center gap-2">
            <Library className="w-5 h-5 text-primary-500" />
            公共文章库
          </h1>
          <p className="text-sm text-gray-500 mt-0.5">
            所有文章均已翻译完成，免费查阅 · 共 {total} 篇
          </p>
        </div>
      </div>

      {/* Search */}
      <div className="relative mb-5">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
        <input
          type="text"
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && loadArticles()}
          placeholder="搜索文章标题..."
          className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-gray-50 dark:bg-slate-800 border border-gray-200 dark:border-gray-700 text-sm text-gray-700 dark:text-gray-200 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary-300 dark:focus:ring-primary-700"
        />
      </div>

      {/* Language Filter */}
      <div className="flex items-center gap-2 mb-4 overflow-x-auto pb-1 scrollbar-thin">
        <button
          onClick={() => setActiveLanguage('all')}
          className={cn(
            'px-3.5 py-1.5 rounded-xl text-xs font-medium whitespace-nowrap transition-all',
            activeLanguage === 'all'
              ? 'bg-primary-500 text-white shadow-sm'
              : 'bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
          )}
        >
          全部语种
        </button>
        {languages.map(([key, name]) => (
          <button
            key={key}
            onClick={() => setActiveLanguage(key)}
            className={cn(
              'px-3.5 py-1.5 rounded-xl text-xs font-medium whitespace-nowrap transition-all',
              activeLanguage === key
                ? 'bg-primary-500 text-white shadow-sm'
                : 'bg-gray-100 dark:bg-slate-700 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-slate-600'
            )}
          >
            {name}
          </button>
        ))}
      </div>

      {/* Category Filter */}
      {categories.length > 0 && (
        <div className="flex items-center gap-2 mb-5 overflow-x-auto pb-1 scrollbar-thin">
          <button
            onClick={() => setActiveCategory('all')}
            className={cn(
              'px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all',
              activeCategory === 'all'
                ? 'bg-accent-100 dark:bg-accent-900 text-accent-700 dark:text-accent-300'
                : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
            )}
          >
            全部分类
          </button>
          {categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              className={cn(
                'px-3 py-1.5 rounded-lg text-xs font-medium whitespace-nowrap transition-all',
                activeCategory === cat.id
                  ? 'bg-accent-100 dark:bg-accent-900 text-accent-700 dark:text-accent-300'
                  : 'text-gray-500 hover:text-gray-700 dark:text-gray-400'
              )}
            >
              {cat.icon} {cat.name}
            </button>
          ))}
        </div>
      )}

      {/* View mode toggle */}
      {articles.length > 0 && (
        <div className="flex items-center justify-end mb-3">
          <div className="flex items-center bg-gray-100 dark:bg-slate-700 rounded-lg p-0.5">
            <button
              onClick={() => setViewMode('grid')}
              className={cn(
                'p-1.5 rounded-md transition-colors',
                viewMode === 'grid'
                  ? 'bg-white dark:bg-slate-600 shadow-sm text-primary-600'
                  : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'
              )}
            >
              <Grid3X3 className="w-4 h-4" />
            </button>
            <button
              onClick={() => setViewMode('list')}
              className={cn(
                'p-1.5 rounded-md transition-colors',
                viewMode === 'list'
                  ? 'bg-white dark:bg-slate-600 shadow-sm text-primary-600'
                  : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-300'
              )}
            >
              <List className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* Content */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <div className="text-sm text-gray-400">加载中...</div>
        </div>
      ) : articles.length > 0 ? (
        viewMode === 'grid' ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
            {articles.map((pa) => (
              <div key={pa.id} className="relative group">
                <ArticleCard
                  article={toArticleLike(pa)}
                  variant="grid"
                  onClick={() => {
                    if (isGuest) {
                      setShowLoginPrompt(true);
                      return;
                    }
                    setSelectedLanguage(pa.targetLanguage);
                    navigate(`/library/${pa.id}`);
                  }}
                />
                <div className="absolute top-2 right-2 flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-black/30 text-white text-[10px] opacity-0 group-hover:opacity-100 transition-opacity">
                  <Eye className="w-3 h-3" />
                  {pa.viewCount}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="space-y-2">
            {articles.map((pa) => (
              <div key={pa.id} className="relative group">
                <ArticleCard
                  article={toArticleLike(pa)}
                  variant="list"
                  onClick={() => {
                    if (isGuest) {
                      setShowLoginPrompt(true);
                      return;
                    }
                    setSelectedLanguage(pa.targetLanguage);
                    navigate(`/library/${pa.id}`);
                  }}
                />
                <div className="absolute top-3 right-10 flex items-center gap-1 px-2 py-0.5 rounded-md bg-gray-100 dark:bg-slate-700 text-gray-500 text-[10px] opacity-0 group-hover:opacity-100 transition-opacity">
                  <Eye className="w-3 h-3" />
                  {pa.viewCount}
                </div>
              </div>
            ))}
          </div>
        )
      ) : (
        <EmptyState
          icon={<Library className="w-12 h-12" />}
          title="公共文章库暂无文章"
          description="管理员上传的文章和用户分享的译文将出现在这里"
        />
      )}
    </div>
  );
}
