/**
 * 文件解析工具 - 支持 TXT / DOCX / PDF 纯文本提取
 */

export type ParsedFile = {
  title: string;
  content: string;
  fileType: 'txt' | 'docx' | 'pdf' | 'unknown';
};

/**
 * 读取 .txt 文件
 */
async function parseTxt(file: File): Promise<string> {
  return await file.text();
}

/**
 * 读取 .docx 文件（使用 mammoth 库）
 */
async function parseDocx(file: File): Promise<string> {
  const mammoth = (await import('mammoth')).default;
  const arrayBuffer = await file.arrayBuffer();
  const result = await mammoth.extractRawText({ arrayBuffer });
  return result.value;
}

/**
 * 读取 .pdf 文件（使用 pdfjs-dist）
 */
async function parsePdf(file: File): Promise<string> {
  const pdfjsLib = await import('pdfjs-dist');
  // 设置 worker 源（使用 CDN 版本）
  pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;

  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  const texts: string[] = [];

  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const textContent = await page.getTextContent();
    const pageText = textContent.items
      .map((item) => ('str' in item ? item.str : ''))
      .join(' ');
    texts.push(pageText);
  }

  return texts.join('\n\n');
}

/**
 * 解析上传的文件，返回标题和纯文本内容
 */
export async function parseFile(file: File): Promise<ParsedFile> {
  const ext = file.name.split('.').pop()?.toLowerCase() || '';
  const title = file.name.replace(/\.[^/.]+$/, '');

  let content = '';
  let fileType: ParsedFile['fileType'] = 'unknown';

  switch (ext) {
    case 'txt':
      content = await parseTxt(file);
      fileType = 'txt';
      break;
    case 'docx':
      content = await parseDocx(file);
      fileType = 'docx';
      break;
    case 'pdf':
      content = await parsePdf(file);
      fileType = 'pdf';
      break;
    default:
      content = await file.text();
      break;
  }

  return { title, content: content.trim(), fileType };
}

/**
 * 校验文件是否支持
 */
export const SUPPORTED_EXTENSIONS = ['.txt', '.docx', '.pdf'];

export function isSupportedFile(file: File): boolean {
  const ext = '.' + file.name.split('.').pop()?.toLowerCase();
  return SUPPORTED_EXTENSIONS.includes(ext);
}
