import { create } from 'zustand';
import {
  getToken,
  setToken,
  getDeviceId,
  setDeviceId,
  getLearnerId,
  setLearnerId,
  uuid,
} from '@/api/client';
import { registerDevice } from '@/api/learner';
import {
  addAccount,
  verifyAccount,
  getCurrentUser,
  setCurrentUser,
  clearCurrentUser,
} from '@/lib/auth';

interface CurrentUser {
  username: string;
}

interface AuthState {
  deviceId: string | null;
  learnerId: string | null;
  token: string | null;
  /** 当前登录用户（null=游客） */
  user: CurrentUser | null;
  /** 是否游客模式 */
  isGuest: boolean;
  /** 是否已完成启动初始化 */
  ready: boolean;
  /** 启动时调用：检查登录状态，已登录则注册设备获取 token */
  bootstrap: () => Promise<void>;
  /** 登录（本地验证） */
  login: (username: string, password: string) => Promise<{ ok: boolean; error?: string }>;
  /** 注册（本地存储） */
  register: (username: string, password: string) => Promise<{ ok: boolean; error?: string }>;
  /** 退出登录 */
  logout: () => void;
}

export const useAuthStore = create<AuthState>((set) => ({
  deviceId: getDeviceId(),
  learnerId: getLearnerId(),
  token: getToken(),
  user: getCurrentUser(),
  isGuest: !getCurrentUser(),
  ready: false,

  bootstrap: async () => {
    const currentUser = getCurrentUser();

    if (!currentUser) {
      // 游客模式：不调后端 API
      set({ isGuest: true, user: null, ready: true });
      return;
    }

    // 已登录用户：执行设备注册获取 token
    let deviceId = getDeviceId();
    let token = getToken();

    if (deviceId && token) {
      set({
        deviceId,
        learnerId: getLearnerId(),
        token,
        user: currentUser,
        isGuest: false,
        ready: true,
      });
      return;
    }

    if (!deviceId) {
      deviceId = uuid();
      setDeviceId(deviceId);
    }

    try {
      const res = await registerDevice(deviceId);
      setToken(res.token);
      setLearnerId(res.learnerId);
      set({
        deviceId,
        learnerId: res.learnerId,
        token: res.token,
        user: currentUser,
        isGuest: false,
        ready: true,
      });
    } catch (e) {
      console.error('设备注册失败:', e);
      set({ deviceId, user: currentUser, isGuest: false, ready: true });
    }
  },

  login: async (username: string, password: string) => {
    // 模拟网络延迟
    await new Promise((r) => setTimeout(r, 500));

    const result = verifyAccount(username, password);
    if (!result.ok) {
      return result;
    }

    // 本地验证成功 → 设置当前用户
    setCurrentUser(username);

    // 执行设备注册获取 token
    let deviceId = getDeviceId();
    if (!deviceId) {
      deviceId = uuid();
      setDeviceId(deviceId);
    }

    try {
      const res = await registerDevice(deviceId);
      setToken(res.token);
      setLearnerId(res.learnerId);
      set({
        deviceId,
        learnerId: res.learnerId,
        token: res.token,
        user: { username },
        isGuest: false,
      });
    } catch (e) {
      // 设备注册失败仍标记为已登录（后续 401 会重试）
      console.error('设备注册失败:', e);
      set({ deviceId, user: { username }, isGuest: false });
    }

    return { ok: true };
  },

  register: async (username: string, password: string) => {
    // 模拟网络延迟
    await new Promise((r) => setTimeout(r, 500));

    const result = addAccount(username, password);
    if (!result.ok) {
      return result;
    }

    // 注册成功 → 自动登录
    setCurrentUser(username);

    let deviceId = getDeviceId();
    if (!deviceId) {
      deviceId = uuid();
      setDeviceId(deviceId);
    }

    try {
      const res = await registerDevice(deviceId);
      setToken(res.token);
      setLearnerId(res.learnerId);
      set({
        deviceId,
        learnerId: res.learnerId,
        token: res.token,
        user: { username },
        isGuest: false,
      });
    } catch (e) {
      console.error('设备注册失败:', e);
      set({ deviceId, user: { username }, isGuest: false });
    }

    return { ok: true };
  },

  logout: () => {
    clearCurrentUser();
    set({
      user: null,
      isGuest: true,
      token: null,
      learnerId: null,
    });
  },
}));

/**
 * 401 时强制重新注册设备（token 过期或无效）。
 * 供 API client 响应拦截调用。
 */
export async function reauthDevice(): Promise<string | null> {
  const currentUser = getCurrentUser();
  if (!currentUser) {
    // 游客模式下 401 不自动重试
    return null;
  }

  const deviceId = getDeviceId() ?? uuid();
  setDeviceId(deviceId);
  try {
    const res = await registerDevice(deviceId);
    setToken(res.token);
    setLearnerId(res.learnerId);
    useAuthStore.setState({
      deviceId,
      learnerId: res.learnerId,
      token: res.token,
      user: currentUser,
      isGuest: false,
    });
    return res.token;
  } catch (e) {
    console.error('重新注册设备失败:', e);
    return null;
  }
}
