/**
 * 英语 48 个国际音标（IPA）数据
 * 分为元音（20 个：短元音/长元音/双元音）和辅音（28 个：爆破/摩擦/破擦/鼻音/舌侧/半元音）。
 * 用于基础学习模块的音标表格展示与示例词朗读。
 */

export interface PhoneticEntry {
  /** IPA 符号，如 /ɪ/ */
  ipa: string;
  /** 分类：vowel_short | vowel_long | diphthong | consonant_stop | consonant_fricative | consonant_affricate | consonant_nasal | consonant_lateral | consonant_semivowel */
  category: string;
  /** 示例单词列表 */
  examples: string[];
  /** 中文说明（如"短元音，嘴半开"） */
  description: string;
  /** 容易混淆的音标 */
  similarTo?: string;
}

/** 分类显示名称 */
export const PHONETIC_CATEGORY_LABELS: Record<string, string> = {
  vowel_short: '短元音',
  vowel_long: '长元音',
  diphthong: '双元音',
  consonant_stop: '爆破音',
  consonant_fricative: '摩擦音',
  consonant_affricate: '破擦音',
  consonant_nasal: '鼻音',
  consonant_lateral: '舌侧音',
  consonant_semivowel: '半元音',
};

/** 分类显示顺序 */
export const PHONETIC_CATEGORY_ORDER: string[] = [
  'vowel_short',
  'vowel_long',
  'diphthong',
  'consonant_stop',
  'consonant_fricative',
  'consonant_affricate',
  'consonant_nasal',
  'consonant_lateral',
  'consonant_semivowel',
];

