import { useMemo } from 'react';
import { Link } from 'react-router-dom';
import {
  TrendingUp,
  BookOpen,
  BookMarked,
  Flame,
  Calendar,
  ArrowRight,
} from 'lucide-react';
import { useArticleStore } from '@/stores/articleStore';
import { useVocabularyStore } from '@/stores/vocabularyStore';
import { useCheckInStore } from '@/stores/checkInStore';
import { calcAllStats, calcActiveDays } from '@/lib/stats';
import { cn } from '@/lib/utils';

/**
 * 首页极简版学习数据
 * 只展示 4 个核心数字 + 最近 7 天迷你热力图 + 「查看详情」入口
 */
export default function StatsSummary() {
  const articles = useArticleStore((s) => s.articles);
  const words = useVocabularyStore((s) => s.words);
  const checkInDays = useCheckInStore((s) => s.checkInDays);

  const stats = useMemo(
    () => calcAllStats(articles, words, checkInDays),
    [articles, words, checkInDays]
  );
  const activeDays = useMemo(
    () => calcActiveDays(words, checkInDays),
    [words, checkInDays]
  );

  const overviewItems = [
    { icon: BookOpen, label: '文章', value: stats.article.total, color: 'text-primary-500' },
    { icon: BookMarked, label: '生词', value: stats.vocab.total, color: 'text-accent-500' },
    { icon: Flame, label: '打卡', value: stats.checkIn.totalDays, color: 'text-orange-500' },
    { icon: Calendar, label: '活跃', value: activeDays, color: 'text-blue-500' },
  ];

  // 智能鼓励文案（极简版）
  const tip = (() => {
    if (stats.checkIn.currentStreak >= 7)
      return `🔥 已连续 ${stats.checkIn.currentStreak} 天，再接再厉！`;
    if (stats.vocab.dueCount > 0)
      return `📚 ${stats.vocab.dueCount} 个生词待复习`;
    if (stats.vocab.total === 0) return '💡 点击文章中的单词即可加入生词本';
    if (stats.checkIn.currentStreak === 0) return '✨ 今日还未打卡';
    return '🌟 每天进步一点点';
  })();

  return (
    <div className="card p-4 sm:p-5 rounded-2xl">
      {/* 头部：标题 + 详情入口 */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <div className="w-7 h-7 rounded-lg bg-gradient-to-br from-primary-400 to-accent-400 flex items-center justify-center text-white">
            <TrendingUp className="w-3.5 h-3.5" />
          </div>
          <h2 className="text-sm font-semibold text-gray-800 dark:text-gray-100">
            学习数据
          </h2>
        </div>
        <Link
          to="/stats"
          className="text-[11px] text-primary-600 dark:text-primary-400 hover:underline flex items-center gap-0.5"
        >
          查看详情 <ArrowRight className="w-3 h-3" />
        </Link>
      </div>

      {/* 四宫格 */}
      <div className="grid grid-cols-4 gap-2 mb-3">
        {overviewItems.map((item) => (
          <div
            key={item.label}
            className="px-1 py-2 rounded-lg bg-gray-50 dark:bg-slate-800/60 text-center"
          >
            <item.icon className={cn('w-3.5 h-3.5 mx-auto mb-0.5', item.color)} />
            <div className="text-base font-bold tabular-nums text-gray-800 dark:text-gray-100 leading-tight">
              {item.value}
            </div>
            <div className="text-[10px] text-gray-500 leading-tight">{item.label}</div>
          </div>
        ))}
      </div>

      {/* 智能提示 */}
      <div className="mt-2.5 text-center">
        <p className="text-[11px] text-gray-500 dark:text-gray-400">{tip}</p>
      </div>
    </div>
  );
}
