/**
 * 学习打卡工具
 *
 * 概念：
 * - "今日"以本地时区为准（避免跨时区判定错误）
 * - 一天内多次学习只算 1 次打卡
 * - 连胜：连续 N 天打卡；中断则归零
 * - 今日已打卡时不再触发新打卡
 */

/** 本地时区的 YYYY-MM-DD（用于作为 key） */
export function toDateKey(timestamp: number = Date.now()): string {
  const d = new Date(timestamp);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/** 计算两个日期之间相差的天数（按本地时区，"今天" 减 "那天"） */
export function daysBetween(later: number, earlier: number): number {
  const d1 = new Date(later);
  d1.setHours(0, 0, 0, 0);
  const d2 = new Date(earlier);
  d2.setHours(0, 0, 0, 0);
  return Math.round((d1.getTime() - d2.getTime()) / (24 * 60 * 60 * 1000));
}

/** 获取最近 N 天的日期 keys（含今天），按从旧到新排序 */
export function getRecentDateKeys(n: number, endTimestamp: number = Date.now()): string[] {
  const result: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    result.push(toDateKey(endTimestamp - i * 24 * 60 * 60 * 1000));
  }
  return result;
}

/**
 * 计算当前连胜天数
 * 规则：从今天往前连续算，遇到断签则停止
 * 若今天没打卡但昨天打卡，按"昨天为锚点"计算（防止"今天没打卡就连胜清零"造成的负反馈）
 */
export function calcStreak(checkInDays: Record<string, boolean>, now: number = Date.now()): number {
  const todayKey = toDateKey(now);
  const yesterdayKey = toDateKey(now - 24 * 60 * 60 * 1000);

  // 起点：今天 > 昨天
  let cursor: number;
  if (checkInDays[todayKey]) {
    cursor = now;
  } else if (checkInDays[yesterdayKey]) {
    // 昨天打了但今天还没打：连胜仍在（只是即将归零）
    cursor = now - 24 * 60 * 60 * 1000;
  } else {
    return 0;
  }

  let streak = 0;
  while (true) {
    const key = toDateKey(cursor);
    if (checkInDays[key]) {
      streak++;
      cursor -= 24 * 60 * 60 * 1000;
    } else {
      break;
    }
  }
  return streak;
}

/** 总打卡天数 */
export function calcTotalDays(checkInDays: Record<string, boolean>): number {
  return Object.values(checkInDays).filter(Boolean).length;
}

/** 友好显示日期 */
export function formatDateLabel(dateKey: string): { weekday: string; day: string } {
  const d = new Date(dateKey);
  const weekdays = ['日', '一', '二', '三', '四', '五', '六'];
  return {
    weekday: `周${weekdays[d.getDay()]}`,
    day: `${d.getMonth() + 1}/${d.getDate()}`,
  };
}

/** 距离今天 N 天前的日期 key */
export function dateKeyDaysAgo(days: number, now: number = Date.now()): string {
  return toDateKey(now - days * 24 * 60 * 60 * 1000);
}
