import { Volume2, Check } from 'lucide-react';
import type { AlphabetEntry } from '@/data/enAlphabet';
import { speak } from '@/lib/speech';
import { useBasicsStore } from '@/stores/basicsStore';
import { cn } from '@/lib/utils';

interface AlphabetGridProps {
  letters: AlphabetEntry[];
}

export default function AlphabetGrid({ letters }: AlphabetGridProps) {
  const { isLetterLearned, toggleLetterLearned } = useBasicsStore();

  const handlePlay = (letter: AlphabetEntry) => {
    // 朗读字母名称（用大写字母 + 示例词各播一次更直观）
    speak({ text: `${letter.upper}. ${letter.soundExample}`, lang: 'en' });
  };

  const handleToggle = (letter: AlphabetEntry) => {
    toggleLetterLearned(letter.upper);
  };

  return (
    <div className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-7 gap-2.5">
      {letters.map((letter) => {
        const learned = isLetterLearned(letter.upper);
        return (
          <button
            key={letter.upper}
            onClick={() => handlePlay(letter)}
            onContextMenu={(e) => {
              e.preventDefault();
              handleToggle(letter);
            }}
            className={cn(
              'relative group rounded-2xl p-3 sm:p-4 text-left transition-all duration-200 border',
              learned
                ? 'bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-950/40 dark:to-teal-950/40 border-emerald-300 dark:border-emerald-700'
                : 'bg-gradient-to-br from-blue-50 to-indigo-50 dark:from-slate-800 dark:to-slate-700/60 border-transparent hover:border-primary-300 dark:hover:border-primary-600 hover:shadow-md hover:-translate-y-0.5'
            )}
            title={`${letter.upper} - ${letter.exampleWord}（右键标记已学）`}
          >
            {/* 已学标记 */}
            {learned && (
              <span className="absolute top-1.5 right-1.5 w-4 h-4 rounded-full bg-emerald-500 text-white flex items-center justify-center">
                <Check className="w-2.5 h-2.5" />
              </span>
            )}

            {/* 大写字母 */}
            <div className="text-2xl sm:text-3xl font-bold text-gray-800 dark:text-gray-100 leading-none">
              {letter.upper}
            </div>

            {/* 小写 + 名称音标 */}
            <div className="mt-1.5 flex items-center justify-between">
              <span className="text-sm font-medium text-gray-500 dark:text-gray-400">
                {letter.lower}
              </span>
              <span className="text-[10px] text-primary-500 dark:text-primary-400 font-mono">
                {letter.namePron}
              </span>
            </div>

            {/* 示例词 */}
            <div className="mt-1 text-[10px] text-gray-400 dark:text-gray-500 truncate">
              {letter.soundExample}
            </div>

            {/* 播放图标（hover 显示） */}
            <Volume2 className="absolute bottom-1.5 right-1.5 w-3 h-3 text-gray-300 dark:text-gray-600 opacity-0 group-hover:opacity-100 transition-opacity" />
          </button>
        );
      })}
    </div>
  );
}
