import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft } from 'lucide-react';
import { cn } from '@/lib/utils';

export type BackButtonVariant = 'text' | 'icon';

interface BackButtonProps {
  /**
   * 无历史栈时回退到的目标路由。默认 '/'。
   */
  fallback?: string;
  /**
   * 视觉变体：
   *   - 'text'（默认）：图标 + "返回" 文本，适合普通页面顶部
   *   - 'icon'        ：仅图标按钮，适合工具栏 / 紧凑场景
   */
  variant?: BackButtonVariant;
  /** 自定义文本，仅在 text 变体下生效 */
  label?: string;
  /** 自定义样式 */
  className?: string;
  /** 标题属性 */
  title?: string;
}

/**
 * 全局返回按钮。
 * - 有历史栈时：navigate(-1) 返回上一个访问页面
 * - 无历史栈时（直接打开 / 新标签）：跳转 fallback（默认首页）
 * 不在首页（pathname === '/'）上渲染——首页是入口，不应有"返回"。
 */
export default function BackButton({
  fallback = '/',
  variant = 'text',
  label = '返回',
  className,
  title = '返回上一页',
}: BackButtonProps) {
  const navigate = useNavigate();
  const location = useLocation();

  // React Router 用 location.key === 'default' 标识"直接进入"（无应用内历史）
  const hasHistory = location.key !== 'default';

  const handleClick = () => {
    if (hasHistory) {
      navigate(-1);
    } else {
      navigate(fallback);
    }
  };

  if (variant === 'icon') {
    return (
      <button
        type="button"
        onClick={handleClick}
        title={title}
        aria-label={title}
        className={cn(
          'btn-ghost !p-2',
          className
        )}
      >
        <ArrowLeft className="w-4 h-4" />
      </button>
    );
  }

  return (
    <button
      type="button"
      onClick={handleClick}
      title={title}
      className={cn(
        'inline-flex items-center gap-1 text-sm text-gray-500 dark:text-gray-400 hover:text-primary-600 dark:hover:text-primary-400 mb-4 transition-colors group',
        className
      )}
    >
      <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-0.5" />
      <span>{label}</span>
    </button>
  );
}
