import { useState, useMemo, useEffect } from 'react';
import {
  BookMarked,
  Volume2,
  Trash2,
  ChevronRight,
  ArrowLeft,
  Sparkles,
  Clock,
  CheckCircle2,
  Headphones,
} from 'lucide-react';
import { useVocabularyStore } from '@/stores/vocabularyStore';
import { useSettingsStore } from '@/stores/settingsStore';
import { useCheckInStore } from '@/stores/checkInStore';
import EmptyState from '@/components/EmptyState';
import DictationMode from '@/components/DictationMode';
import BackButton from '@/components/BackButton';
import { cn } from '@/lib/utils';
import { speak } from '@/lib/speech';
import { toKatakana } from '@/lib/jaFurigana';
import { LANGUAGE_NAMES, DIFFICULTY_NAMES, type Language, type Difficulty, type ReviewRating, type VocabularyWord } from '@/types';
import { REVIEW_RATINGS, formatTimeUntil, isDue } from '@/lib/ebbinghaus';

type ReviewMode = 'list' | 'flashcard';
type ViewMode = 'vocabulary' | 'dictation';

export default function VocabularyPage() {
  const { words, removeWord, recordReview } = useVocabularyStore();
  const { settings } = useSettingsStore();
  const checkIn = useCheckInStore((s) => s.checkIn);
  const [languageFilter, setLanguageFilter] = useState<Language | 'all'>('all');
  const [difficultyFilter, setDifficultyFilter] = useState<Difficulty | 'all'>('all');
  const [reviewMode, setReviewMode] = useState<ReviewMode>('list');
  const [viewMode, setViewMode] = useState<ViewMode>('vocabulary');
  const [currentCardIndex, setCurrentCardIndex] = useState(0);
  const [showAnswer, setShowAnswer] = useState(false);
  // 触发重新计算到期状态的 ticker
  const [, setTicker] = useState(0);

  // 每分钟刷新一次"距复习"倒计时
  useEffect(() => {
    const timer = setInterval(() => setTicker((n) => n + 1), 60_000);
    return () => clearInterval(timer);
  }, []);

  const filteredWords = useMemo(() => {
    return words.filter((w) => {
      if (languageFilter !== 'all' && w.language !== languageFilter) return false;
      if (difficultyFilter !== 'all' && w.difficulty !== difficultyFilter) return false;
      return true;
    });
  }, [words, languageFilter, difficultyFilter]);

  // 闪卡队列：只复习到期的单词；若无到期单词则复习所有（保证可继续学习）
  const reviewQueue = useMemo(() => {
    const filtered = filteredWords;
    const due = filtered.filter((w) => isDue(w));
    if (due.length > 0) return due;
    // 没有到期时，按 nextReviewAt 升序展示（最先该复习的优先）
    return [...filtered].sort((a, b) => a.nextReviewAt - b.nextReviewAt);
  }, [filteredWords]);

  // 统计
  const dueCount = useMemo(() => filteredWords.filter((w) => isDue(w)).length, [filteredWords]);

  const handleSpeak = (word: string, lang: string) => {
    speak({ text: word, lang, rate: settings.speechRate });
  };

  // 语种适配：单词文本渲染（日语 ruby 假名注音）
  const renderWordText = (word: VocabularyWord) => {
    if (word.language === 'ja' && word.reading) {
      return (
        <ruby>
          {word.word}
          <rp>(</rp>
          <rt className="text-[0.65em] text-primary-500 dark:text-primary-400">{word.reading}</rt>
          <rp>)</rp>
        </ruby>
      );
    }
    return <>{word.word}</>;
  };

  const handleRate = (rating: ReviewRating) => {
    const word = reviewQueue[currentCardIndex];
    if (!word) return;
    recordReview(word.id, rating);
    // 复习行为 = 学习动作，自动打卡
    checkIn();
    if (currentCardIndex < reviewQueue.length - 1) {
      setCurrentCardIndex(currentCardIndex + 1);
      setShowAnswer(false);
    } else {
      // 已复习完一轮
      setCurrentCardIndex(0);
      setShowAnswer(false);
    }
  };

  const handleNextCard = () => {
    if (currentCardIndex < reviewQueue.length - 1) {
      setCurrentCardIndex(currentCardIndex + 1);
      setShowAnswer(false);
    }
  };

  const handlePrevCard = () => {
    if (currentCardIndex > 0) {
      setCurrentCardIndex(currentCardIndex - 1);
      setShowAnswer(false);
    }
  };

  const languages = Object.entries(LANGUAGE_NAMES).slice(0, 5);
  const difficulties = Object.entries(DIFFICULTY_NAMES);

  // 听写模式：整页替换
  if (viewMode === 'dictation') {
    return <DictationMode />;
  }

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-8">
      <BackButton />

      {/* Header */}
      <div className="flex items-center justify-between mb-6 flex-wrap gap-3">
        <div>
          <h1 className="text-xl font-bold text-gray-800 dark:text-gray-100 flex items-center gap-2">
            生词本
            {dueCount > 0 && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-primary-100 dark:bg-primary-900/40 text-primary-700 dark:text-primary-300 text-xs font-medium">
                <Sparkles className="w-3 h-3" />
                {dueCount} 待复习
              </span>
            )}
          </h1>
          <p className="text-sm text-gray-500 mt-0.5">共 {words.length} 个单词</p>
        </div>
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => setViewMode('dictation')}
            disabled={words.length === 0}
            className="btn-secondary !py-1.5 !px-3 text-xs"
            title="听写 / 默写模式"
          >
            <Headphones className="w-3.5 h-3.5" />
            听写模式
          </button>
          <button
            onClick={() => {
              setReviewMode(reviewMode === 'flashcard' ? 'list' : 'flashcard');
              setCurrentCardIndex(0);
              setShowAnswer(false);
            }}
            disabled={filteredWords.length === 0}
            className={cn(
              'btn-secondary !py-1.5 !px-3 text-xs',
              reviewMode === 'flashcard' && 'ring-2 ring-primary-300',
              dueCount > 0 && reviewMode === 'list' && 'animate-pulse'
            )}
          >
            {reviewMode === 'list' ? (
              <>
                <Sparkles className="w-3.5 h-3.5" />
                智能复习
                {dueCount > 0 && <span className="ml-1">({dueCount})</span>}
              </>
            ) : (
              <>
                <BookMarked className="w-3.5 h-3.5" />
                列表模式
              </>
            )}
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex items-center gap-2 mb-6 flex-wrap">
        <span className="text-xs text-gray-400 mr-1">语种：</span>
        <button
          onClick={() => setLanguageFilter('all')}
          className={cn(
            'px-2.5 py-1 rounded-lg text-xs font-medium transition-all',
            languageFilter === 'all' ? 'bg-primary-100 text-primary-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
          )}
        >
          全部
        </button>
        {languages.map(([key, name]) => (
          <button
            key={key}
            onClick={() => setLanguageFilter(key as Language)}
            className={cn(
              'px-2.5 py-1 rounded-lg text-xs font-medium transition-all',
              languageFilter === key ? 'bg-primary-100 text-primary-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            )}
          >
            {name}
          </button>
        ))}

        <span className="text-xs text-gray-400 ml-2 mr-1">难度：</span>
        {difficulties.map(([key, name]) => (
          <button
            key={key}
            onClick={() => setDifficultyFilter(key as Difficulty)}
            className={cn(
              'px-2.5 py-1 rounded-lg text-xs font-medium transition-all',
              difficultyFilter === key ? 'bg-accent-100 text-accent-700' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            )}
          >
            {name}
          </button>
        ))}
      </div>

      {/* Content */}
      {filteredWords.length > 0 ? (
        reviewMode === 'list' ? (
          /* List view */
          <div className="space-y-2">
            {filteredWords.map((word) => {
              const due = isDue(word);
              return (
                <div
                  key={word.id}
                  className={cn(
                    'card p-4 flex items-center gap-4 hover:shadow-sm transition-shadow',
                    due && 'ring-1 ring-primary-200 dark:ring-primary-800'
                  )}
                >
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-0.5 flex-wrap">
                      <span className="font-semibold text-gray-800 dark:text-gray-100 text-sm">
                        {renderWordText(word)}
                      </span>
                      {word.phonetic && (
                        <span className="text-xs text-gray-400 font-mono">/{word.phonetic}/</span>
                      )}
                      {word.language === 'ja' && word.reading && (
                        <span className="text-[10px] text-gray-400">
                          {word.reading} · {toKatakana(word.reading)}
                        </span>
                      )}
                      {word.language === 'en' && word.syllables && (
                        <span className="text-[10px] text-accent-500">{word.syllables}</span>
                      )}
                      <span className="tag-language text-[10px]">{LANGUAGE_NAMES[word.language]}</span>
                      <span className="tag-difficulty text-[10px]">{DIFFICULTY_NAMES[word.difficulty]}</span>
                      {due && (
                        <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[10px] font-medium bg-primary-100 dark:bg-primary-900/40 text-primary-700 dark:text-primary-300">
                          <Clock className="w-2.5 h-2.5" />
                          待复习
                        </span>
                      )}
                    </div>
                    <p className="text-sm text-gray-500 dark:text-gray-400 truncate">
                      {word.translation}
                      {word.partOfSpeech && <span className="ml-2 text-xs text-gray-400">· {word.partOfSpeech}</span>}
                    </p>
                    <p className="text-[11px] text-gray-400 mt-0.5 flex items-center gap-2">
                      <span>复习 {word.reviewCount} 次</span>
                      <span>·</span>
                      <span>
                        {due ? '现在可复习' : `${formatTimeUntil(word.nextReviewAt)}复习`}
                      </span>
                      {word.interval > 0 && (
                        <>
                          <span>·</span>
                          <span>间隔 {word.interval} 天</span>
                        </>
                      )}
                    </p>
                  </div>
                  <div className="flex items-center gap-1 shrink-0">
                    <button
                      onClick={() => handleSpeak(word.word, word.language)}
                      className="btn-ghost !p-1.5"
                      title="朗读"
                    >
                      <Volume2 className="w-3.5 h-3.5" />
                    </button>
                    <button
                      onClick={() => removeWord(word.id)}
                      className="btn-ghost !p-1.5 text-gray-400 hover:text-red-500"
                      title="删除"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          /* Flashcard view - Ebbinghaus SM-2 */
          reviewQueue.length > 0 ? (
            <div className="max-w-md mx-auto">
              {/* Progress */}
              <div className="flex items-center justify-between text-xs text-gray-500 mb-3">
                <span>
                  {currentCardIndex + 1} / {reviewQueue.length}
                  {dueCount > 0 && (
                    <span className="ml-2 text-primary-600 dark:text-primary-400">
                      · {dueCount} 待复习
                    </span>
                  )}
                </span>
                <span className="text-[11px] text-gray-400">
                  EF {reviewQueue[currentCardIndex]?.easeFactor.toFixed(2)}
                </span>
              </div>

              {/* Card */}
              <div
                className="card p-8 min-h-[260px] flex flex-col items-center justify-center cursor-pointer select-none"
                onClick={() => setShowAnswer(!showAnswer)}
              >
                {reviewQueue[currentCardIndex] && (
                  <>
                    <span className="text-[10px] uppercase tracking-wider text-gray-400 mb-2">
                      {LANGUAGE_NAMES[reviewQueue[currentCardIndex].language]} ·{' '}
                      {DIFFICULTY_NAMES[reviewQueue[currentCardIndex].difficulty]}
                    </span>
                    <h2 className="text-3xl font-bold text-gray-800 dark:text-gray-100 mb-3 text-center break-words">
                      {showAnswer
                        ? reviewQueue[currentCardIndex].translation
                        : renderWordText(reviewQueue[currentCardIndex])}
                    </h2>
                    {showAnswer && reviewQueue[currentCardIndex].phonetic && (
                      <p className="text-sm text-gray-400 font-mono mb-2">
                        /{reviewQueue[currentCardIndex].phonetic}/
                      </p>
                    )}
                    {showAnswer && reviewQueue[currentCardIndex].language === 'ja' && reviewQueue[currentCardIndex].reading && (
                      <p className="text-xs text-gray-400 mb-2">
                        平假名: {reviewQueue[currentCardIndex].reading} · 片假名: {toKatakana(reviewQueue[currentCardIndex].reading)}
                      </p>
                    )}
                    {showAnswer && reviewQueue[currentCardIndex].language === 'en' && reviewQueue[currentCardIndex].syllables && (
                      <p className="text-xs text-accent-500 mb-2">{reviewQueue[currentCardIndex].syllables}</p>
                    )}
                    {showAnswer && reviewQueue[currentCardIndex].partOfSpeech && (
                      <p className="text-xs text-gray-500 mb-3">
                        · {reviewQueue[currentCardIndex].partOfSpeech}
                      </p>
                    )}
                    {showAnswer && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleSpeak(reviewQueue[currentCardIndex].word, reviewQueue[currentCardIndex].language);
                        }}
                        className="btn-ghost !p-2"
                      >
                        <Volume2 className="w-4 h-4" />
                      </button>
                    )}
                    <p className="text-xs text-gray-400 mt-4">
                      {showAnswer ? '点击查看单词' : '点击显示释义'}
                    </p>
                  </>
                )}
              </div>

              {/* Rating buttons (only show after reveal) */}
              {showAnswer ? (
                <div className="grid grid-cols-4 gap-2 mt-6">
                  {([0, 1, 2, 3] as ReviewRating[]).map((rating) => {
                    const info = REVIEW_RATINGS[rating];
                    const colorMap: Record<string, string> = {
                      red: 'bg-red-100 hover:bg-red-200 text-red-700 dark:bg-red-900/30 dark:hover:bg-red-900/50 dark:text-red-300 border-red-200 dark:border-red-800',
                      orange: 'bg-orange-100 hover:bg-orange-200 text-orange-700 dark:bg-orange-900/30 dark:hover:bg-orange-900/50 dark:text-orange-300 border-orange-200 dark:border-orange-800',
                      primary: 'bg-primary-100 hover:bg-primary-200 text-primary-700 dark:bg-primary-900/30 dark:hover:bg-primary-900/50 dark:text-primary-300 border-primary-200 dark:border-primary-800',
                      green: 'bg-green-100 hover:bg-green-200 text-green-700 dark:bg-green-900/30 dark:hover:bg-green-900/50 dark:text-green-300 border-green-200 dark:border-green-800',
                    };
                    return (
                      <button
                        key={rating}
                        onClick={() => handleRate(rating)}
                        title={info.description}
                        className={cn(
                          'flex flex-col items-center justify-center gap-1 py-3 rounded-xl border-2 font-medium text-sm transition-colors',
                          colorMap[info.color]
                        )}
                      >
                        <span>{info.label}</span>
                        <span className="text-[10px] opacity-75 font-normal">
                          {rating === 0 ? '< 1天' : rating === 1 ? '1.2×' : rating === 2 ? `${reviewQueue[currentCardIndex]?.easeFactor.toFixed(1)}×` : `${(reviewQueue[currentCardIndex]?.easeFactor * 1.3).toFixed(1)}×`}
                        </span>
                      </button>
                    );
                  })}
                </div>
              ) : (
                <button
                  onClick={() => setShowAnswer(true)}
                  className="btn-primary w-full mt-6"
                >
                  <CheckCircle2 className="w-4 h-4" />
                  显示答案
                </button>
              )}

              {/* Navigation */}
              <div className="flex items-center justify-center gap-4 mt-4">
                <button
                  onClick={handlePrevCard}
                  disabled={currentCardIndex === 0}
                  className="btn-secondary disabled:opacity-30 text-xs !py-1.5 !px-3"
                >
                  <ArrowLeft className="w-3.5 h-3.5" /> 上一个
                </button>
                <button
                  onClick={handleNextCard}
                  disabled={currentCardIndex >= reviewQueue.length - 1}
                  className="btn-secondary disabled:opacity-30 text-xs !py-1.5 !px-3"
                >
                  跳过 <ChevronRight className="w-3.5 h-3.5" />
                </button>
              </div>

              {currentCardIndex === reviewQueue.length - 1 && showAnswer && (
                <div className="mt-4 p-3 rounded-xl bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 text-center">
                  <p className="text-sm text-green-700 dark:text-green-300 flex items-center justify-center gap-1.5">
                    <CheckCircle2 className="w-4 h-4" />
                    已完成本轮复习
                  </p>
                </div>
              )}
            </div>
          ) : (
            <EmptyState
              icon={<BookMarked className="w-12 h-12" />}
              title="还没有生词"
              description="在阅读文章中点击单词即可收藏到生词本"
            />
          )
        )
      ) : (
        <EmptyState
          icon={<BookMarked className="w-12 h-12" />}
          title="还没有生词"
          description="在阅读文章中点击单词即可收藏到生词本"
        />
      )}
    </div>
  );
}
