import { useState, useEffect } from 'react';
import { X, Share2, Loader2 } from 'lucide-react';
import { submitArticle, getPublicCategories } from '@/api/publicArticle';
import type { Article } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import { cn } from '@/lib/utils';

interface ShareToPublicModalProps {
  isOpen: boolean;
  onClose: () => void;
  article: Article;
}

export default function ShareToPublicModal({ isOpen, onClose, article }: ShareToPublicModalProps) {
  const [categories, setCategories] = useState<Array<{ id: string; name: string; icon?: string }>>([]);
  const [categoryId, setCategoryId] = useState('');
  const [tags, setTags] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    if (isOpen) {
      getPublicCategories()
        .then((data) => {
          setCategories(data.list.map((c) => ({ id: c.id, name: c.name, icon: c.icon || undefined })));
        })
        .catch(() => {});
      setCategoryId('');
      setTags('');
      setError('');
      setSuccess(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const hasTranslation = !!article.translation;

  const handleSubmit = async () => {
    if (!hasTranslation) {
      setError('请先翻译文章后再分享到公共库');
      return;
    }
    setLoading(true);
    setError('');
    try {
      await submitArticle({
        title: article.title,
        content: article.content,
        translation: article.translation!,
        sourceLanguage: article.sourceLanguage,
        targetLanguage: article.targetLanguage,
        categoryId: categoryId || undefined,
        tags: tags ? tags.split(',').map((s) => s.trim()).filter(Boolean) : [],
      });
      setSuccess(true);
    } catch (e) {
      setError(e instanceof Error ? e.message : '提交失败，请稍后重试');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4"
      onClick={onClose}
    >
      <div
        className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl max-w-md w-full max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-gray-100 dark:border-gray-700">
          <div className="flex items-center gap-2">
            <Share2 className="w-5 h-5 text-primary-500" />
            <h2 className="text-base font-semibold text-gray-800 dark:text-gray-100">分享到公共库</h2>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
            <X className="w-5 h-5" />
          </button>
        </div>

        {success ? (
          /* Success state */
          <div className="p-6 text-center">
            <div className="w-16 h-16 mx-auto rounded-full bg-green-100 dark:bg-green-900/40 flex items-center justify-center mb-4">
              <Share2 className="w-8 h-8 text-green-600 dark:text-green-400" />
            </div>
            <h3 className="text-base font-semibold text-gray-800 dark:text-gray-100 mb-2">
              已提交成功
            </h3>
            <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">
              你的文章已提交到公共文章库，等待管理员审核通过后将公开展示。
            </p>
            <button onClick={onClose} className="btn-primary w-full">
              完成
            </button>
          </div>
        ) : (
          /* Form */
          <div className="p-5 space-y-4">
            {/* Article info preview */}
            <div className="p-3 rounded-xl bg-gray-50 dark:bg-slate-700/50">
              <div className="text-sm font-medium text-gray-700 dark:text-gray-200 truncate">
                {article.title}
              </div>
              <div className="flex items-center gap-2 mt-1 text-[11px] text-gray-400">
                <span>{LANGUAGE_NAMES[article.sourceLanguage]}</span>
                <span>→</span>
                <span>{LANGUAGE_NAMES[article.targetLanguage]}</span>
                <span>·</span>
                <span>{article.content.length} 字</span>
                {article.translation && (
                  <>
                    <span>·</span>
                    <span className="text-green-500">已翻译</span>
                  </>
                )}
              </div>
            </div>

            {!hasTranslation && (
              <div className="p-3 rounded-lg bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800">
                <p className="text-xs text-yellow-700 dark:text-yellow-400">
                  这篇文章还没有翻译。请先在阅读页面翻译完成后再分享到公共库。
                </p>
              </div>
            )}

            {/* Category select */}
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-300 mb-1.5">
                分类
              </label>
              <select
                value={categoryId}
                onChange={(e) => setCategoryId(e.target.value)}
                className="w-full px-3 py-2 rounded-xl bg-gray-50 dark:bg-slate-700 border border-gray-200 dark:border-gray-600 text-sm text-gray-700 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-primary-300"
              >
                <option value="">不选择分类</option>
                {categories.map((cat) => (
                  <option key={cat.id} value={cat.id}>
                    {cat.icon} {cat.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Tags input */}
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-300 mb-1.5">
                标签（英文逗号分隔，可选）
              </label>
              <input
                type="text"
                value={tags}
                onChange={(e) => setTags(e.target.value)}
                placeholder="如: 阅读, 习惯, 自我提升"
                className="w-full px-3 py-2 rounded-xl bg-gray-50 dark:bg-slate-700 border border-gray-200 dark:border-gray-600 text-sm text-gray-700 dark:text-gray-200 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-primary-300"
              />
            </div>

            {error && (
              <div className="p-2.5 rounded-lg bg-red-50 dark:bg-red-900/20 text-xs text-red-600 dark:text-red-400">
                {error}
              </div>
            )}

            {/* Actions */}
            <div className="flex justify-end gap-2 pt-2">
              <button
                onClick={onClose}
                className="btn-ghost !py-2 !px-4 text-xs"
              >
                取消
              </button>
              <button
                onClick={handleSubmit}
                disabled={!hasTranslation || loading}
                className={cn(
                  'btn-primary !py-2 !px-4 text-xs',
                  (!hasTranslation || loading) && 'opacity-50 cursor-not-allowed'
                )}
              >
                {loading ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    提交中...
                  </>
                ) : (
                  <>
                    <Share2 className="w-3.5 h-3.5" />
                    提交分享
                  </>
                )}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
