/**
 * 英文→中文反向词典
 * 从 CN_EN_DICT 自动生成，支持一词多义
 */

import { CN_EN_DICT } from './replacementEngine';

export interface EnCnEntry {
  pos: string;
  meanings: string[];
  phonetic: string;
}

// 自动生成反向词典：英文单词 → [{ pos, meanings: [中文1, 中文2, ...], phonetic }]
export const EN_CN_DICT: Record<string, EnCnEntry[]> = (() => {
  const map: Record<string, { pos: string; meanings: Set<string>; phonetic: string }[]> = {};

  for (const [cn, entries] of Object.entries(CN_EN_DICT)) {
    for (const entry of entries) {
      const en = entry.en.toLowerCase();
      if (!map[en]) {
        map[en] = [];
      }

      // 查找是否已有相同词性的条目
      let posEntry = map[en].find(e => e.pos === entry.pos);
      if (!posEntry) {
        posEntry = { pos: entry.pos, meanings: new Set(), phonetic: entry.phonetic || '' };
        map[en].push(posEntry);
      }
      posEntry.meanings.add(cn);
      // 优先保留非空的音标
      if (entry.phonetic && !posEntry.phonetic) {
        posEntry.phonetic = entry.phonetic;
      }
    }
  }

  // 转换为最终格式
  const result: Record<string, EnCnEntry[]> = {};
  for (const [en, entries] of Object.entries(map)) {
    result[en] = entries.map(e => ({
      pos: e.pos,
      meanings: Array.from(e.meanings),
      phonetic: e.phonetic,
    }));
  }

  return result;
})();

// 中文词性 → 英文标签
export const POS_LABELS: Record<string, string> = {
  noun: 'n.',
  verb: 'v.',
  adjective: 'adj.',
  adverb: 'adv.',
};
