/**
 * 统一 API 客户端（基于 fetch）。
 * 自动附加 learner token，处理 { code, data, message } 响应格式。
 * 401 时触发重新注册设备回调。
 */

const BASE_URL = '/api';

/** localStorage 中 learner token 的键名 */
export const LEARNER_TOKEN_KEY = 'bilingual-reader-learner-token';
export const LEARNER_DEVICE_KEY = 'bilingual-reader-learner-device';
export const LEARNER_ID_KEY = 'bilingual-reader-learner-id';

export function getToken(): string | null {
  return localStorage.getItem(LEARNER_TOKEN_KEY);
}

export function setToken(token: string): void {
  localStorage.setItem(LEARNER_TOKEN_KEY, token);
}

export function getDeviceId(): string | null {
  return localStorage.getItem(LEARNER_DEVICE_KEY);
}

export function setDeviceId(id: string): void {
  localStorage.setItem(LEARNER_DEVICE_KEY, id);
}

export function getLearnerId(): string | null {
  return localStorage.getItem(LEARNER_ID_KEY);
}

export function setLearnerId(id: string): void {
  localStorage.setItem(LEARNER_ID_KEY, id);
}

/** 生成 uuid（无 crypto.randomUUID 时回退） */
export function uuid(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export interface ApiError extends Error {
  status: number;
  code: number;
}

function makeError(status: number, code: number, message: string): ApiError {
  const e = new Error(message) as ApiError;
  e.status = status;
  e.code = code;
  return e;
}

interface RequestOptions {
  method?: 'GET' | 'POST' | 'PATCH' | 'DELETE';
  body?: unknown;
  /** 跳过附加 token（用于设备注册接口本身） */
  skipAuth?: boolean;
  signal?: AbortSignal;
}

/**
 * 发起 API 请求。
 * @returns 响应 data 字段
 * @throws ApiError 当 HTTP 状态码非 2xx 或业务 code !== 0
 */
export async function request<T = unknown>(
  path: string,
  options: RequestOptions = {}
): Promise<T> {
  const { method = 'GET', body, skipAuth = false, signal } = options;
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  if (!skipAuth) {
    const token = getToken();
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }
  }

  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
    signal,
  });

  let json: { code: number; data: T | null; message: string } | null = null;
  try {
    json = (await res.json()) as { code: number; data: T | null; message: string };
  } catch {
    throw makeError(res.status, -1, `请求失败 (${res.status})`);
  }

  if (!res.ok || (json && json.code !== 0)) {
    const code = json?.code ?? res.status;
    const message = json?.message ?? `请求失败 (${res.status})`;
    throw makeError(res.status, code, message);
  }

  return (json?.data ?? null) as T;
}

export const apiGet = <T = unknown>(path: string, signal?: AbortSignal) =>
  request<T>(path, { method: 'GET', signal });

export const apiPost = <T = unknown>(path: string, body?: unknown, signal?: AbortSignal) =>
  request<T>(path, { method: 'POST', body, signal });

export const apiPatch = <T = unknown>(path: string, body?: unknown, signal?: AbortSignal) =>
  request<T>(path, { method: 'PATCH', body, signal });

export const apiDelete = <T = unknown>(path: string, signal?: AbortSignal) =>
  request<T>(path, { method: 'DELETE', signal });
