/**
 * 日语假名数据（五十音图 + 浊音/半浊音/拗音）
 * 共 104 条：清音 45 + 拨音 1 + 浊音 20 + 半浊音 5 + 清拗音 21 + 浊/半浊拗音 12
 * 用于基础学习模块的假名网格展示与朗读。
 */

export type KanaType = 'clear' | 'voiced' | 'semi-voiced' | 'youon' | 'special';

export interface KanaEntry {
  /** 平假名 */
  hiragana: string;
  /** 片假名 */
  katakana: string;
  /** 罗马音 */
  romaji: string;
  /** 所属行（用行首假名，如 'あ' 'か'） */
  row: string;
  /** 所属段（あ/い/う/え/お）；拗音用 'ゃ'/'ゅ'/'ょ' */
  column: string;
  /** 类型 */
  type: KanaType;
  /** 笔画数（可选，用于书写动画，暂保留） */
  strokeCount?: number;
}

/** 五段（列）顺序 */
export const KANA_COLUMNS: string[] = ['あ', 'い', 'う', 'え', 'お'];

/** 十行顺序 */
export const KANA_ROWS: string[] = ['あ', 'か', 'さ', 'た', 'な', 'は', 'ま', 'や', 'ら', 'わ'];

