import type { TranslationPair } from '@/services/translationService';

/**
 * 由原文 + 译文按行分割构造 TranslationPair[]
 * 用于从已翻译的文章恢复对照数据（不触发翻译 API）
 */
export function buildTranslationPairs(content: string, translation: string): TranslationPair[] {
  const lines = content.split('\n');
  const translatedLines = translation.split('\n');
  return lines.map((original, i) => ({
    original,
    translated: translatedLines[i] || '',
  }));
}
