/**
 * 听写/默写判题工具
 *
 * 设计原则：
 * - 大小写不敏感
 * - 标点、空格不计入判定
 * - 常见拼写错误容错（重复字母、连字符等）
 * - 计算相似度作为部分得分参考
 */

import type { VocabularyWord } from '@/types';

/** 标准化：去标点、转小写、合并空白 */
export function normalize(text: string): string {
  return text
    .toLowerCase()
    .replace(/[''`]/g, "'") // 统一不同样式的单引号
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[.,!?;:"()\[\]{}]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Levenshtein 距离（编辑距离） */
export function editDistance(a: string, b: string): number {
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1, // 删除
        dp[i][j - 1] + 1, // 插入
        dp[i - 1][j - 1] + cost // 替换
      );
    }
  }
  return dp[m][n];
}

/** 相似度 0-1（基于编辑距离） */
export function similarity(a: string, b: string): number {
  if (!a && !b) return 1;
  const dist = editDistance(a, b);
  return 1 - dist / Math.max(a.length, b.length, 1);
}

/** 判定对错 */
export function checkAnswer(userInput: string, correctAnswer: string): {
  correct: boolean;
  similarity: number;
  diff?: { missing: string; extra: string };
} {
  const u = normalize(userInput);
  const c = normalize(correctAnswer);
  if (u === c) return { correct: true, similarity: 1 };
  // 多词答案（如 "a piece of cake"）允许容错
  // 但单次/二词短语严格匹配
  const sim = similarity(u, c);
  return {
    correct: false,
    similarity: sim,
  };
}

/** 打分逻辑 */
export interface ScoringResult {
  base: number; // 基础分
  combo: number; // 连击加成
  total: number; // 本题得分
  isCorrect: boolean;
  isPartial: boolean; // 是否部分正确（相似度 >= 0.6）
}

export function scoreAnswer(
  userInput: string,
  correctAnswer: string,
  combo: number
): ScoringResult {
  const { correct, similarity: sim } = checkAnswer(userInput, correctAnswer);
  if (correct) {
    const base = 10;
    const comboBonus = Math.min(combo, 5) * 1; // 最多 +5
    return { base, combo: comboBonus, total: base + comboBonus, isCorrect: true, isPartial: false };
  }
  if (sim >= 0.6) {
    // 部分正确：相似度达到 60% 给个安慰分
    const base = 2 + Math.round(sim * 3); // 2-5 分
    return { base, combo: 0, total: base, isCorrect: false, isPartial: true };
  }
  return { base: 0, combo: 0, total: 0, isCorrect: false, isPartial: false };
}

/** 抽题：从词库中随机抽取 N 个不重复的单词 */
export function pickWords(pool: VocabularyWord[], count: number): VocabularyWord[] {
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

/** 难度筛选 */
export function filterByLanguage(
  words: VocabularyWord[],
  language: string | 'all'
): VocabularyWord[] {
  if (language === 'all') return words;
  return words.filter((w) => w.language === language);
}
