import { Clock, ChevronRight, BookOpen } from 'lucide-react';
import type { Article } from '@/types';
import { LANGUAGE_NAMES } from '@/types';
import { cn } from '@/lib/utils';

interface ArticleCardProps {
  article: Article;
  onClick?: () => void;
  className?: string;
  variant?: 'grid' | 'list';
}

export default function ArticleCard({ article, onClick, className, variant = 'list' }: ArticleCardProps) {
  const timeAgo = (timestamp: number) => {
    const diff = Date.now() - timestamp;
    const minutes = Math.floor(diff / 60000);
    if (minutes < 60) return `${minutes}分钟前`;
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}小时前`;
    const days = Math.floor(hours / 24);
    return `${days}天前`;
  };

  const preview = article.content.slice(0, 80) + (article.content.length > 80 ? '...' : '');

  if (variant === 'grid') {
    return (
      <div
        onClick={onClick}
        className={cn(
          'card-hover group flex flex-col overflow-hidden cursor-pointer',
          className
        )}
      >
        <div className="h-24 bg-gradient-to-br from-primary-100 to-accent-100 dark:from-primary-900/40 dark:to-accent-900/40 flex items-center justify-center shrink-0">
          <BookOpen className="w-8 h-8 text-primary-500 dark:text-primary-400 opacity-60" />
        </div>
        <div className="p-3 flex flex-col flex-1 min-h-0">
          <h3 className="font-semibold text-gray-800 dark:text-gray-100 text-sm mb-1.5 line-clamp-2 leading-snug">
            {article.title}
          </h3>
          <p className="text-xs text-gray-400 dark:text-gray-500 leading-relaxed line-clamp-3 flex-1">
            {preview}
          </p>
          <div className="flex items-center gap-2 flex-wrap mt-3 pt-2 border-t border-gray-100 dark:border-gray-800">
            <span className="tag-language text-[10px] px-1.5 py-0.5">
              {LANGUAGE_NAMES[article.targetLanguage] || article.targetLanguage}
            </span>
            <span className="flex items-center gap-1 text-[10px] text-gray-400 ml-auto">
              <Clock className="w-3 h-3" />
              {timeAgo(article.updatedAt)}
            </span>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div
      onClick={onClick}
      className={cn(
        'card-hover p-4 group cursor-pointer',
        className
      )}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <h3 className="font-semibold text-gray-800 dark:text-gray-100 text-sm mb-1 truncate">
            {article.title}
          </h3>
          <p className="text-xs text-gray-400 dark:text-gray-500 leading-relaxed line-clamp-2">
            {preview}
          </p>
        </div>
        <ChevronRight className="w-4 h-4 text-gray-300 dark:text-gray-600 mt-1 shrink-0 group-hover:text-primary-500 transition-colors" />
      </div>

      <div className="flex items-center gap-2 flex-wrap mt-3">
        <span className="tag-language text-[10px] px-2 py-0.5">
          {LANGUAGE_NAMES[article.targetLanguage] || article.targetLanguage}
        </span>
        <span className="flex items-center gap-1 text-[10px] text-gray-400">
          <Clock className="w-3 h-3" />
          {timeAgo(article.updatedAt)}
        </span>
        {article.tags?.map((tag) => (
          <span key={tag} className="tag bg-gray-100 dark:bg-slate-700 text-gray-500 dark:text-gray-400 text-[10px] px-2 py-0.5">
            {tag}
          </span>
        ))}
      </div>
    </div>
  );
}