import { RotateCcw, ArrowLeft, Trophy } from 'lucide-react';
import { cn } from '@/lib/utils';

interface BasicQuizResultProps {
  correct: number;
  total: number;
  onRetry: () => void;
  onBack: () => void;
}

export default function BasicQuizResult({ correct, total, onRetry, onBack }: BasicQuizResultProps) {
  const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;

  // 圆环参数
  const radius = 52;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (percentage / 100) * circumference;

  // 鼓励文案
  let encouragement = '';
  let color = '';
  if (percentage >= 90) {
    encouragement = '太棒了！你已掌握得很扎实 🎉';
    color = 'text-emerald-500';
  } else if (percentage >= 70) {
    encouragement = '做得不错！再练几次就更熟练了 💪';
    color = 'text-primary-500';
  } else if (percentage >= 50) {
    encouragement = '继续加油，多看多练就能进步 📚';
    color = 'text-orange-500';
  } else {
    encouragement = '别灰心，先回到课程复习一下吧 🌱';
    color = 'text-red-400';
  }

  return (
    <div className="max-w-md mx-auto text-center py-6">
      <div className="relative inline-flex items-center justify-center mb-6">
        <svg width="140" height="140" className="-rotate-90">
          <circle
            cx="70"
            cy="70"
            r={radius}
            fill="none"
            strokeWidth="10"
            className="stroke-gray-100 dark:stroke-slate-700"
          />
          <circle
            cx="70"
            cy="70"
            r={radius}
            fill="none"
            strokeWidth="10"
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
            className="stroke-primary-500 transition-all duration-700"
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className={cn('text-3xl font-bold', color)}>{percentage}%</span>
          <span className="text-xs text-gray-400 mt-0.5">正确率</span>
        </div>
      </div>

      <div className="mb-2 flex items-center justify-center gap-2">
        <Trophy className={cn('w-5 h-5', color)} />
        <span className="text-lg font-semibold text-gray-800 dark:text-gray-100">
          {correct} / {total} 题正确
        </span>
      </div>
      <p className={cn('text-sm mb-8', color)}>{encouragement}</p>

      <div className="flex items-center justify-center gap-3">
        <button
          onClick={onBack}
          className="btn-secondary"
        >
          <ArrowLeft className="w-4 h-4" />
          返回课程
        </button>
        <button
          onClick={onRetry}
          className="btn-primary"
        >
          <RotateCcw className="w-4 h-4" />
          再练一次
        </button>
      </div>
    </div>
  );
}
