import { useNavigate } from 'react-router-dom';
import { Lock, LogIn, X } from 'lucide-react';
import { useUIStore } from '@/stores/uiStore';
import { useLocation } from 'react-router-dom';

export default function LoginPrompt() {
  const { showLoginPrompt, setShowLoginPrompt } = useUIStore();
  const navigate = useNavigate();
  const location = useLocation();

  if (!showLoginPrompt) return null;

  const handleLogin = () => {
    setShowLoginPrompt(false);
    navigate('/auth', { state: { from: location.pathname } });
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-fade-in"
      onClick={() => setShowLoginPrompt(false)}
    >
      <div
        className="bg-white dark:bg-slate-800 rounded-2xl shadow-xl max-w-xs w-full p-6 text-center animate-bounce-in"
        onClick={(e) => e.stopPropagation()}
      >
        <button
          onClick={() => setShowLoginPrompt(false)}
          className="absolute top-3 right-3 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
        >
          <X className="w-4 h-4" />
        </button>

        <div className="w-14 h-14 mx-auto rounded-full bg-primary-50 dark:bg-primary-900/30 flex items-center justify-center mb-4">
          <Lock className="w-7 h-7 text-primary-500" />
        </div>

        <h3 className="text-base font-semibold text-gray-800 dark:text-gray-100 mb-1.5">
          请先登录
        </h3>
        <p className="text-xs text-gray-500 dark:text-gray-400 mb-5">
          此功能需要登录后使用，游客模式仅支持预览浏览
        </p>

        <div className="flex gap-2">
          <button
            onClick={() => setShowLoginPrompt(false)}
            className="flex-1 btn-ghost !py-2 text-xs"
          >
            取消
          </button>
          <button
            onClick={handleLogin}
            className="flex-1 btn-primary !py-2 text-xs"
          >
            <LogIn className="w-3.5 h-3.5" />
            去登录
          </button>
        </div>
      </div>
    </div>
  );
}
