import { useState, useCallback, useRef, useEffect } from 'react';
import { translateLineByLine } from '@/services/translationService';
import type { TranslationPair } from '@/services/translationService';
import type { Article } from '@/types';
import { useWalletStore } from '@/stores/walletStore';
import { useAuthStore } from '@/stores/authStore';
import { useUIStore } from '@/stores/uiStore';
import { buildTranslationPairs } from '@/lib/translationPairs';

/** 长文本翻译扣费阈值（字符数），短文本（选词查词）不扣 */
const LONG_TEXT_THRESHOLD = 2000;

interface UseTranslationReturn {
  translationPairs: TranslationPair[];
  setTranslationPairs: React.Dispatch<React.SetStateAction<TranslationPair[]>>;
  isTranslating: boolean;
  translationError: string;
  /**
   * 源语种 = 目标语种，已跳过翻译（直接用原文作为译文）。
   * UI 应当显示提示信息而非"翻译完成"或"翻译失败"。
   */
  noTranslationNeeded: boolean;
  /** 翻译进度（0-100） */
  translationProgress: number;
  /** 翻译进度文字，如 "正在翻译第 3/10 句" */
  translationProgressText: string;
  /** 已完成的句子数 */
  translationCompleted: number;
  /** 总句子数 */
  translationTotal: number;
  handleTranslate: (article: Article) => Promise<void>;
  retryTranslation: (article: Article) => Promise<void>;
  cancelTranslation: () => void;
  restoreTranslation: (article: Article) => TranslationPair[];
}

export function useTranslation(
  updateArticle: (id: string, data: Partial<Article>) => void
): UseTranslationReturn {
  const [translationPairs, setTranslationPairs] = useState<TranslationPair[]>([]);
  const [isTranslating, setIsTranslating] = useState(false);
  const [translationError, setTranslationError] = useState('');
  const [noTranslationNeeded, setNoTranslationNeeded] = useState(false);
  const [translationProgress, setTranslationProgress] = useState(0);
  const [translationProgressText, setTranslationProgressText] = useState('');
  const [translationCompleted, setTranslationCompleted] = useState(0);
  const [translationTotal, setTranslationTotal] = useState(0);

  // 中断信号（用于取消进行中的翻译）
  const signalRef = useRef<{ aborted: boolean } | null>(null);

  // 组件卸载时取消翻译
  useEffect(() => {
    return () => {
      if (signalRef.current) {
        signalRef.current.aborted = true;
      }
    };
  }, []);

  const runTranslate = useCallback(
    async (article: Article) => {
      // 初始化中断信号
      if (signalRef.current) {
        signalRef.current.aborted = true;
      }
      const signal = { aborted: false };
      signalRef.current = signal;

      setIsTranslating(true);
      setTranslationError('');
      setNoTranslationNeeded(false);
      setTranslationProgress(0);
      setTranslationCompleted(0);
      setTranslationTotal(0);
      setTranslationProgressText('准备翻译...');

      // 长文本扣费拦截：content 超过阈值时先扣次数/币
      const contentLen = article.content.length;
      if (contentLen > LONG_TEXT_THRESHOLD) {
        setTranslationProgressText('正在扣除翻译次数...');
        const { spend } = useWalletStore.getState();
        const result = await spend(article.id, contentLen);
        if (!result.ok) {
          setTranslationError('翻译次数不足，请打卡获取虚拟币或兑换后再试');
          setTranslationProgressText('翻译次数不足');
          setIsTranslating(false);
          return;
        }
      }

      try {
        const result = await translateLineByLine(
          article.content,
          article.sourceLanguage,
          article.targetLanguage,
          {
            signal,
            onProgress: (completed, total, current) => {
              setTranslationCompleted(completed);
              setTranslationTotal(total);
              const percent = total > 0 ? Math.round((completed / total) * 100) : 0;
              setTranslationProgress(percent);
              if (current && completed < total) {
                const preview = current.length > 20 ? current.slice(0, 20) + '…' : current;
                setTranslationProgressText(`正在翻译第 ${completed + 1}/${total} 句：${preview}`);
              } else {
                setTranslationProgressText(`已完成 ${completed}/${total}`);
              }
            },
          }
        );

        if (signal.aborted) {
          return; // 已被取消，不更新状态
        }

        setTranslationPairs(result.pairs);
        setTranslationProgress(100);
        setNoTranslationNeeded(result.noTranslationNeeded);
        setTranslationProgressText(
          result.noTranslationNeeded ? '源语种 = 目标语种，无需翻译' : '翻译完成'
        );
        // 仅在真正翻译完成时持久化译文；同语种情况下原文已展示，不必再保存一遍
        if (!result.noTranslationNeeded) {
          const translatedText = result.pairs.map((p) => p.translated).join('\n');
          updateArticle(article.id, { translation: translatedText });
        }
      } catch (error) {
        if (signal.aborted) return;
        const msg = error instanceof Error ? error.message : '翻译失败，请稍后重试';
        setTranslationError(msg);
        setTranslationProgressText('翻译失败');
      } finally {
        if (!signal.aborted) {
          setIsTranslating(false);
        }
      }
    },
    [updateArticle]
  );

  const handleTranslate = useCallback(
    async (article: Article) => {
      // 游客模式拦截：翻译需要登录
      if (useAuthStore.getState().isGuest) {
        useUIStore.getState().setShowLoginPrompt(true);
        return;
      }
      await runTranslate(article);
    },
    [runTranslate]
  );

  /** 失败重试（保留已有翻译） */
  const retryTranslation = useCallback(
    async (article: Article) => {
      setTranslationError('');
      setNoTranslationNeeded(false);
      await runTranslate(article);
    },
    [runTranslate]
  );

  /** 取消翻译 */
  const cancelTranslation = useCallback(() => {
    if (signalRef.current) {
      signalRef.current.aborted = true;
    }
    setIsTranslating(false);
    setTranslationProgressText('已取消');
  }, []);

  const restoreTranslation = useCallback((article: Article): TranslationPair[] => {
    if (!article.translation) {
      setTranslationPairs([]);
      return [];
    }
    const pairs = buildTranslationPairs(article.content, article.translation);
    setTranslationPairs(pairs);
    return pairs;
  }, []);

  return {
    translationPairs,
    setTranslationPairs,
    isTranslating,
    translationError,
    noTranslationNeeded,
    translationProgress,
    translationProgressText,
    translationCompleted,
    translationTotal,
    handleTranslate,
    retryTranslation,
    cancelTranslation,
    restoreTranslation,
  };
}
