/**
 * 8 语种字符集正则 + 文本语种判定工具
 *
 * 用于 useTextSelection 中：
 * - 判定用户选中的文本是否属于文章源语种
 * - 决定走"中文→英文高亮"还是"外文→中文高亮"分支
 *
 * 注意：日文正则同时包含假名和汉字，因为日语文章中汉字非常常见。
 */

import type { Language } from '@/types';

export const LANG_CHAR_PATTERNS: Record<Language, RegExp> = {
  zh: /[\u4e00-\u9fff]/,
  en: /[A-Za-z]/,
  // 假名（平假名 \u3040-\u309f、片假名 \u30a0-\u30ff、半角假名 \uff65-\uff9f）+ 汉字
  ja: /[\u3040-\u30ff\u31f0-\u31ff\uff65-\uff9f\u4e00-\u9fff]/,
  ko: /[\uac00-\ud7af]/,
  ru: /[\u0400-\u04ff]/,
  es: /[A-Za-zÁÉÍÑÓÚÜáéíñóúü]/,
  fr: /[A-Za-zÀ-ÖØ-öø-ÿ]/,
  de: /[A-Za-zÄÖÜäöüß]/,
  ar: /[\u0600-\u06ff]/,
};

/**
 * 判断文本是否含有指定源语种的字符。
 * 用作"用户选中外文"的判定依据。
 */
export function isSourceLanguageText(text: string, lang: Language): boolean {
  return LANG_CHAR_PATTERNS[lang].test(text);
}
