import { useState, useEffect } from 'react';
import { Volume2, Check, X } from 'lucide-react';
import { speak } from '@/lib/speech';
import { cn } from '@/lib/utils';

export interface QuizQuestion {
  /** 题干文本（如字母 'A' 或假名 'あ'） */
  prompt: string;
  /** 辅助显示（如罗马音） */
  promptRomaji?: string;
  /** TTS 朗读内容（默认用 prompt） */
  playText?: string;
  /** 朗读语种 */
  lang?: string;
  /** 4 个选项 */
  options: string[];
  /** 正确答案 */
  answer: string;
}

interface BasicQuizProps {
  questions: QuizQuestion[];
  onComplete: (correct: number, total: number) => void;
}

export default function BasicQuiz({ questions, onComplete }: BasicQuizProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selected, setSelected] = useState<string | null>(null);
  const [correctCount, setCorrectCount] = useState(0);
  const [answered, setAnswered] = useState(false);

  const question = questions[currentIndex];

  // 自动播放当前题干（仅 TTS 题型可朗读时）
  useEffect(() => {
    setSelected(null);
    setAnswered(false);
  }, [currentIndex]);

  if (!question) return null;

  const handleSelect = (option: string) => {
    if (answered) return;
    setSelected(option);
    setAnswered(true);
    const isCorrect = option === question.answer;
    if (isCorrect) setCorrectCount((c) => c + 1);

    // 1.2 秒后进入下一题或完成
    setTimeout(() => {
      if (currentIndex + 1 >= questions.length) {
        onComplete(isCorrect ? correctCount + 1 : correctCount, questions.length);
      } else {
        setCurrentIndex((i) => i + 1);
      }
    }, 1200);
  };

  const handlePlayPrompt = () => {
    speak({ text: question.playText || question.prompt, lang: question.lang || 'en' });
  };

  const progress = ((currentIndex + (answered ? 1 : 0)) / questions.length) * 100;

  return (
    <div className="max-w-xl mx-auto">
      {/* 进度条 */}
      <div className="mb-6">
        <div className="flex items-center justify-between mb-1.5 text-xs text-gray-500 dark:text-gray-400">
          <span>第 {currentIndex + 1} / {questions.length} 题</span>
          <span>已答对 {correctCount}</span>
        </div>
        <div className="h-1.5 bg-gray-100 dark:bg-slate-700 rounded-full overflow-hidden">
          <div
            className="h-full bg-primary-500 transition-all duration-300 rounded-full"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* 题干 */}
      <div className="text-center mb-8">
        <p className="text-sm text-gray-500 dark:text-gray-400 mb-3">请选择对应的答案</p>
        <div className="inline-flex flex-col items-center gap-1">
          <button
            onClick={handlePlayPrompt}
            className="text-5xl sm:text-6xl font-bold text-gray-800 dark:text-gray-100 hover:text-primary-600 dark:hover:text-primary-400 transition-colors px-6 py-3"
            title="点击朗读"
          >
            {question.prompt}
          </button>
          {question.promptRomaji && (
            <span className="text-sm text-gray-400">{question.promptRomaji}</span>
          )}
          <Volume2 className="w-4 h-4 text-gray-300 dark:text-gray-600" />
        </div>
      </div>

      {/* 选项 */}
      <div className="grid grid-cols-2 gap-3">
        {question.options.map((option) => {
          const isCorrect = option === question.answer;
          const isSelected = option === selected;
          return (
            <button
              key={option}
              onClick={() => handleSelect(option)}
              disabled={answered}
              className={cn(
                'relative py-4 px-3 rounded-2xl text-lg font-medium transition-all duration-200 border',
                !answered && 'bg-white dark:bg-slate-800 border-gray-100 dark:border-slate-700 hover:border-primary-300 dark:hover:border-primary-600 hover:shadow-md hover:-translate-y-0.5 text-gray-700 dark:text-gray-200',
                answered && isCorrect && 'bg-emerald-50 dark:bg-emerald-950/40 border-emerald-400 dark:border-emerald-600 text-emerald-700 dark:text-emerald-300',
                answered && isSelected && !isCorrect && 'bg-red-50 dark:bg-red-950/40 border-red-400 dark:border-red-600 text-red-700 dark:text-red-300',
                answered && !isCorrect && !isSelected && 'bg-white dark:bg-slate-800 border-gray-100 dark:border-slate-700 text-gray-400 dark:text-gray-500 opacity-60'
              )}
            >
              {option}
              {answered && isCorrect && (
                <Check className="absolute top-2 right-2 w-4 h-4 text-emerald-500" />
              )}
              {answered && isSelected && !isCorrect && (
                <X className="absolute top-2 right-2 w-4 h-4 text-red-500" />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}
