/**
 * 词汇替换引擎
 * 阶段一：英语优先，支持真实分词 + 词典映射
 * 其他语言：仅整句翻译，不做单词级替换
 */

import type { Language, PartOfSpeech, Difficulty } from '@/types';

export interface ReplacementResult {
  originalWord: string;
  replacementWord: string;
  position: number;
  length: number;
  partOfSpeech: PartOfSpeech;
  phonetic: string;
  translation: string;
  /** 日语替换词的假名注音（前向兼容，日语单词级替换启用后填充） */
  reading?: string;
}

export interface ReplacementOptions {
  ratio: number;          // 0.0 - 1.0
  posFilter: PartOfSpeech[];
  difficulty: Difficulty;
  language: Language;
  avoidDuplicates: boolean;
}

